def test_live_guard_uses_only_pass_single_wallet_candidates(tmp_path):
    profit_state = tmp_path / "profit_state.json"
    profit_state.write_text(
        json.dumps(
            {
                "best_runtime_candidate": {
                    "candidate_id": "multi",
                    "candidate_type": "MULTI_WALLET_INVENTORY",
                    "status": "PASS",
                    "policy": {"policy_id": "multi_policy"},
                },
                "forward_queue_runtime_candidates": [
                    {
                        "candidate_id": "single",
                        "candidate_type": "SINGLE_WALLET",
                        "status": "PASS",
                        "source_wallet": "0xabcdefabcdefabcdefabcdefabcdefabcdefabcd",
                        "policy": {"policy_id": "single_policy"},
                    }
                ],
            }
        )
    )
    args = SimpleNamespace(profit_state=str(profit_state), candidate_id="", source_wallet="")

    candidate, source_wallet, blockers = _load_live_guard_candidate(args)

    assert candidate["candidate_id"] == "single"
    assert source_wallet == "0xabcdefabcdefabcdefabcdefabcdefabcdefabcd"
    assert blockers == []


