def test_live_guard_c539_microprobe_status_passes_with_live_protection(monkeypatch):
    import scripts.run_wallet_copy_live_guard as guard

    wallet = "0xc5391c6dfda1174e456b1bc7e05eb9d0179673d1"
    monkeypatch.setattr(
        guard,
        "_candidate_live_protection_gate",
        lambda _candidate, *, now=None: {
            "passed": True,
            "failed_checks": [],
            "source_wallet": wallet,
        },
    )

    gate = guard._candidate_pass_gate(
        {
            "candidate_id": "deadman_microprobe_c5391c6dfd",
            "candidate_type": "SINGLE_WALLET",
            "source_wallet": wallet,
            "status": "FABLE_1912_DEADMAN_CORRECTED_MICROPROBE",
        },
        source_wallet_pin=wallet,
    )

    assert gate["passed"] is True
    assert gate["failed_checks"] == []
    assert gate["live_protection_gate"]["passed"] is True


def test_live_guard_c539_microprobe_status_still_requires_live_protection(monkeypatch):
    import scripts.run_wallet_copy_live_guard as guard

    wallet = "0xc5391c6dfda1174e456b1bc7e05eb9d0179673d1"
    monkeypatch.setattr(
        guard,
        "_candidate_live_protection_gate",
        lambda _candidate, *, now=None: {
            "passed": False,
            "failed_checks": ["shared_live_gate_external_liveness"],
            "source_wallet": wallet,
        },
    )

    gate = guard._candidate_pass_gate(
        {
            "candidate_id": "deadman_microprobe_c5391c6dfd",
            "candidate_type": "SINGLE_WALLET",
            "source_wallet": wallet,
            "status": "FABLE_1912_DEADMAN_CORRECTED_MICROPROBE",
        },
        source_wallet_pin=wallet,
    )

    assert gate["passed"] is False
    assert gate["failed_checks"] == ["shared_live_gate_external_liveness"]
    assert gate["live_protection_gate"]["passed"] is False


def test_live_guard_enabled_overlay_statuses_are_registered():
    import scripts.run_wallet_copy_live_guard as guard

    overlay = load_json(guard.AUTO_DEGRADE_ACTIVE_SET_STATE, default={})

    assert guard._unregistered_enabled_overlay_statuses(overlay) == []
    assert guard._live_status_registration_audit(overlay)["status"] == "PASS"
    assert not guard._candidate_status_live_admissible(
        {"status": "AUTO_DISABLED_CELL_FIRST_SLICE_BREACH"}
    )
    assert not guard._candidate_status_live_admissible(
        {"status": "DEMOTED_FABLE_SUBSTITUTE_ROTATION"}
    )
    assert all(
        registration.get("direction_id")
        and isinstance(registration.get("live_admissible"), bool)
        for registration in guard._FABLE_LIVE_STATUS_REGISTRY.values()
    )


def test_live_guard_unregistered_enabled_overlay_status_fails_registration_check():
    import scripts.run_wallet_copy_live_guard as guard

    overlay = {
        "members": [
            {
                "enabled": True,
                "status": "FUTURE_ADMISSION_STATUS_NOT_REGISTERED",
            },
            {
                "enabled": False,
                "status": "DISABLED_STATUS_NEEDS_NO_LIVE_REGISTRATION",
            },
        ]
    }

    assert guard._unregistered_enabled_overlay_statuses(overlay) == [
        "FUTURE_ADMISSION_STATUS_NOT_REGISTERED"
    ]
    audit = guard._live_status_registration_audit(overlay)
    assert audit["status"] == "UNREGISTERED_ENABLED_STATUS"
    assert audit["unregistered_enabled_statuses"] == [
        "FUTURE_ADMISSION_STATUS_NOT_REGISTERED"
    ]


