def test_live_guard_does_not_fallback_to_member_bar_when_active_set_empty(tmp_path):
    import scripts.run_wallet_copy_live_execution as live_execution

    profit_state = tmp_path / "profit_state.json"
    profit_state.write_text(json.dumps({}), encoding="utf-8")
    candidate_id = "active_set_member_2608ad88"
    wallet = "0x3725d52f3c252e8374999cc8617292ea2608ad88"
    policy_id = "member_bar_0.10_cap_8_le_25_all_window"
    args = SimpleNamespace(
        profit_state=str(profit_state),
        candidate_id=candidate_id,
        source_wallet=wallet,
        policy_id=policy_id,
        active_set_temporal_now_iso="2026-07-13T12:00:00Z",
    )

    candidate, source_wallet, blockers = _load_live_guard_candidate(args)
    direct_candidate = live_execution._mission_active_member_candidate(
        candidate_id_pin=candidate_id,
        source_wallet_pin=wallet,
        policy_id_pin=policy_id,
    )

    assert "live_guard_candidate_not_pass" in blockers
    assert "live_guard_pinned_candidate_missing" in blockers
    assert source_wallet == wallet
    assert candidate["candidate_id"] == candidate_id
    assert candidate["status"] == "PINNED_CANDIDATE_MISSING_FROM_PROFIT_STATE"
    assert direct_candidate == {}


