def test_active_set_runtime_args_member_max_price_cannot_loosen_guard_cap(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    wallet = "0x59603775762a631d4bcd156980c0a174bbc4c2d2"

    def _active_set_with_max_price(max_price: float) -> dict:
        return {
            "mode": "active_set_single_guard",
            "status": "ACTIVE",
            "target_member_count_max": 1,
            "members": [
                {
                    "candidate_id": "leaderboard_crypto_5960377576",
                    "candidate_type": "SINGLE_WALLET",
                    "source_wallet": wallet,
                    "enabled": True,
                    "policy_id": "legacy_roster_policy",
                    "wallet_fraction": 0.1,
                    "max_order_usd": 8.0,
                    "max_price": max_price,
                    "policy": {
                        "policy_id": "legacy_roster_policy",
                        "wallet_fraction": 0.1,
                        "max_order_usd": 8.0,
                        "max_price": max_price,
                    },
                }
            ],
        }

    def _base_args() -> SimpleNamespace:
        return SimpleNamespace(
            active_set=True,
            active_set_member_limit=0,
            candidate_id="",
            source_wallet="",
            policy_id="",
            inventory_late_window_stop_s=60.0,
            min_live_order_usd=1.0,
            price_band_decision_max_price=0.50,
            active_set_temporal_now_iso="2026-07-11T20:00:00+00:00",
        )

    monkeypatch.setattr(guard, "AUTO_DEGRADE_ACTIVE_SET_STATE", tmp_path / "missing_overlay.json")
    monkeypatch.setattr(guard, "_active_live_set_is_empty", lambda active_set=None: False)
    monkeypatch.setattr(
        guard,
        "_apply_temporal_slice_exclusions",
        lambda members, **kwargs: (members, {"included_count": len(members), "excluded_count": 0}),
    )

    # Friday-golden weekday behavior keeps the 0.50 ceiling unless a narrower cap is explicit.
    monkeypatch.setattr(guard, "_active_live_set_contract", lambda *, now=None: _active_set_with_max_price(0.50))
    runtime_args, _ = guard._active_set_runtime_args(_base_args(), cycle=1)
    assert runtime_args.price_band_decision_max_price == 0.50
    assert runtime_args.active_set_selected_member_policy["max_price"] == 0.50

    # A tighter member policy still tightens the runtime cap.
    monkeypatch.setattr(guard, "_active_live_set_contract", lambda *, now=None: _active_set_with_max_price(0.25))
    runtime_args, _ = guard._active_set_runtime_args(_base_args(), cycle=1)
    assert runtime_args.price_band_decision_max_price == 0.25

    digest = tmp_path / "state_digest.json"
    digest.write_text(
        json.dumps(
            {
                "defense_tripwires": {
                    "t1_day_pnl_usd": 0.0,
                }
            }
        ),
        encoding="utf-8",
    )
    a689_active_set = {
        "mode": "active_set_single_guard",
        "status": "ACTIVE",
        "target_member_count_max": 1,
        "members": [
            {
                "candidate_id": "runtime_auto_degrade_a6896d11f7",
                "candidate_type": "SINGLE_WALLET",
                "source_wallet": guard._A689_CANARY_WALLET,
                "enabled": True,
                "policy_id": guard._A689_CANARY_POLICY_ID,
                "wallet_fraction": 0.1,
                "max_order_usd": 2.0,
                "max_price": 0.7,
                "policy": {
                    "policy_id": guard._A689_CANARY_POLICY_ID,
                    "wallet_fraction": 0.1,
                    "max_order_usd": 2.0,
                    "max_price": 0.7,
                },
            }
        ],
    }
    a689_args = _base_args()
    a689_args.state_digest_json = str(digest)
    monkeypatch.setattr(guard, "_active_live_set_contract", lambda *, now=None: a689_active_set)
    runtime_args, _ = guard._active_set_runtime_args(a689_args, cycle=1)
    assert runtime_args.price_band_decision_max_price == 0.7
    assert runtime_args.active_set_selected_member_policy["max_price"] == 0.7
    assert (
        runtime_args.active_set_selected_member_policy["a689_canary_price_carveout"]["status"]
        == "A689_CANARY_PRICE_BAND_CARVEOUT"
    )


def test_active_set_all_runtime_member_probe_flag_evaluates_every_non_selected_member(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    selected_wallet = "0x1111111111111111111111111111111111111111"
    first_probe_wallet = "0x2222222222222222222222222222222222222222"
    second_probe_wallet = "0x3333333333333333333333333333333333333333"
    active_set_runtime = {
        "selected_member": {"candidate_id": "selected", "source_wallet": selected_wallet},
        "members": [
            {"candidate_id": "selected", "source_wallet": selected_wallet},
            {"candidate_id": "first_probe", "source_wallet": first_probe_wallet},
            {"candidate_id": "second_probe", "source_wallet": second_probe_wallet},
        ],
    }
    calls: list[tuple[str, bool, bool, str, str]] = []

    def _fake_run_fused_live_execution(args, *, candidate_id: str) -> dict:
        calls.append(
            (
                candidate_id,
                bool(args.execute_live),
                bool(args.live_orders_allowed),
                str(args.live_arm_state),
                str(args.selected_candidate_override_state),
            )
        )
        return {
            "returncode": 0,
            "stdout_json": {
                "status": "LIVE_ARMED_NO_FRESH_INTENTS",
                "candidate_intent_summary": {
                    "fresh_candidate_intents": 0,
                    "fresh_candidate_intents_after_toxicity_protection": 0,
                    "fresh_candidate_intents_after_expected_fee_gate": 0,
                },
            },
        }

    monkeypatch.setattr(guard, "ROOT", tmp_path)
    monkeypatch.setattr(guard, "_run_fused_live_execution", _fake_run_fused_live_execution)
    args = SimpleNamespace(
        active_set_live_execution_probes=True,
        active_set_live_execution_probe_max_members=1,
        active_set_evaluate_all_runtime_members_per_cycle=True,
        live_ledger_event_log=str(tmp_path / "live-events.jsonl"),
        execute_live=True,
        explicit_live_operator_go=True,
        live_orders_allowed=True,
    )

    result = guard._run_active_set_live_execution_probes(
        args,
        active_set_runtime=active_set_runtime,
        dataapi_poll_result={},
    )

    assert result["evaluation_mode"] == "all_runtime_members_per_cycle"
    assert result["all_runtime_members_per_cycle"] is True
    assert result["runtime_member_count"] == 3
    assert result["probed_members"] == 2
    assert [call[0] for call in calls] == ["first_probe", "second_probe"]
    assert all(call[1] is False and call[2] is False for call in calls)
    assert all("wallet_copy_live_execution_probe_" in call[3] for call in calls)
    overrides = [json.loads(Path(call[4]).read_text()) for call in calls]
    assert [payload["candidate"]["candidate_id"] for payload in overrides] == ["first_probe", "second_probe"]
    assert [payload["candidate"]["source_wallet"] for payload in overrides] == [
        first_probe_wallet,
        second_probe_wallet,
    ]
    assert all(payload["candidate"]["live_target_profile"]["status"] == "PASS" for payload in overrides)


