def test_live_execution_probe_eval_all_round_robin_cap_keeps_force_wallet(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    selected_wallet = "0x1111111111111111111111111111111111111111"
    probe_wallets = [f"0x{idx:040x}" for idx in range(2, 10)]
    active_set_runtime = {
        "selected_member": {"candidate_id": "selected", "source_wallet": selected_wallet},
        "members": [{"candidate_id": "selected", "source_wallet": selected_wallet}]
        + [
            {"candidate_id": f"probe_{idx}", "source_wallet": wallet}
            for idx, wallet in enumerate(probe_wallets, start=1)
        ],
    }
    calls: list[str] = []

    def _fake_run_fused_live_execution(args, *, candidate_id: str) -> dict:
        calls.append(candidate_id)
        return {
            "returncode": 0,
            "stdout_json": {
                "status": "LIVE_ARMED_NO_FRESH_INTENTS",
                "candidate_intent_summary": {
                    "fresh_candidate_intents": 0,
                    "fresh_candidate_intents_after_toxicity_protection": 0,
                    "fresh_candidate_intents_after_expected_fee_gate": 0,
                },
            },
        }

    monkeypatch.setattr(guard, "ROOT", tmp_path)
    monkeypatch.setattr(guard, "_run_fused_live_execution", _fake_run_fused_live_execution)
    args = SimpleNamespace(
        active_set_live_execution_probes=True,
        active_set_live_execution_probe_max_members=1,
        active_set_evaluate_all_runtime_members_per_cycle=True,
        live_ledger_event_log=str(tmp_path / "live-events.jsonl"),
        rtds_watermark_state=str(tmp_path / "missing_watermarks.json"),
        execute_live=True,
        explicit_live_operator_go=True,
        live_orders_allowed=True,
    )

    first = guard._run_active_set_live_execution_probes(
        args,
        active_set_runtime=active_set_runtime,
        dataapi_poll_result={},
        max_members_override=3,
        include_all_runtime_members_override=True,
        round_robin_offset=0,
    )
    second = guard._run_active_set_live_execution_probes(
        args,
        active_set_runtime=active_set_runtime,
        dataapi_poll_result={},
        max_members_override=3,
        include_all_runtime_members_override=True,
        round_robin_offset=3,
    )
    forced = guard._run_active_set_live_execution_probes(
        args,
        active_set_runtime=active_set_runtime,
        dataapi_poll_result={},
        force_wallets={probe_wallets[-1]},
        max_members_override=0,
        include_all_runtime_members_override=False,
    )

    assert [row["candidate_id"] for row in first["rows"]] == ["probe_1", "probe_2", "probe_3"]
    assert [row["candidate_id"] for row in second["rows"]] == ["probe_4", "probe_5", "probe_6"]
    assert [row["candidate_id"] for row in forced["rows"]] == ["probe_8"]
    assert first["member_cap"] == 3
    assert second["round_robin_offset"] == 3
    assert forced["probed_members_this_cycle"] == 1
    assert calls == [
        "probe_1",
        "probe_2",
        "probe_3",
        "probe_4",
        "probe_5",
        "probe_6",
        "probe_8",
    ]


