def test_live_guard_activation_not_before_holds_restart_payload_until_due():
    import scripts.run_wallet_copy_live_guard as guard

    member = {
        "candidate_id": "cohort_alive_admit_f418d3a1",
        "source_wallet": "0xf418d3a1a941292f9c8707d62a14980c5beb95a3",
        "enabled": True,
        "status": "FABLE_1232_COHORT_ALIVE_ADMISSION_WIRED_FOR_SINGLE_POST_13Z_RESTART",
        "activate_not_before_utc": "2026-07-14T13:00:00Z",
    }
    before_due = datetime(2026, 7, 14, 12, 59, 59, tzinfo=timezone.utc)
    due = datetime(2026, 7, 14, 13, 0, 0, tzinfo=timezone.utc)

    held = guard._normalize_active_set_member_runtime(member, now=before_due)

    assert held["enabled"] is False
    assert held["status"] == "PENDING_ACTIVATION_NOT_BEFORE_UTC"
    assert held["activation_not_before_gate"]["held"] is True
    assert guard._active_set_member_is_disabled(member, now=before_due) is True
    assert guard._active_set_member_is_disabled(held, now=before_due) is True

    active = guard._normalize_active_set_member_runtime(member, now=due)

    assert active["enabled"] is True
    assert active["status"] == "FABLE_1232_COHORT_ALIVE_ADMISSION_WIRED_FOR_SINGLE_POST_13Z_RESTART"
    assert active["activation_not_before_gate"]["held"] is False
    assert guard._active_set_member_is_disabled(active, now=due) is False


