def test_live_guard_scoped_admissions_fail_closed_without_venue_authority():
    import scripts.run_wallet_copy_live_guard as guard

    stale = {
        "status": "ACTIVE",
        "direction_id": "2026-07-28T07:55Z-OP-TOMORROW",
        "move_slice_keys": ["120-180|>0.75"],
        "admitted_bands": [
            {
                "move_slice_key": "120-180|>0.75",
                "fixed_policy_full_stream_rescore": {
                    "f1_pass": True,
                    "resolved": 320,
                    "post_fee_pnl_usd": 15.5,
                    "roi_pct": 4.8,
                    "first_half_post_fee_pnl_usd": 8.0,
                    "second_half_post_fee_pnl_usd": 7.5,
                },
            }
        ],
    }
    band = guard._band_scoped_admission_override(
        {
            "policy": {"move_slice_keys": ["120-180|>0.75"]},
            "band_scoped_admission": stale,
        }
    )
    cell = guard._cell_scoped_admission_override(
        {
            "policy": {"move_slice_keys": ["120-180|>0.75"]},
            "cell_scoped_admission": {
                **stale,
                "fixed_policy_full_stream_rescore": stale["admitted_bands"][0][
                    "fixed_policy_full_stream_rescore"
                ],
            },
        }
    )

    assert band["valid"] is False
    assert band["reason"] == "venue_authority_missing_stale_artifact"
    assert cell["valid"] is False
    assert cell["reason"] == "venue_authority_missing_stale_artifact"


