def test_live_guard_monday_boundary_auto_returns_weekend_bench_and_temporal_gates(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    weekday_benched = "0xe6db20932faf0f9780acf75d95c74c9984407dac"
    weekend_only = "0xac0586732786905d285959613f1813bc89246729"
