def test_live_guard_caches_unchanged_auto_degrade_overlay(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    overlay_state = tmp_path / "auto_degrade.json"
    overlay_state.write_text('{"members": []}', encoding="utf-8")
    monkeypatch.setattr(guard, "AUTO_DEGRADE_ACTIVE_SET_STATE", overlay_state)
    monkeypatch.setattr(guard, "_AUTO_DEGRADE_OVERLAY_CACHE", None)
    original_load_json = guard.load_json
    calls = 0
    cache_readonly_values = []

    def counted_load_json(*args, **kwargs):
        nonlocal calls
        calls += 1
        cache_readonly_values.append(kwargs.get("cache_readonly"))
        return original_load_json(*args, **kwargs)

    monkeypatch.setattr(guard, "load_json", counted_load_json)

    first = guard._load_auto_degrade_active_set_overlay()
    second = guard._load_auto_degrade_active_set_overlay()
    assert second is first
    assert calls == 1

    overlay_state.write_text('{"members": [], "generation": 2}', encoding="utf-8")
    third = guard._load_auto_degrade_active_set_overlay()
    assert third is not first
    assert calls == 2
    assert cache_readonly_values == [False, False]


