def test_live_guard_zero_fresh_poll_skips_stale_latest_auto_degrade_admission(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    state_path = tmp_path / "data/research/wallet_copy_active_set_dataapi_poller_state.json"
    overlay_path = tmp_path / "data/research/wallet_copy_active_set_auto_degrade_state.json"
    state_path.parent.mkdir(parents=True, exist_ok=True)
    latest_wallet = "0xa95b27b0626973f7bc7600e65cd88cd7b42d0d14"
    stale_wallet = "0xac0586732786905d285959613f1813bc89246729"
    state_path.write_text(
        json.dumps(
            {
                "summary": {"fresh_poll_only_signals": 0},
                "fetch_meta": {
                    stale_wallet: {"freshest_buy_lag_s_by_source": {"data_api": 10.0}},
                    latest_wallet: {"freshest_buy_lag_s_by_source": {"data_api": 120.0}},
                },
            }
        ),
        encoding="utf-8",
    )
    overlay_path.write_text(
        json.dumps(
            {
                "latest_admission": {
                    "candidate_id": "auto_degrade_a95b27b062",
                    "source_wallet": latest_wallet,
                    "status": "AUTO_DEGRADE_PROTECTION_BOUNDED",
                    "enabled": True,
                }
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setattr(guard, "ROOT", tmp_path)
    monkeypatch.setattr(guard, "AUTO_DEGRADE_ACTIVE_SET_STATE", overlay_path)

    selected_index, selection = guard._fresh_runtime_member_selection_index(
        [
            {"candidate_id": "stale", "source_wallet": stale_wallet},
            {"candidate_id": "latest", "source_wallet": latest_wallet},
        ],
        SimpleNamespace(active_set_dataapi_poller_state=str(state_path)),
    )

    assert selected_index == 0
    assert selection["reason"] == "runtime_member_freshest_buy_lag_fallback"
    assert selection["selected_wallet"] == stale_wallet
    assert selection["latest_admission_priority"]["skipped"] is True
    assert selection["latest_admission_priority"]["freshest_buy_lag_s"] == 120.0


