def test_live_guard_same_cycle_promotes_after_fee_probe_and_respects_freeze(monkeypatch):
    import scripts.run_wallet_copy_live_guard as guard

    promoted_wallet = "0x1111111111111111111111111111111111111111"
    frozen_wallet = "0x2222222222222222222222222222222222222222"
    selected_wallet = "0x3333333333333333333333333333333333333333"
    active_set_runtime = {
        "selected_member": {"candidate_id": "selected", "source_wallet": selected_wallet},
        "members": [
            {"candidate_id": "promoted_candidate", "source_wallet": promoted_wallet},
            {"candidate_id": "frozen_candidate", "source_wallet": frozen_wallet},
            {"candidate_id": "selected", "source_wallet": selected_wallet},
        ],
    }
    live_probe_result = {
        "enabled": True,
        "rows": [
            {
                "candidate_id": "frozen_candidate",
                "source_wallet": frozen_wallet,
                "fresh_candidate_intents_after_expected_fee_gate": 2,
            },
            {
                "candidate_id": "promoted_candidate",
                "source_wallet": promoted_wallet,
                "fresh_candidate_intents_after_expected_fee_gate": 1,
            },
        ],
    }
    calls = []

    def fake_live_execution(args, *, candidate_id):
        calls.append(candidate_id)
        return {
            "returncode": 0,
            "execution_mode": "unit",
            "duration_s": 0.01,
            "stdout_json": {
                "status": "LIVE_EXECUTION_SUBMITTED",
                "orders_submitted": 1,
                "orders_accepted": 1,
                "orders_rejected": 0,
                "candidate_intent_summary": {
                    "fresh_candidate_intents": 1,
                    "fresh_candidate_intents_after_toxicity_protection": 1,
                    "fresh_candidate_intents_after_expected_fee_gate": 1,
                },
            },
        }

    monkeypatch.setattr(guard, "_run_fused_live_execution", fake_live_execution)
    monkeypatch.setattr(
        guard,
        "_active_set_selection_priority_freeze",
        lambda wallets: {"enabled": True, "wallets": [frozen_wallet], "rows": []},
    )

    result = guard._run_active_set_live_execution_probe_promotions(
        SimpleNamespace(execute_live=True, live_orders_allowed=True),
        active_set_runtime=active_set_runtime,
        live_probe_result=live_probe_result,
    )

    assert calls == ["promoted_candidate"]
    assert result["promoted_members"] == 1
    assert result["rows"][0]["orders_accepted"] == 1
    assert result["skipped"][0]["reason"] == "selection_priority_frozen"


def test_live_guard_probes_shadow_candidate_seats_without_spending_runtime_probe_budget(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    selected_wallet = "0x1111111111111111111111111111111111111111"
    runtime_wallet = "0x2222222222222222222222222222222222222222"
    shadow_wallet = "0x3333333333333333333333333333333333333333"
    calls = []

    def fake_live_execution(args, *, candidate_id):
        calls.append(
            {
                "candidate_id": candidate_id,
                "execute_live": args.execute_live,
                "live_orders_allowed": args.live_orders_allowed,
                "live_arm_state": args.live_arm_state,
            }
        )
        return {
            "returncode": 0,
            "stdout_json": {
                "status": "LIVE_ARMED_NO_FRESH_INTENTS",
                "candidate_intent_summary": {
                    "fresh_candidate_intents": 0,
                    "fresh_candidate_intents_after_toxicity_protection": 0,
                    "fresh_candidate_intents_after_expected_fee_gate": 0,
                },
            },
        }

    monkeypatch.setattr(guard, "_run_fused_live_execution", fake_live_execution)

    result = guard._run_active_set_live_execution_probes(
        SimpleNamespace(
            active_set_live_execution_probes=True,
            active_set_live_execution_probe_max_members=1,
            rtds_watermark_state=str(tmp_path / "missing_watermarks.json"),
        ),
        active_set_runtime={
            "selected_member": {"source_wallet": selected_wallet},
            "members": [
                {"candidate_id": "selected", "source_wallet": selected_wallet},
                {"candidate_id": "runtime_probe", "source_wallet": runtime_wallet},
            ],
        },
        dataapi_poll_result={
            "fetch_meta": {
                runtime_wallet: {"policy_compatible_fresh_buy_rows_le_30s": 1},
            }
        },
        shadow_candidate_members=[
            {
                "candidate_id": "shadow_probe",
                "source_wallet": shadow_wallet,
                "shadow_only": True,
                "live_orders_allowed": False,
            }
        ],
    )

    assert [call["candidate_id"] for call in calls] == ["shadow_probe", "runtime_probe"]
    assert all(call["execute_live"] is False for call in calls)
    assert all(call["live_orders_allowed"] is False for call in calls)
    assert result["probed_members"] == 2
    assert result["shadow_candidate_seat_wallets"] == [shadow_wallet]
    assert result["rows"][0]["source_wallet"] == shadow_wallet


