def test_live_guard_selection_pin_can_select_temporal_unproven_member(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    pinned_wallet = "0x2222222222222222222222222222222222222222"
    proven_wallet = "0x1111111111111111111111111111111111111111"
    active_set = {
        "status": "ACTIVE",
        "mode": "active_set_single_guard",
        "target_member_count_max": 2,
        "members": [
            {"candidate_id": "proven", "source_wallet": proven_wallet, "policy_id": "policy_proven"},
            {"candidate_id": "pinned", "source_wallet": pinned_wallet, "policy_id": "policy_pinned"},
        ],
    }
    poller_state = tmp_path / "active_set_poller.json"
    poller_state.write_text(json.dumps({"fetch_meta": {}, "summary": {"fresh_poll_only_signals": 0}}), encoding="utf-8")

    def temporal_with_unproven_pin(members, *, profiles=None, now=None):
        rows = []
        for member in members:
            row = dict(member)
            wallet = str(row.get("source_wallet") or "").lower()
            row["temporal_slice_evaluation"] = {
                "excluded": False,
                "reason": "no_active_temporal_slice_proven_negative",
                "evaluated_slices": [
                    {
                        "slice": "weekend",
                        "label": "UNPROVEN" if wallet == pinned_wallet else "PROVEN-POSITIVE",
                    }
                ],
            }
            rows.append(row)
        return rows, {"enabled": True, "excluded_count": 0, "excluded_members": [], "excluded_wallets": []}

    monkeypatch.setattr(guard, "_active_live_set_contract", lambda *, now=None: active_set)
    monkeypatch.setattr(guard, "_active_live_set_is_empty", lambda active_set=None: False)
    monkeypatch.setattr(guard, "_apply_temporal_slice_exclusions", temporal_with_unproven_pin)
    monkeypatch.setattr(
        guard,
        "_load_auto_degrade_active_set_overlay",
        lambda: {
            "selection_pin": {
                "enabled": True,
                "pin_id": "unit-pin-temporal-unproven",
                "source_wallet": pinned_wallet,
                "created_at": guard.dt.datetime.now(guard.dt.timezone.utc).isoformat(),
                "reason": "unit_test_pin_temporal_unproven",
            }
        },
    )
    base_args = SimpleNamespace(
        active_set=True,
        active_set_member_limit=0,
        candidate_id="",
        source_wallet="",
        policy_id="",
        inventory_late_window_stop_s=60.0,
        active_set_dataapi_poller_state=str(poller_state),
        live_ledger_state=str(tmp_path / "empty_live_ledger.json"),
    )

    runtime_args, active_set_runtime = guard._active_set_runtime_args(base_args, cycle=1)

    assert runtime_args.candidate_id == "pinned"
    assert runtime_args.source_wallet == pinned_wallet
    assert active_set_runtime["selection_mode"] == "selection_pin_single_guard"
    selection = active_set_runtime["fresh_runtime_member_selection"]
    assert selection["reason"] == "runtime_member_selection_pin"
    assert selection["temporal_unproven_override"]["source_wallet"] == pinned_wallet
    assert active_set_runtime["selected_member"]["source_wallet"] == pinned_wallet


