def test_live_guard_selection_pin_expiry_tracks_sliding_quiet_clock_anchor(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    a689 = guard._A689_CANARY_WALLET
    overlay_path = tmp_path / "wallet_copy_active_set_auto_degrade_state.json"
    live_execution_path = tmp_path / "wallet_copy_live_execution_state.json"
    now = guard.dt.datetime.now(guard.dt.timezone.utc)
    old_anchor = now - guard.dt.timedelta(hours=5)
    old_fire = old_anchor + guard.dt.timedelta(hours=4)
    latest_submit = now - guard.dt.timedelta(minutes=10)
    new_fire = latest_submit + guard.dt.timedelta(hours=4)
    overlay_path.write_text(
        json.dumps(
            {
                "members": [
                    {"candidate_id": "a689", "source_wallet": a689, "policy_id": guard._A689_CANARY_POLICY_ID}
                ],
                "selection_pin": {
                    "enabled": True,
                    "pin_id": "weekend-seat-loss-f418-to-a689",
                    "direction_id": guard._WEEKEND_SEAT_LOSS_RIDER_DIRECTION_ID,
                    "created_at": (now - guard.dt.timedelta(hours=2)).isoformat(),
                    "expires_at": guard._utc_iso(old_fire),
                    "candidate_id": "a689",
                    "source_wallet": a689,
                    "quiet_clock": {
                        "anchor_iso": guard._utc_iso(old_anchor),
                        "earliest_fire_iso": guard._utc_iso(old_fire),
                        "reset_predicate": "selected_submit_eligible_copyintent",
                    },
                },
            }
        ),
        encoding="utf-8",
    )
    live_execution_path.write_text(
        json.dumps(
            {
                "orders": [
                    {
                        "order_id": "order-a689-latest",
                        "intent_id": "intent-a689-latest",
                        "source_wallet": a689,
                        "status": "LIVE_SUBMITTED",
                        "final_status": "FILLED",
                        "updated_at": guard._utc_iso(latest_submit),
                        "market_slug": "btc-updown-5m-unit",
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setattr(guard, "AUTO_DEGRADE_ACTIVE_SET_STATE", overlay_path)
    monkeypatch.setattr(guard, "WALLET_COPY_LIVE_EXECUTION_STATE", live_execution_path)

    result = guard._active_set_selection_pin({a689})

    assert result["wallet"] == a689
    assert result["expires_at"] == guard._utc_iso(new_fire)
    assert result["quiet_clock_expiry_refresh"]["status"] == "PIN_EXPIRED_BEFORE_QUIET_CLOCK_FIRE_REPAIRED"
    updated = json.loads(overlay_path.read_text(encoding="utf-8"))
    assert updated["selection_pin"]["expires_at"] == guard._utc_iso(new_fire)
    assert updated["selection_pin"]["quiet_clock"]["anchor_iso"] == guard._utc_iso(latest_submit)
    assert updated["selection_pin"]["quiet_clock_expiry_derived"] is True
    assert updated["selection_pin_quiet_clock_expiry_refresh"]["drift_signature"] == "PIN_EXPIRED_BEFORE_QUIET_CLOCK_FIRE"


def test_live_guard_stale_overlay_write_preserves_newer_mechanical_demotion():
    import scripts.run_wallet_copy_live_guard as guard

    target = "0x" + "33" * 20
    demotion = {
        "status": "APPLIED",
        "target_wallet": target,
        "generated_at": "2026-07-26T19:05:18Z",
        "direction_id": "fable-first-loss",
        "reason": "FIRST_CANONICAL_NEGATIVE_RESOLUTION_UNDER_DIRECT_PIN",
        "target_status": "AUTO_DISABLED_CELL_FIRST_SLICE_BREACH",
    }
    current = {
        "members": [
            {
                "candidate_id": "direct-target",
                "source_wallet": target,
                "enabled": False,
                "status": "DEMOTED_FABLE_SUBSTITUTE_ROTATION",
            }
        ],
        "selection_pin": {
            "candidate_id": "direct-target",
            "source_wallet": target,
            "enabled": False,
        },
        "latest_mechanical_temporal_loss_demotion": demotion,
    }
    stale = {
        "updated_at": "2026-07-26T19:04:30Z",
        "members": [
            {
                "candidate_id": "direct-target",
                "source_wallet": target,
                "enabled": True,
                "status": "POLICY_CHOKE_RUNG_DIRECT_EMERGENCY_ADMISSION",
            }
        ],
        "selection_pin": {
            "candidate_id": "direct-target",
            "source_wallet": target,
            "enabled": True,
        },
    }

    fenced, report = guard._fence_latest_mechanical_demotion(stale, current=current)

    assert report["status"] == "STALE_OVERLAY_WRITE_FENCED"
    assert fenced["members"][0]["enabled"] is False
    assert fenced["members"][0]["status"] == "AUTO_DISABLED_CELL_FIRST_SLICE_BREACH"
    assert fenced["selection_pin"]["enabled"] is False
    assert fenced["latest_mechanical_temporal_loss_demotion"] == demotion


