def test_live_guard_hot_reloads_mission_contract_on_mtime_change(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    mission_path = tmp_path / "mission.py"
    config_path = tmp_path / "wallet_copy_config_generation.json"

    def write_mission(version: int) -> None:
        mission_path.write_text(
            "\n".join(
                [
                    "from copy import deepcopy",
                    f"WALLET_COPY_MISSION_CONTRACT = {{'schema_version': {version}, 'current_runtime_phase_contract': {{}}}}",
                    "def mission_contract():",
                    "    return deepcopy(WALLET_COPY_MISSION_CONTRACT)",
                    "",
                ]
            ),
            encoding="utf-8",
        )
        os.utime(mission_path, ns=(version * 1_000_000_000, version * 1_000_000_000))

    write_mission(1)
    config_path.write_text("{}", encoding="utf-8")
    monkeypatch.setattr(guard, "MISSION_CONTRACT_PATH", mission_path)
    monkeypatch.setattr(guard, "CONFIG_GENERATION_PATH", config_path)
    monkeypatch.setattr(
        guard,
        "_MISSION_HOT_RELOAD_STATE",
        {
            "mission_mtime_ns": None,
            "config_generation_mtime_ns": None,
            "reload_count": 0,
            "last_status": "UNINITIALIZED",
        },
    )
    monkeypatch.setattr(
        guard,
        "mission_contract",
        lambda: {"schema_version": 1, "current_runtime_phase_contract": {}},
    )

    initialized = guard._mission_contract_hot_reload_check(cycle=1)
    write_mission(2)
    reloaded = guard._mission_contract_hot_reload_check(cycle=2)

    assert initialized["status"] == "INITIALIZED"
    assert reloaded["status"] == "RELOADED"
    assert reloaded["reloaded"] is True
    assert reloaded["schema_version"] == 2
    assert guard.mission_contract()["schema_version"] == 2


def test_live_guard_active_set_selected_override_precedes_profit_state_fallthrough(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    bad_wallet = "0x1111111111111111111111111111111111111111"
    good_wallet = "0x2222222222222222222222222222222222222222"
    active_set = {
        "status": "ACTIVE",
        "mode": "active_set_single_guard",
        "target_member_count_max": 2,
        "members": [
            {
                "candidate_id": "queue_backfill_bad",
                "candidate_type": "SINGLE_WALLET",
                "source_wallet": bad_wallet,
                "policy_id": "policy_bad",
            },
            {
                "candidate_id": "active_member_good",
                "candidate_type": "SINGLE_WALLET",
                "source_wallet": good_wallet,
                "policy_id": "policy_good",
            },
        ],
    }
    monkeypatch.setattr(guard, "_active_live_set_contract", lambda *, now=None: active_set)
    monkeypatch.setattr(guard, "_active_live_set_is_empty", lambda active_set=None: False)
    profit_state = tmp_path / "profit_state.json"
    profit_state.write_text(
        json.dumps(
            {
                "forward_queue_runtime_candidates": [
                    {
                        "candidate_id": "queue_backfill_bad",
                        "candidate_type": "SINGLE_WALLET",
                        "status": "BLOCKED",
                        "source_wallet": bad_wallet,
                        "policy": {"policy_id": "policy_bad"},
                    },
                    {
                        "candidate_id": "active_member_good",
                        "candidate_type": "SINGLE_WALLET",
                        "status": "PASS",
                        "source_wallet": good_wallet,
                        "policy": {"policy_id": "policy_good"},
                    },
                ]
            }
        ),
        encoding="utf-8",
    )
    base_args = SimpleNamespace(
        active_set=True,
        active_set_member_limit=0,
        candidate_id="",
        source_wallet="",
        policy_id="",
        profit_state=str(profit_state),
        promotion_rotation_state=str(tmp_path / "promotion_rotation_state.json"),
        inventory_late_window_stop_s=60.0,
    )

    runtime_args, active_set_runtime = guard._active_set_runtime_args(base_args, cycle=1)
    candidate, source_wallet, blockers = guard._load_candidate(runtime_args)

    assert active_set_runtime["selected_member"]["candidate_id"] == "queue_backfill_bad"
    assert runtime_args.active_set_fallthrough_members[1]["candidate_id"] == "active_member_good"
    assert candidate["candidate_id"] == "queue_backfill_bad"
    assert candidate["status"] == "PASS"
    assert candidate["metadata"]["active_set_member_status"] == "BLOCKED"
    assert source_wallet == bad_wallet
    assert blockers == []
    assert candidate["guard_fallthrough"]["applied"] is False
    assert candidate["guard_pass_gate"]["passed"] is True
    assert candidate["guard_selection_attempts"][0]["blockers"] == []
    assert candidate["guard_selection_attempts"][0]["pass_gate"]["failed_checks"] == []
    diagnostics = guard._candidate_pass_gate_diagnostics(candidate, blockers)
    assert diagnostics["selected_passed"] is True
    assert diagnostics["failed_check_counts"] == {}
    assert diagnostics["blocker_counts"] == {}
    assert diagnostics["first_passing_attempt"]["candidate_id"] == "queue_backfill_bad"
    assert diagnostics["fallthrough"]["applied"] is False


def test_live_guard_active_set_selected_override_bridges_when_profit_candidates_do_not_pass(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    first_wallet = "0x3333333333333333333333333333333333333333"
    second_wallet = "0x4444444444444444444444444444444444444444"
    active_set = {
        "status": "ACTIVE",
        "mode": "active_set_single_guard",
        "target_member_count_max": 2,
        "members": [
            {
                "candidate_id": "active_member_blocked_a",
                "candidate_type": "SINGLE_WALLET",
                "source_wallet": first_wallet,
                "policy_id": "policy_a",
            },
            {
                "candidate_id": "active_member_blocked_b",
                "candidate_type": "SINGLE_WALLET",
                "source_wallet": second_wallet,
                "policy_id": "policy_b",
            },
        ],
    }
    monkeypatch.setattr(guard, "_active_live_set_contract", lambda *, now=None: active_set)
    monkeypatch.setattr(guard, "_active_live_set_is_empty", lambda active_set=None: False)
    profit_state = tmp_path / "profit_state.json"
    profit_state.write_text(
        json.dumps(
            {
                "forward_queue_runtime_candidates": [
                    {
                        "candidate_id": "active_member_blocked_a",
                        "candidate_type": "SINGLE_WALLET",
                        "status": "BLOCKED",
                        "source_wallet": first_wallet,
                        "policy": {"policy_id": "policy_a"},
                    },
                    {
                        "candidate_id": "active_member_blocked_b",
                        "candidate_type": "SINGLE_WALLET",
                        "status": "PENDING",
                        "source_wallet": second_wallet,
                        "policy": {"policy_id": "policy_b"},
                    },
                ]
            }
        ),
        encoding="utf-8",
    )
    base_args = SimpleNamespace(
        active_set=True,
        active_set_member_limit=0,
        candidate_id="",
        source_wallet="",
        policy_id="",
        profit_state=str(profit_state),
        promotion_rotation_state=str(tmp_path / "promotion_rotation_state.json"),
        inventory_late_window_stop_s=60.0,
    )

    runtime_args, active_set_runtime = guard._active_set_runtime_args(base_args, cycle=1)
    candidate, source_wallet, blockers = guard._load_candidate(runtime_args)

    assert active_set_runtime["selected_member"]["candidate_id"] == "active_member_blocked_a"
    assert candidate["candidate_id"] == "active_member_blocked_a"
    assert source_wallet == first_wallet
    assert candidate["status"] == "PASS"
    assert candidate["metadata"]["active_set_member_status"] == "BLOCKED"
    assert blockers == []
    assert candidate["guard_pass_gate"]["passed"] is True
    assert candidate["guard_pass_gate"]["failed_checks"] == []
    assert candidate["guard_fallthrough"]["applied"] is False
    assert [attempt["candidate_id"] for attempt in candidate["guard_selection_attempts"]] == [
        "active_member_blocked_a",
    ]
    diagnostics = guard._candidate_pass_gate_diagnostics(candidate, blockers)
    assert diagnostics["selected_passed"] is True
    assert diagnostics["selected_failed_checks"] == []
    assert diagnostics["failed_check_counts"] == {}
    assert diagnostics["blocker_counts"] == {}
    assert diagnostics["first_passing_attempt"]["candidate_id"] == "active_member_blocked_a"
    assert diagnostics["fallthrough"]["applied"] is False


