def test_live_guard_coverage_hunger_activation_is_hour_gated(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    alive_hour_wallet = "0xa6896d11f76dfa2820662c1f441496f51553559b"
    proven_hour_wallet = "0xdf2c0702fc00be90bd795234a86e28f1ed39118a"
    temporal = tmp_path / "wallet_temporal_profitability_latest.json"
    _write_temporal_slice_labels(
        temporal,
        [
            {
                "wallet": proven_hour_wallet,
                "classification": "WEEKDAY-ONLY",
                "slice_labels": {
                    "weekday": _slice_label("PROVEN-POSITIVE", n=235, roi=22.0),
                    "weekend": _slice_label("PROVEN-NEGATIVE", n=20, roi=-5.0),
                },
            }
        ],
    )
    monkeypatch.setattr(guard, "WALLET_TEMPORAL_PROFITABILITY_STATE", temporal)
    members = [
        {
            "candidate_id": "alive_hour_probe",
            "source_wallet": alive_hour_wallet,
            "coverage_hunger_activation": {"activation_hours_utc": [15]},
        },
        {
            "candidate_id": "proven_hour_probe",
            "source_wallet": proven_hour_wallet,
            "coverage_hunger_activation": {"activation_hours_utc": [14]},
        },
    ]

    inactive_members, inactive_report = guard._apply_temporal_slice_exclusions(
        members,
        now=datetime(2026, 7, 14, 13, 5, tzinfo=timezone.utc),
    )
    admitted_alive, alive_report = guard._apply_temporal_slice_exclusions(
        [members[0]],
        now=datetime(2026, 7, 14, 15, 5, tzinfo=timezone.utc),
    )
    admitted_proven, proven_report = guard._apply_temporal_slice_exclusions(
        [members[1]],
        now=datetime(2026, 7, 14, 14, 5, tzinfo=timezone.utc),
    )

    assert inactive_members == []
    assert inactive_report["excluded_wallets"] == [alive_hour_wallet, proven_hour_wallet]
    assert {
        row["reason"] for row in inactive_report["excluded_members"]
    } == {"coverage_hunger_activation_hour_inactive"}
    assert admitted_alive[0]["temporal_slice_evaluation"]["reason"] == "coverage_hunger_alive_hour_probe"
    assert alive_report["excluded_count"] == 0
    assert admitted_proven[0]["temporal_slice_evaluation"]["reason"] == "no_active_temporal_slice_proven_negative"
    assert proven_report["excluded_count"] == 0


def test_live_guard_external_liveness_sweep_disables_nonliving_enabled_members(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    live_wallet = "0x1111111111111111111111111111111111111111"
    stale_wallet = "0x2222222222222222222222222222222222222222"
    missing_wallet = "0x3333333333333333333333333333333333333333"
    now = datetime(2026, 7, 14, 12, 0, tzinfo=timezone.utc)
    state = tmp_path / "queue_remote_dataapi_fresh_flow_probe_latest.json"
    state.write_text(
        json.dumps(
            {
                "generated_at": now.isoformat(),
                "rows": [
                    {
                        "wallet": live_wallet,
                        "status": "PASS",
                        "latest_btc5m_trade_ts": now.timestamp() - 120,
                        "btc5m_trades_24h": 3,
                        "btc5m_buys_24h": 3,
                    },
                    {
                        "wallet": stale_wallet,
                        "status": "PASS",
                        "latest_btc5m_trade_ts": now.timestamp() - 25 * 3600,
                        "btc5m_trades_24h": 3,
                        "btc5m_buys_24h": 3,
                    },
                ],
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setattr(guard, "ACTIVE_SET_EXTERNAL_LIVENESS_STATE", state)

    swept, report = guard._apply_external_liveness_sweep(
        [
            {"candidate_id": "live", "source_wallet": live_wallet, "enabled": True, "status": "PASS"},
            {"candidate_id": "stale", "source_wallet": stale_wallet, "enabled": True, "status": "PASS"},
            {"candidate_id": "missing", "source_wallet": missing_wallet, "enabled": True, "status": "PASS"},
        ],
        now=now,
    )
    rows = {row["source_wallet"]: row for row in swept}

    assert rows[live_wallet]["enabled"] is True
    assert rows[live_wallet]["external_liveness_gate"]["passed"] is True
    assert rows[stale_wallet]["enabled"] is False
    assert rows[stale_wallet]["status"] == "AUTO_DISABLED_EXTERNAL_LIVENESS_FABLE_20260714T1134"
    assert rows[stale_wallet]["external_liveness_gate"]["reason"] == "external_liveness_age_gte_24h"
    assert rows[missing_wallet]["enabled"] is False
    assert rows[missing_wallet]["external_liveness_gate"]["reason"] == "external_liveness_row_missing"
    assert report["disabled_wallets"] == [stale_wallet, missing_wallet]


