    stale = dict(member)
    stale["temporal_slice_evaluation"] = {
        "excluded": False,
        "evaluated_slices": [{
            "slice": "weekend", "label": "PROVEN-POSITIVE",
            "resolved_trades": 29, "roi_pct": 8.3,
        }],
    }
    reverted, _ = guard._apply_weekend_proven_seat_admission([stale], now=now)
    assert reverted[0]["status"] == "FABLE_1704_MASS_ADMISSION_WAVE_TOP10_COMPLETE_HISTORY"


