def test_live_guard_external_liveness_sweep_preserves_f418_readmission(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    f418_wallet = "0xf418d3a1a941292f9c8707d62a14980c5beb95a3"
    now = datetime(2026, 7, 16, 5, 45, tzinfo=timezone.utc)
    state = tmp_path / "queue_remote_dataapi_fresh_flow_probe_latest.json"
    state.write_text(
        json.dumps(
            {
                "generated_at": now.isoformat(),
                "rows": [
                    {
                        "wallet": f418_wallet,
                        "status": "PASS",
                        "latest_btc5m_trade_ts": now.timestamp() - 42 * 3600,
                        "btc5m_trades_24h": 3,
                        "btc5m_buys_24h": 3,
                    }
                ],
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setattr(guard, "ACTIVE_SET_EXTERNAL_LIVENESS_STATE", state)

    swept, report = guard._apply_external_liveness_sweep(
        [
            {
                "candidate_id": "market_cohort_alive_980c5beb95a3",
                "source_wallet": f418_wallet,
                "enabled": True,
                "status": "FABLE_0528_F418_ACTIVATED_BRANCH_A",
                "f418_readmission_activation": {
                    "direction_id": "2026-07-16T05:28Z-fable-f418-activation-branch-a",
                    "packet_status": "PRE_RULED_ADMIT_F418_ACTIVATION",
                    "counterfactual_basis": "routing_shadow_member_attribution",
                    "measurable_resolved_intents": 15,
                    "post_fee_pnl_usd": 4.544406,
                    "basis_packet": "data/research/f418_readmission_packet_latest.json",
                },
            }
        ],
        now=now,
    )

    row = swept[0]
    gate = row["external_liveness_gate"]
    assert row["enabled"] is True
    assert gate["passed"] is True
    assert gate["reason"] == "external_liveness_exempt_f418_routing_shadow_readmission"
    assert gate["original_reason"] == "external_liveness_age_gte_24h"
    assert row["external_liveness_exemption"]["measurable_resolved_intents"] == 15
    assert report["disabled_wallets"] == []
    assert report["exempted_wallets"] == [f418_wallet]


