def test_live_guard_operator_notify_transition_uses_prior_blockers_after_restart():
    import scripts.run_wallet_copy_live_guard as guard

    prior_blockers = [
        "temporal_slice_exclusion_all_measured_members",
        "seat_reserved(direction_id=2026-07-11T20:04Z-fable-5960-readmission, activates_at=2026-07-13T00:00:00Z)",
    ]
    running_blockers: list[str] = []

    restart_transition = guard._operator_notify_transition(
        {"blockers": prior_blockers},
        current_blockers=running_blockers,
        suppression={"enabled": True, "suppress_repeat_notify_while_blocker_set_unchanged": True},
        now_iso="2026-07-11T22:23:44Z",
    )
    repeat_transition = guard._operator_notify_transition(
        {"blockers": running_blockers, "operator_notify_transition": restart_transition},
        current_blockers=running_blockers,
        suppression={"enabled": True, "suppress_repeat_notify_while_blocker_set_unchanged": True},
        now_iso="2026-07-11T22:24:44Z",
    )

    assert restart_transition["notify"] is True
    assert restart_transition["blocker_set_changed"] is True
    assert restart_transition["last_notify_at"] == "2026-07-11T22:23:44Z"
    assert repeat_transition["notify"] is False
    assert repeat_transition["blocker_set_changed"] is False
    assert repeat_transition["last_notify_at"] == "2026-07-11T22:23:44Z"


