def test_live_guard_overflow_refill_follows_overlay_queue_position(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    overlay_path = tmp_path / "wallet_copy_active_set_auto_degrade_state.json"
    base_members = [
        {"candidate_id": f"base_{index}", "source_wallet": f"0x{index:040x}", "policy_id": f"p{index}", "enabled": True}
        for index in range(1, 9)
    ]
    base_active_set = {
        "status": "ACTIVE",
        "mode": "active_set_single_guard",
        "target_member_count_max": 9,
        "members": base_members,
    }
    overlay_path.write_text(
        json.dumps(
            {
                "members": [
                    {
                        "candidate_id": "overlay_refill_second",
                        "source_wallet": "0xffffffffffffffffffffffffffffffffffffffff",
                        "policy_id": "second",
                        "enabled": True,
                        "queue_position": 5,
                    },
                    {
                        "candidate_id": "overlay_active_slot",
                        "source_wallet": "0x1111111111111111111111111111111111111111",
                        "policy_id": "active",
                        "enabled": True,
                        "queue_position": 1,
                    },
                    {
                        "candidate_id": "overlay_refill_first",
                        "source_wallet": "0x2222222222222222222222222222222222222222",
                        "policy_id": "first",
                        "enabled": True,
                        "queue_position": 2,
                    },
                ]
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setattr(guard, "AUTO_DEGRADE_ACTIVE_SET_STATE", overlay_path)
    monkeypatch.setattr(
        guard,
        "mission_contract",
        lambda: {"current_runtime_phase_contract": {"active_live_set": base_active_set}},
    )
    call_count = 0

    def fake_total_loss_auto_disable(members, args):
        nonlocal call_count
        call_count += 1
        if call_count == 1:
            disabled = members[0]
            return members[1:], {
                "enabled": True,
                "disabled_members": [
                    {
                        "candidate_id": disabled.get("candidate_id"),
                        "source_wallet": disabled.get("source_wallet"),
                    }
                ],
            }
        return members, {"enabled": True, "disabled_members": []}

    monkeypatch.setattr(guard, "_total_loss_member_auto_disable", fake_total_loss_auto_disable)
    base_args = SimpleNamespace(
        active_set=True,
        active_set_member_limit=0,
        candidate_id="",
        source_wallet="",
        policy_id="",
        inventory_late_window_stop_s=60.0,
    )

    _, active_set_runtime = guard._active_set_runtime_args(base_args, cycle=1)

    runtime_candidate_ids = [row["candidate_id"] for row in active_set_runtime["members"]]
    assert "overlay_active_slot" in runtime_candidate_ids
    assert "overlay_refill_first" in runtime_candidate_ids
    assert "overlay_refill_second" not in runtime_candidate_ids
    assert active_set_runtime["total_loss_auto_disable"]["overflow_refill"]["admitted_queue_positions"] == [2.0]


def test_live_guard_applies_defensive_sizing_to_base_and_overlay(monkeypatch, tmp_path):
    import scripts.run_wallet_copy_live_guard as guard

    overlay_path = tmp_path / "wallet_copy_active_set_auto_degrade_state.json"
    overlay_path.write_text(
        json.dumps(
            {
                "updated_at": "2026-07-07T17:15:00Z",
                "members": [
                    {
                        "candidate_id": "overlay_member",
                        "source_wallet": "0x2222222222222222222222222222222222222222",
                        "policy_id": "overlay_policy",
                        "enabled": True,
                        "max_order_usd": 4.0,
                        "policy": {"policy_id": "overlay_policy", "max_order_usd": 4.0},
                    },
                    {
                        "candidate_id": "runtime_auto_degrade_a95b27b062",
                        "source_wallet": "0xa95b27b0626973f7bc7600e65cd88cd7b42d0d14",
                        "policy_id": "a95b_policy",
                        "enabled": True,
                        "fable_cap_max_order_usd": 1.0,
                        "max_order_usd": 1.0,
                        "policy": {"policy_id": "a95b_policy", "max_order_usd": 1.0},
                    }
                ],
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setattr(guard, "AUTO_DEGRADE_ACTIVE_SET_STATE", overlay_path)
    monkeypatch.setattr(
        guard,
        "mission_contract",
        lambda: {
            "current_runtime_phase_contract": {
                "active_live_set": {
                    "status": "ACTIVE",
                    "overnight_defensive_sizing": {
                        "enabled": True,
                        "direction_id": "unit-defensive",
                        "budget_multiplier": 0.5,
                        "strong_tier_suspended": True,
                    },
                    "members": [
                        {
                            "candidate_id": "base_member",
                            "source_wallet": "0x1111111111111111111111111111111111111111",
                            "policy_id": "base_policy",
                            "enabled": True,
                            "max_order_usd": 8.0,
                            "policy": {"policy_id": "base_policy", "max_order_usd": 8.0},
                        }
                    ],
                }
            }
        },
    )

    active_set = guard._active_live_set_contract()
    members = guard._active_live_set_members_contract()

    assert active_set["defensive_sizing_applied"]["budget_multiplier"] == 0.5
    assert [(row["candidate_id"], row["max_order_usd"], row["policy"]["max_order_usd"]) for row in members] == [
        ("base_member", 4.0, 4.0),
        ("overlay_member", 2.0, 2.0),
        ("runtime_auto_degrade_a95b27b062", 1.0, 1.0),
    ]
    assert all(row["defensive_sizing"]["strong_tier_suspended"] is True for row in members)
    a95b = next(row for row in members if row["candidate_id"] == "runtime_auto_degrade_a95b27b062")
    assert a95b["defensive_sizing"]["explicit_fable_cap_max_order_usd"] == 1.0
    assert a95b["defensive_sizing"]["budget_multiplier_skipped_for_explicit_fable_cap"] is True


