def test_live_guard_slow_path_cadence_helpers_default_to_hot_path_first_cycle():
    import scripts.run_wallet_copy_live_guard as guard

    args = SimpleNamespace(
        guard_slow_path_every_n_cycles=4,
        active_set_dataapi_poller_every_n_cycles=4,
        self_feed_ledger_diff_every_n_cycles=0,
        self_feed_ledger_diff_cycle_offset=0,
        watch_tier_dataapi_poller_every_n_cycles=0,
        watch_tier_dataapi_poller_cycle_offset=0,
        shadow_lanes_every_n_cycles=0,
        shadow_lanes_cycle_offset=2,
    )

    every_n = guard._cadence_every_n(args, "self_feed_ledger_diff_every_n_cycles")
    assert every_n == 4
    self_feed_offset = guard._cadence_offset(args, "self_feed_ledger_diff_cycle_offset", every_n=every_n)
    assert self_feed_offset == 0
    assert guard._cadence_due(1, every_n, self_feed_offset) is True
    assert guard._cadence_due(2, every_n, self_feed_offset) is False
    assert guard._cadence_due(5, every_n, self_feed_offset) is True
    watch_tier_every_n = guard._cadence_every_n(args, "watch_tier_dataapi_poller_every_n_cycles")
    watch_tier_offset = guard._cadence_offset(
        args,
        "watch_tier_dataapi_poller_cycle_offset",
        every_n=watch_tier_every_n,
    )
    assert watch_tier_every_n == 4
    assert watch_tier_offset == 0
    assert guard._cadence_due(1, watch_tier_every_n, watch_tier_offset) is True
    assert guard._cadence_due(2, watch_tier_every_n, watch_tier_offset) is False
    assert guard._cadence_due(5, watch_tier_every_n, watch_tier_offset) is True
    shadow_lanes_every_n = guard._cadence_every_n(args, "shadow_lanes_every_n_cycles")
    shadow_lanes_offset = guard._cadence_offset(
        args,
        "shadow_lanes_cycle_offset",
        every_n=shadow_lanes_every_n,
    )
    assert shadow_lanes_every_n == 4
    assert shadow_lanes_offset == 2
    assert guard._cadence_due(3, shadow_lanes_every_n, shadow_lanes_offset) is True
    active_set_dataapi_every_n = guard._cadence_every_n(args, "active_set_dataapi_poller_every_n_cycles")
    assert active_set_dataapi_every_n == 4
    assert guard._cadence_due(2, active_set_dataapi_every_n, 0) is False

    payload = guard._cadence_payload(
        {"status": "PASS", "paper_only": True, "live_orders_allowed": False},
        name="self_feed_ledger_diff",
        generated_at="2026-07-08T04:14:00Z",
        cycle=2,
        every_n=every_n,
        offset=self_feed_offset,
        executed=False,
    )
    assert payload["status"] == "PASS"
    assert payload["cadence"]["executed_this_cycle"] is False
    assert payload["cadence"]["every_n_cycles"] == 4
    assert payload["cadence"]["cycle_offset"] == 0
    watch_payload = guard._cadence_payload(
        {"status": "PASS", "paper_only": True, "live_orders_allowed": False},
        name="watch_tier_dataapi_poller",
        generated_at="2026-07-13T22:15:00Z",
        cycle=3,
        every_n=watch_tier_every_n,
        offset=watch_tier_offset,
        executed=False,
    )
    assert watch_payload["status"] == "PASS"
    assert watch_payload["cadence"]["name"] == "watch_tier_dataapi_poller"
    assert watch_payload["cadence"]["executed_this_cycle"] is False
    assert watch_payload["cadence"]["every_n_cycles"] == 4
    assert watch_payload["cadence"]["cycle_offset"] == 0
    assert watch_payload["cadence"]["reason"] == (
        "cadence_reports_per_task_due_status; every_n_1_runs_on_hot_path"
    )


