def test_live_guard_active_set_rtds_premerge_refreshes_all_members(monkeypatch):
    import scripts.run_wallet_copy_live_guard as guard

    calls: list[tuple[str, Any]] = []

    def fake_selected(args):
        calls.append(("selected", args.source_wallet))
        return {
            "status": "PASS",
            "source_wallet": args.source_wallet,
            "new_matching_events": 1,
            "retained_matching_rows": 3,
            "history_write_skipped": False,
            "latest_event_ts": 1_700_000_001.0,
            "latest_observed_ts": 1_700_000_002.0,
            "rtds_catchup_lag_s": 0.25,
            "offset_state": args.offset_state,
            "premerge_substage_profile": {
                "tail_open_seek_read": {"duration_s": 0.01, "bytes_read": 128},
                "line_json_parse": {"duration_s": 0.02, "line_count": 3},
                "merge_dedupe": {"duration_s": 0.03, "matching_events": 1},
                "history_write": {"duration_s": 0.05, "executed": True},
                "offset_state_write": {"duration_s": 0.04},
            },
        }

    def fake_batch(args):
        wallets = list(args.source_wallets)
        calls.append(("batch", wallets))
        summaries = {}
        for index, source_wallet in enumerate(wallets):
            summaries[source_wallet] = {
                "status": "PASS",
                "source_wallet": source_wallet,
                "new_matching_events": 1 if source_wallet.endswith("2222") else 0,
                "retained_matching_rows": 3,
                "history_write_skipped": source_wallet.endswith("1111"),
                "latest_event_ts": 1_700_000_001.0,
                "latest_observed_ts": 1_700_000_002.0,
                "rtds_catchup_lag_s": 0.25,
                "offset_state": args.offset_states[source_wallet],
                "premerge_substage_profile": {
                    "tail_open_seek_read": {"duration_s": 0.01 if index == 0 else 0.0, "bytes_read": 128},
                    "line_json_parse": {"duration_s": 0.02 if index == 0 else 0.0, "line_count": 3},
                    "merge_dedupe": {"duration_s": 0.03 if index == 0 else 0.0, "matching_events": 1},
                    "history_write": {"duration_s": 0.05 if index == 0 else 0.0, "executed": True},
                    "offset_state_write": {"duration_s": 0.04 if index == 0 else 0.0},
                },
            }
        return {"status": "PASS", "wallet_summaries": summaries}

    monkeypatch.setattr(guard, "_run_rtds_merge", fake_selected)
    monkeypatch.setattr(guard, "_run_rtds_multi_wallet_merge", fake_batch)
    monkeypatch.setattr(guard, "_active_live_set_members_contract", lambda: [])
    args = SimpleNamespace(
        rtds_jsonl="data/research/rtds.jsonl",
        active_set_rtds_premerge=True,
        active_set_rtds_premerge_member_limit=0,
        history_state="history.json",
        history_window_index="history_index.json",
        wallet_event_log="events.jsonl",
        rtds_scan_limit=50_000,
        rtds_tail_bytes=12345,
        rtds_cold_tail_bytes=98765,
        rtds_offset_state="offset.json",
        rtds_watermark_state="watermarks.json",
        rtds_max_new_events=500,
        pipeline_timeout_s=45.0,
    )

    selected_result, report = guard._run_active_set_rtds_premerge(
        args,
        active_set_runtime={
            "members": [
                {"source_wallet": "0x1111111111111111111111111111111111111111"},
                {"source_wallet": "0x2222222222222222222222222222222222222222"},
                {"source_wallet": "0x1111111111111111111111111111111111111111"},
                {"source_wallet": "0x3333333333333333333333333333333333333333", "enabled": False},
            ]
        },
        selected_wallet="0x2222222222222222222222222222222222222222",
    )

    assert calls == [
        (
            "batch",
            [
                "0x2222222222222222222222222222222222222222",
                "0x1111111111111111111111111111111111111111",
            ],
        ),
    ]
    assert selected_result["stdout_json"]["source_wallet"] == "0x2222222222222222222222222222222222222222"
    assert selected_result["execution_mode"] == "in_process_batch"
    assert report["status"] == "PASS"
    assert report["wallets_refreshed"] == 2
    assert report["new_matching_events"] == 1
    assert report["max_rtds_catchup_lag_s"] == 0.25
    assert {row["execution_mode"] for row in report["rows"]} == {"in_process_batch"}
    assert report["selected_wallet_priority_premerge"]["applied"] is True
    assert (
        report["selected_wallet_priority_premerge"]["reason"]
        == "selected_wallet_included_in_single_batch_premerge"
    )
    assert report["rows"][0]["premerge_substage_profile"]["tail_open_seek_read"]["bytes_read"] == 128
    assert report["rows"][0]["premerge_substage_profile"]["line_json_parse"]["line_count"] == 3
    totals = report["premerge_substage_profile_totals"]
    assert totals["status"] == "PASS"
    assert totals["wallet_profiles"] == 2
    assert totals["stages"]["tail_open_seek_read"]["duration_s"] == 0.01
    assert totals["stages"]["tail_open_seek_read"]["bytes_read"] == 128
    assert totals["stages"]["line_json_parse"]["line_count"] == 3
    assert totals["stages"]["merge_dedupe"]["matching_events"] == 1
    assert totals["stages"]["history_write"]["duration_s"] == 0.05
    assert totals["stages"]["offset_state_write"]["samples"] == 2
    assert report["paper_only"] is True
    assert report["live_orders_allowed"] is False


