def test_live_guard_watch_tier_poller_chunks_round_robin(monkeypatch, tmp_path: Path):
    calls: list[list[str]] = []

    def fake_poll(args, *, source_wallets):
        calls.append(source_wallets)
        return {
            "status": "PASS",
            "summary": {"active_set_wallets": len(source_wallets), "poll_only_signals": 0},
            "paper_only": True,
            "live_orders_allowed": False,
        }

    wallets = [f"0x{i:040x}" for i in range(5)]
    config = tmp_path / "watch.json"
    config.write_text(
        json.dumps({"wallets": [{"source_wallet": wallet} for wallet in wallets]}),
        encoding="utf-8",
    )
    monkeypatch.setattr("scripts.run_wallet_copy_live_guard._run_active_set_dataapi_poll", fake_poll)
    args = SimpleNamespace(
        watch_tier_dataapi_poller=True,
        watch_tier_wallets_config=str(config),
        watch_tier_history_state="watch_history.json",
        watch_tier_history_window_index="watch_index.json",
        watch_tier_wallet_event_log="watch_events.jsonl",
        watch_tier_dataapi_first_seen_jsonl="watch_first_seen.jsonl",
        watch_tier_dataapi_poller_state="watch_state.json",
        watch_tier_dataapi_poller_interval_s=5.0,
        watch_tier_dataapi_poller_max_wallets_per_cycle=2,
        active_set_dataapi_poller_limit=17,
        active_set_dataapi_poller_pages=2,
        active_set_dataapi_poller_timeout_s=1.25,
        active_set_dataapi_poller_retries=2,
        active_set_dataapi_poller_trade_query_keys="user",
        pipeline_data_api_trade_query_keys="user",
        active_set_dataapi_poller_max_workers=4,
        active_set_dataapi_poller_disable_source_base_overrides=True,
        max_event_age_s=30.0,
    )

    first = _run_watch_tier_dataapi_poller(args, round_robin_offset=0)
    second = _run_watch_tier_dataapi_poller(args, round_robin_offset=2)

    assert calls[0] == wallets[:2]
    assert calls[1] == wallets[2:4]
    assert first["watch_tier_chunk"] == {
        "enabled": True,
        "wallet_count_total": 5,
        "max_wallets_per_cycle": 2,
        "round_robin_offset": 0,
        "selected_wallet_count": 2,
        "next_round_robin_offset": 2,
    }
    assert first["summary"]["watch_tier_wallets"] == 2
    assert first["summary"]["watch_tier_wallets_total"] == 5
    assert first["summary"]["watch_tier_wallets_remaining_after_this_cycle"] == 3
    assert second["watch_tier_chunk"]["round_robin_offset"] == 2
    assert second["watch_tier_chunk"]["next_round_robin_offset"] == 4


