def test_postfilter_active_set_backfills_live_admissible_members_to_floor():
    import scripts.run_wallet_copy_live_guard as guard

    members = [
        {
            "candidate_id": "inadmissible_1",
            "source_wallet": "0x" + "1" * 40,
            "status": "FABLE_1704_MASS_ADMISSION_WAVE_TOP10_COMPLETE_HISTORY",
        },
        {
            "candidate_id": "inadmissible_2",
            "source_wallet": "0x" + "5" * 40,
            "status": "FABLE_1704_MASS_ADMISSION_WAVE_TOP10_COMPLETE_HISTORY",
        },
        {
            "candidate_id": "inadmissible_3",
            "source_wallet": "0x" + "6" * 40,
            "status": "FABLE_1704_MASS_ADMISSION_WAVE_TOP10_COMPLETE_HISTORY",
        },
        {
            "candidate_id": "admissible_1",
            "source_wallet": "0x" + "2" * 40,
            "status": "POLICY_CHOKE_RUNG_DIRECT_EMERGENCY_ADMISSION",
        },
        {
            "candidate_id": "admissible_2",
            "source_wallet": "0x" + "3" * 40,
            "status": "FABLE_1912_DEADMAN_CORRECTED_MICROPROBE",
        },
        {
            "candidate_id": "admissible_3",
            "source_wallet": "0x" + "4" * 40,
            "status": "POLICY_CHOKE_RUNG_DIRECT_EMERGENCY_ADMISSION",
        },
    ]

    selected, diagnostic = guard._rank_postfilter_active_set_members(
        members,
        limit=3,
        target_member_count_min=3,
    )

    assert [row["candidate_id"] for row in selected] == [
        "admissible_1",
        "admissible_2",
        "admissible_3",
    ]
    assert len(selected) >= min(3, diagnostic["admissible_available"])
    assert diagnostic["admissible_available"] == 3
    assert len(diagnostic["members_added"]) == 3
    assert diagnostic["members_rejected"] == [
        {
            "candidate_id": "inadmissible_1",
            "source_wallet": "0x" + "1" * 40,
            "status": "FABLE_1704_MASS_ADMISSION_WAVE_TOP10_COMPLETE_HISTORY",
            "reason": "post_filter_target_capacity",
        },
        {
            "candidate_id": "inadmissible_2",
            "source_wallet": "0x" + "5" * 40,
            "status": "FABLE_1704_MASS_ADMISSION_WAVE_TOP10_COMPLETE_HISTORY",
            "reason": "post_filter_target_capacity",
        },
        {
            "candidate_id": "inadmissible_3",
            "source_wallet": "0x" + "6" * 40,
            "status": "FABLE_1704_MASS_ADMISSION_WAVE_TOP10_COMPLETE_HISTORY",
            "reason": "post_filter_target_capacity",
        },
    ]
    assert len(selected) >= 2


