def test_live_guard_window_rollups_group_children_in_one_linear_pass(monkeypatch):
    import scripts.run_wallet_copy_live_guard as guard

    rows = [
        {
            "source_wallet": "0xaaa",
            "market_slug": f"btc-updown-5m-{1_700_000_000 + index * 300}",
            "condition_id": f"0xcond{index}",
            "outcome": "Up",
            "wallet_eligible_orders": 1,
            "our_submits": 0,
            "our_fills": 0,
            "dominant_skip_reason": "inventory_target_already_met",
        }
        for index in range(40)
    ]
    calls = 0
    original = guard._participation_window_key

    def counted(row):
        nonlocal calls
        calls += 1
        return original(row)

    monkeypatch.setattr(guard, "_participation_window_key", counted)
    rollups = guard._participation_window_rollups(rows)

    assert len(rollups) == len(rows)
    assert calls == len(rows)


def test_live_guard_window_rollup_preserves_multi_child_semantics():
    import scripts.run_wallet_copy_live_guard as guard

    rows = []
    for window, pending in ((1_700_000_000, True), (1_700_000_300, False)):
        for index, reason in enumerate(
            ("inventory_target_already_met", "inventory_target_already_met", "other")
        ):
            rows.append(
                {
                    "source_wallet": "0xaaa",
                    "market_slug": f"btc-updown-5m-{window}",
                    "condition_id": f"0x{window}",
                    "outcome": f"outcome-{index}",
                    "wallet_eligible_orders": index + 1,
                    "our_submits": 0,
                    "our_fills": 0,
                    "dominant_skip_reason": reason,
                    "missed_active_window": True,
                    "miss_pending_market_lifecycle": pending and index == 2,
                    "miss_pending_market_lifecycle_reason": (
                        "market_open" if pending and index == 2 else None
                    ),
                }
            )

    rollups = guard._participation_window_rollups(rows)
    by_slug = {row["market_slug"]: row for row in rollups}
    pending = by_slug["btc-updown-5m-1700000000"]
    settled = by_slug["btc-updown-5m-1700000300"]

    assert pending["wallet_eligible_orders"] == 6
    assert pending["dominant_skip_reason"] == "inventory_target_already_met"
    assert pending["miss_pending_market_lifecycle_reasons"] == {"market_open": 1}
    assert pending["missed_active_window"] is False
    assert pending["participation_skip_category_counts"] == {
        "CORRECT_SKIP": 2,
        "MEASURED_SKIP": 1,
    }
    assert settled["wallet_eligible_orders"] == 6
    assert settled["dominant_skip_reason"] == "inventory_target_already_met"
    assert settled["miss_pending_market_lifecycle_reasons"] == {}
    assert settled["missed_active_window"] is True
    assert settled["participation_skip_category"] == "MEASURED_SKIP"


def test_live_guard_in_process_rss_sample_uses_current_pid(monkeypatch):
    import scripts.run_wallet_copy_live_guard as guard

