def test_discover_replay_unresolved_ratio_excludes_open_lifecycle_windows():
    import scripts.replay_discover_live_band_candidates as replay

    orders = [
        {"order_id": "resolved", "market_slug": "btc-updown-5m-1700000000"},
        {"order_id": "closed_unresolved", "market_slug": "btc-updown-5m-1700000000"},
        {"order_id": "open_unresolved", "market_slug": "btc-updown-5m-1700000300"},
    ]
    scored = [
        {"order_id": "resolved", "resolved": True},
        {"order_id": "closed_unresolved", "resolved": False},
        {"order_id": "open_unresolved", "resolved": False},
    ]

    summary = replay._lifecycle_closed_score_summary(
        orders,
        scored,
        {"orders": 3, "resolved_orders": 1, "unresolved_orders": 2, "unresolved_ratio": 0.666667},
        now_ts=1_700_000_400.0,
    )

    assert summary["lifecycle_unresolved_basis"] == "closed_markets_only"
    assert summary["lifecycle_closed_orders"] == 2
    assert summary["pending_lifecycle_orders"] == 1
    assert summary["closed_unresolved_orders"] == 1
    assert summary["unresolved_orders"] == 1
    assert summary["unresolved_ratio"] == 0.5
    assert summary["resolved_orders"] == 1


