def test_polymarket_http_client_suppresses_repeat_direct_reset_without_recovery(monkeypatch):
    calls = []

    def fake_request(self, method, url, **kwargs):
        calls.append({"method": method, "url": url, **kwargs})
        raise requests.ConnectionError("connection reset by peer")

    monkeypatch.delenv("POLYMARKET_SOURCE_PROXY_URL", raising=False)
    monkeypatch.delenv("POLYMARKET_HTTPS_PROXY", raising=False)
    monkeypatch.delenv("POLYMARKET_DATA_API_BASE_URL", raising=False)
    monkeypatch.setenv("POLYMARKET_DIRECT_RESET_SUPPRESSION_TTL_S", "60")
    monkeypatch.setattr(requests.Session, "request", fake_request)
    client = PolymarketHttpClient(timeout_s=0.1, retries=1, user_agent="unit-test")

    with pytest.raises(PolymarketRouteError) as first:
        client.get_json(
            "https://data-api.polymarket.com/trades",
            params={"limit": 1},
            request_role="unit_trade_fetch",
        )

    assert len(calls) == 3
    assert first.value.route_report["route_class"] == "DIRECT_RESET"
    assert first.value.route_report["direct_route_suppression_armed"] is True
    assert first.value.route_report["direct_route_suppressed"] is False
    assert first.value.route_report["external_route_required"] is True
    assert first.value.route_report["code_route_recovery_exhausted"] is True
    assert first.value.route_report["required_operator_inputs"] == [
        "POLYMARKET_SOURCE_PROXY_URL",
        "POLYMARKET_HTTPS_PROXY",
        "POLYMARKET_DATA_API_BASE_URL",
        "POLYMARKET_GAMMA_API_BASE_URL",
        "POLYMARKET_CLOB_API_BASE_URL",
    ]

    with pytest.raises(PolymarketRouteError) as second:
        client.get_json(
            "https://data-api.polymarket.com/trades",
            params={"limit": 1},
            request_role="unit_trade_fetch",
        )

    assert len(calls) == 3
    assert second.value.route_report["status"] == "TRANSPORT_ERROR"
    assert second.value.route_report["route_class"] == "DIRECT_RESET"
    assert second.value.route_report["attempt_count"] == 1
    assert second.value.route_report["attempts"][0]["variant"] == "direct_route_reset_suppression"
    assert second.value.route_report["direct_route_suppressed"] is True
    assert second.value.route_report["direct_route_suppression_armed"] is False
    assert second.value.route_report["external_route_required"] is True
    assert second.value.route_report["next_command"].startswith("python3 scripts/probe_polymarket_source_routes.py")


