def test_source_route_probe_reports_variant_pass_counts_and_rate_limit():
    endpoint_result = {
        "requests": [
            {"status": "ERROR", "variant": "requests_default"},
            {"status": "PASS", "variant": "requests_browser_ua_connection_close"},
        ],
        "curl_variants": [
            {"status": "PASS", "transport": "curl_ipv4_http1_head"},
            {"status": "ERROR", "transport": "curl_http2_head", "stderr_tail": "recv failure"},
        ],
        "httpx_variants": [
            {"status": "PASS", "variant": "httpx_http1_browser_ua"},
            {"status": "ERROR", "variant": "httpx_http2_browser_ua", "error": "connection reset"},
        ],
    }

    assert _endpoint_status(endpoint_result) == "PASS"
    assert _best_route_variant(endpoint_result) == "requests_browser_ua_connection_close"
    assert _route_variant_pass_counts(endpoint_result) == {
        "curl_ipv4_http1_head": 1,
        "httpx_http1_browser_ua": 1,
        "requests_browser_ua_connection_close": 1,
    }

    rate_limited = {"requests": [{"status": "HTTP_NON_2XX", "http_status": 429}], "curl_variants": []}
    assert _rate_limit_suspected(rate_limited) is True
    assert _endpoint_status(rate_limited) == "RATE_LIMIT_SUSPECTED"


