def test_source_route_probe_reuses_direct_result_for_identical_unproxied_route(monkeypatch):
    import scripts.probe_polymarket_source_routes as probe

    endpoints = [
        {
            "name": "data_leaderboard",
            "host": "data-api.polymarket.com",
            "url": "https://data-api.polymarket.com/leaderboard",
            "params": {"limit": 1},
        },
        {
            "name": "internet_control_google",
            "host": "www.google.com",
            "url": "https://www.google.com",
            "params": None,
            "control": True,
        },
    ]

    def fake_direct_probe(endpoint, timeout_s):
        if endpoint.get("control"):
            return {
                "best_route_variant": "requests_default",
                "curl_variants": [],
                "dns": {"status": "OK", "addresses": ["142.250.1.1"]},
                "httpx_variants": [],
                "rate_limit_suspected": False,
                "requests": [{"status": "PASS", "variant": "requests_default"}],
                "status": "PASS",
            }
        return {
            "best_route_variant": "",
            "curl_variants": [
                {"status": "ERROR", "stderr_tail": "Recv failure", "transport": "curl_http1_head"}
            ],
            "dns": {"status": "OK", "addresses": ["104.18.1.1"]},
            "httpx_variants": [
                {
                    "status": "ERROR",
                    "error": "Connection reset by peer",
                    "variant": "httpx_http1_browser_ua",
                }
            ],
            "rate_limit_suspected": False,
            "requests": [
                {
                    "status": "ERROR",
                    "error": "Connection reset by peer",
                    "variant": "requests_default",
                }
            ],
            "status": "CONNECTION_RESET",
        }

    def fake_routed_endpoint(endpoint):
        return dict(endpoint), {
            "original_host": endpoint["host"],
            "routed_host": endpoint["host"],
            "source_base_override_configured": False,
            "source_base_override_env_var": None,
        }

    def fake_dns_probe(host):
        if host == "www.google.com":
            return {"status": "OK", "addresses": ["142.250.1.1"]}
        return {"status": "OK", "addresses": ["104.18.1.1"]}

    def fail_routed_probe(*args, **kwargs):
        raise AssertionError("identical unproxied routes should reuse direct probe evidence")

    monkeypatch.delenv("POLYMARKET_SOURCE_PROXY_URL", raising=False)
    monkeypatch.delenv("POLYMARKET_HTTPS_PROXY", raising=False)
    for env_var in ("HTTPS_PROXY", "HTTP_PROXY", "ALL_PROXY", "NO_PROXY"):
        monkeypatch.delenv(env_var, raising=False)
    monkeypatch.setattr(probe, "ENDPOINTS", endpoints)
    monkeypatch.setattr(probe, "_direct_probe", fake_direct_probe)
    monkeypatch.setattr(probe, "_routed_endpoint", fake_routed_endpoint)
    monkeypatch.setattr(probe, "_dns_probe", fake_dns_probe)
    monkeypatch.setattr(probe, "_httpx_probe", fail_routed_probe)
    monkeypatch.setattr(probe, "_requests_probe", fail_routed_probe)
    monkeypatch.setattr(probe, "_curl_probe", fail_routed_probe)
    monkeypatch.setattr(probe, "source_base_overrides", lambda: {})

    state = probe.build_state(timeout_s=0.1)
    endpoint = next(row for row in state["endpoints"] if row["name"] == "data_leaderboard")

    assert state["status"] == "POLYMARKET_ROUTE_RESET"
    assert endpoint["routed_reused_direct_probe"] is True
    assert endpoint["routed_reuse_reason"] == "identical_direct_route_without_proxy_or_base_override"
    assert endpoint["requests"] == endpoint["direct_requests"]
    assert endpoint["curl_variants"] == endpoint["direct_curl_variants"]
    assert endpoint["reset_attempt_count"] == 3


def test_source_route_probe_classifies_direct_and_recovered_routes():
    assert _route_class({"direct_status": "PASS", "routed_status": "PASS"}) == "DIRECT_PASS"
    assert (
        _route_class(
            {
                "direct_status": "CONNECTION_RESET",
                "routed_status": "PASS",
                "source_base_override_configured": True,
            }
        )
        == "ROUTE_RECOVERED_DEGRADED"
    )
    assert (
        _route_class(
            {
                "direct_status": "CONNECTION_RESET",
                "routed_status": "PASS",
                "requests": [{"status": "PASS", "proxy_configured": True}],
            }
        )
        == "PROXY_RECOVERED_DEGRADED"
    )
    assert (
        _route_class(
            {
                "direct_status": "CONNECTION_RESET",
                "httpx_variants": [{"status": "PASS", "proxy_configured": True}],
                "routed_status": "PASS",
            }
        )
        == "PROXY_RECOVERED_DEGRADED"
    )
    assert (
        _route_class({"direct_status": "CONNECTION_RESET", "routed_status": "CONNECTION_RESET"})
        == "DIRECT_RESET"
    )
    assert (
        _route_class(
            {
                "direct_status": "RATE_LIMIT_SUSPECTED",
                "routed_status": "PASS",
                "source_base_override_configured": True,
            }
        )
        == "ROUTE_RECOVERED_DEGRADED"
    )


