    assert state["env"]["HTTPS_PROXY"]["contains_sensitive_material"] is True
    assert state["env"]["NO_PROXY"]["mentions_polymarket"] is True
    assert "user" not in serialized
    assert "pass" not in serialized
    assert "secret" not in serialized


