    assert gamma_override["base_url_redacted"] == "https://relay.example:8443/gamma"
    assert gamma_override["base_url_scheme"] == "https"
    assert gamma_override["base_url_host"] == "relay.example:8443"
    assert gamma_override["base_url_path"] == "/gamma"
