def test_jina_source_relay_honors_retry_after_backoff(monkeypatch):
    from scripts import run_polymarket_jina_source_relay as relay

    class FakeJinaResponse:
        def __init__(self, status_code: int, body: bytes):
            self.status_code = status_code
            self.headers = {}
            self._body = body

        def iter_content(self, chunk_size=65_536):
            del chunk_size
            yield self._body

    responses = [
        FakeJinaResponse(429, b'{"retryAfter":3,"message":"rate limited"}'),
        FakeJinaResponse(200, b"Title:\n\nMarkdown Content:\n[]"),
    ]
    sleeps = []

    def fake_get(url, **kwargs):
        del url, kwargs
        return responses.pop(0)

    relay._CACHE.clear()
    relay._UPSTREAM_BACKOFF_UNTIL = 0.0
    relay._UPSTREAM_NEXT_REQUEST_AT = 0.0
    monkeypatch.setattr(relay.requests, "get", fake_get)
    monkeypatch.setattr(relay.time, "monotonic", lambda: 100.0)
    monkeypatch.setattr(relay.time, "sleep", lambda seconds: sleeps.append(seconds))

    payload, source = relay.fetch_via_jina(
        "https://data-api.polymarket.com/trades?limit=1",
        timeout_s=1.0,
        cache_ttl_s=30.0,
        max_bytes=10_000,
        upstream_retries=2,
        upstream_min_interval_s=0.0,
    )

    assert json.loads(payload) == []
    assert source == "jina"
    assert responses == []
    assert 3.0 in sleeps


