def test_source_relay_health_payload_reports_in_flight_cap():
    from scripts import run_polymarket_jina_source_relay as relay

    metrics_lock = relay.threading.Lock()
    server = SimpleNamespace(
        relay_timeout_s=8.0,
        relay_cache_ttl_s=8.0,
        relay_upstream_retries=2,
        relay_upstream_min_interval_s=0.25,
        relay_max_upstream_in_flight=4,
        relay_busy_timeout_s=0.75,
        relay_metrics_lock=metrics_lock,
        relay_path_metrics={},
    )
    relay._record_path_metric(server, "/clob/book", "upstream_502", 0.8)
    relay._record_path_metric(server, "/clob/book", "upstream_502", 1.2)
    relay._record_path_metric(server, "/clob/book", "busy_503", 0.75)

    payload = relay._health_payload(server)

    assert payload["status"] == "PASS"
    assert payload["paper_only"] is True
    assert payload["live_orders_allowed"] is False
    assert payload["max_upstream_in_flight"] == 4
    assert payload["busy_timeout_s"] == 0.75
    assert payload["path_metrics"]["/clob/book"]["upstream_502"]["count"] == 2
    assert payload["path_metrics"]["/clob/book"]["upstream_502"]["latency_p50_s"] == 1.0
    assert payload["path_metrics"]["/clob/book"]["busy_503"]["count"] == 1


