def test_live_tracker_cli_stops_on_strict_admission_evidence(monkeypatch, tmp_path: Path):
    import scripts.run_wallet_live_tracker as runner

    state_path = tmp_path / "tracker_state.json"
    calls = {"count": 0}

    class FakeTracker:
        def __init__(self, cfg):
            self.cfg = cfg

        def poll_once(self):
            calls["count"] += 1
            required = 0 if calls["count"] == 1 else 2
            return {
                "summary": {
                    "wallets": 2,
                    "wallet_reports": [{"wallet": "0xunit1"}, {"wallet": "0xunit2"}],
                    "mirror_coverage_status": "PASS",
                    "copy_efficiency": {
                        "status": "PASS" if required else "WATCH",
                        "summary": {
                            "required_buy_copy_events": required,
                            "clob_filled_buy_copy_events": required,
                            "fallback_filled_buy_copy_events": 0,
                            "rejected_buy_copy_events": 0,
                            "missed_buy_copy_events": 0,
                        },
                    },
                }
            }

    monkeypatch.setattr(runner, "LiveWalletTracker", FakeTracker)
    monkeypatch.setattr(runner.time, "sleep", lambda seconds: None)
    monkeypatch.setattr(
        "sys.argv",
        [
            "run_wallet_live_tracker.py",
            "--iterations",
            "20",
            "--state",
            str(state_path),
            "--stop-on-admission-evidence",
            "--no-use-global-tracker-lock",
        ],
    )

    assert runner.main() == 0
    assert calls["count"] == 2
    payload = json.loads(state_path.read_text(encoding="utf-8"))
    stop = payload["admission_evidence_stop_condition"]
    assert stop["reached"] is True
    assert stop["required_buy_copy_events"] == 2
    assert stop["clob_filled_buy_copy_events"] == 2
    assert stop["blockers"] == []
    assert payload["paper_only"] is True
    assert payload["live_orders_allowed"] is False


def test_live_tracker_admission_stop_condition_can_require_market_windows():
    import scripts.run_wallet_live_tracker as runner

    args = SimpleNamespace(
        stop_on_admission_evidence=True,
        stop_min_required_buy_copy_events=2,
        stop_min_clob_filled_buy_copy_events=2,
        stop_min_clob_filled_market_windows=2,
    )

    def state_for(markets: list[str]) -> dict:
        return {
            "summary": {
                "copy_efficiency": {
                    "summary": {
                        "required_buy_copy_events": len(markets),
                        "clob_filled_buy_copy_events": len(markets),
                        "fallback_filled_buy_copy_events": 0,
                        "rejected_buy_copy_events": 0,
                        "missed_buy_copy_events": 0,
                    },
                    "event_scores": [
                        {
                            "wallet_action": "BUY",
                            "copy_status": "COPIED_FILLED",
                            "fill_source": "clob_book_evidence",
                            "market_slug": market,
                        }
                        for market in markets
                    ],
                }
            }
        }

    one_window = runner._admission_evidence_stop_condition(
        state_for(["btc-updown-5m-1700000000", "btc-updown-5m-1700000000"]),
        args,
    )
    assert one_window["reached"] is False
    assert one_window["clob_filled_market_windows"] == 1
    assert "clob_filled_market_windows_below_stop_threshold" in one_window["blockers"]

    two_windows = runner._admission_evidence_stop_condition(
        state_for(["btc-updown-5m-1700000000", "btc-updown-5m-1700000300"]),
        args,
    )
    assert two_windows["reached"] is True
    assert two_windows["clob_filled_market_windows"] == 2


