def test_live_tracker_global_lock_busy_reports_lock_owner(monkeypatch, tmp_path: Path):
    import scripts.run_wallet_live_tracker as runner

    state_path = tmp_path / "tracker_state.json"
    lock_path = tmp_path / "tracker.lock"
    lock_path.write_text(
        json.dumps(
            {
                "pid": 12345,
                "started_at": "2026-06-28T18:23:11+00:00",
                "state": "data/research/owner_state.json",
            }
        ),
        encoding="utf-8",
    )

    def raise_busy(*_args, **_kwargs):
        raise BlockingIOError

    monkeypatch.setattr(runner.fcntl, "flock", raise_busy)

    result = runner._acquire_global_tracker_lock(
        SimpleNamespace(
            use_global_tracker_lock=True,
            global_tracker_lock=str(lock_path),
            state=str(state_path),
        )
    )

    assert result is False
    payload = json.loads(state_path.read_text(encoding="utf-8"))
    runtime = payload["runtime_limit"]
    assert runtime["pid"] == 12345
    assert runtime["pid_role"] == "lock_owner"
    assert runtime["lock_owner_pid"] == 12345
    assert runtime["blocked_pid"] != 12345
    assert runtime["lock_owner_state"] == "data/research/owner_state.json"


