def test_mission_runtime_policy_rejects_primary_events_above_policy_cap():
    from scripts import run_wallet_copy_live_execution

    contract = mission_contract()
    runtime_phase = contract["current_runtime_phase_contract"]
    policy_payload = run_wallet_copy_live_execution._runtime_policy_from_mission("")
    assert policy_payload["policy_id"] == "fast_wf_0.10_cap_4_all_prices_minusd_0_all_window"
    assert policy_payload["max_price"] == 0.50
    assert policy_payload["max_order_usd"] == 1.0

    aligned = run_wallet_copy_live_execution._mission_runtime_candidate_policy(
        {
            "candidate_id": "runtime_auto_degrade_32de91fa20",
            "source_wallet": "0x32de91fa203321fa7735e7854f2b1c844e71ce9d",
            "policy": {
                "policy_id": "fast_wf_0.10_cap_4_all_prices_minusd_0_all_window",
                "max_price": 1.0,
                "wallet_fraction": 0.05,
                "max_order_usd": 2.0,
            },
        }
    )
    assert aligned["policy"]["policy_id"] == policy_payload["policy_id"]
    assert aligned["policy"]["max_price"] == 0.50

    policy = CandidatePolicy(
        policy_id=policy_payload["policy_id"],
        min_price=float(policy_payload.get("min_price", 0.01)),
        max_price=float(policy_payload["max_price"]),
    )
    cheap_event = WalletEvent.from_dict({**wallet_event(price=0.50).asdict(), "window_start_s": 1_700_000_000})
    expensive_event = WalletEvent.from_dict({**wallet_event(price=0.51).asdict(), "window_start_s": 1_700_000_000})

    assert policy_accepts_event(policy, cheap_event) == (True, "accepted")
    assert policy_accepts_event(policy, expensive_event) == (False, "price_outside_policy")


