def test_relaxed_copyability_report_reprices_strict_slippage_rejects():
    from scripts.report_wallet_copy_relaxed_copyability import _copyability_profile_decision

    row = {
        "wallet_action": "BUY",
        "profit_policy_accepted": True,
        "event_age_s": 6.5,
        "clob_book_status": "OK",
        "clob_best_ask": 0.99,
        "source_price": 0.97,
        "clob_fill_ratio": 0.0,
        "clob_blocking_reason": "price_above_slippage_cap",
        "copyability_details": {
            "min_slippage_to_fill_bps": 206.185567,
            "clob_blocking_reason": "price_above_slippage_cap",
        },
    }

    strict_reason, strict_basis = _copyability_profile_decision(
        row,
        {"max_event_age_s": 10.0, "max_slippage_bps": 150.0, "min_clob_fill_ratio": 0.999},
    )
    relaxed_reason, relaxed_basis = _copyability_profile_decision(
        row,
        {"max_event_age_s": 30.0, "max_slippage_bps": 500.0, "min_clob_fill_ratio": 0.999},
    )

    assert strict_reason == "best_ask_above_profile_slippage"
    assert strict_basis is None
    assert relaxed_reason == "accepted"
    assert relaxed_basis == "relaxed_best_ask_from_min_slippage"


def test_leaderboard_onboarding_persists_preserved_state_on_http_error(tmp_path: Path):
    from scripts.onboard_leaderboard_crypto_wallets import _write_source_route_blocked_state

    output = tmp_path / "leaderboard_state.json"
    registry = tmp_path / "wallets.json"
    output.write_text(
        json.dumps(
            {
                "kind": "wallet_copy_leaderboard_crypto_state",
                "candidate_wallets": [
                    {
                        "address": "0x1111111111111111111111111111111111111111",
                        "name": "leaderboard_old",
                        "tags": ["leaderboard_crypto", "candidate"],
                    }
                ],
                "summary": {"unique_wallets": 1},
            }
        ),
        encoding="utf-8",
    )
    registry.write_text(
        json.dumps(
            {
                "wallets": [
                    {
                        "name": "leaderboard_registry",
                        "address": "0x2222222222222222222222222222222222222222",
                        "enabled": True,
                        "tags": ["leaderboard_crypto"],
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    args = SimpleNamespace(
        output=str(output),
        registry=str(registry),
        category="CRYPTO",
        order_by="PNL",
        run_pipeline=False,
        max_wallets=0,
        leaderboard_pages=0,
        leaderboard_max_pages=20,
    )

    state = _write_source_route_blocked_state(args, requests.HTTPError("503 Service Unavailable"))

    assert state["status"] == "SOURCE_ROUTE_BLOCKED"
    assert state["paper_only"] is True
    assert state["live_orders_allowed"] is False
    assert state["source_route_blocked"]["status"] == "POLYMARKET_SOURCE_FETCH_FAILED"
    assert state["source_route_blocked"]["preserved_candidate_wallets"] == 2
    assert state["summary"]["unique_wallets"] == 2
    assert {row["address"] for row in state["candidate_wallets"]} == {
        "0x1111111111111111111111111111111111111111",
        "0x2222222222222222222222222222222222222222",
    }


