def test_fast_candidate_policies_cover_middle_market_window():
    policies = fast_candidate_policies()
    early = wallet_event(price=0.58, size=20.0, timestamp=1_700_000_030)
    middle = wallet_event(price=0.58, size=20.0, timestamp=1_700_000_149)
    late = wallet_event(price=0.58, size=20.0, timestamp=1_700_000_240)

    early_matches = [policy.policy_id for policy in policies if policy_accepts_event(policy, early)[0]]
    middle_matches = [policy.policy_id for policy in policies if policy_accepts_event(policy, middle)[0]]
    late_matches = [policy.policy_id for policy in policies if policy_accepts_event(policy, late)[0]]

    assert any(policy_id.endswith("_first_90s") for policy_id in early_matches)
    assert any(policy_id.endswith("_middle_90s") for policy_id in middle_matches)
    assert any(policy_id.endswith("_last_120s") for policy_id in late_matches)


