def test_gamma_resolution_fetch_uses_measured_source_route_client(monkeypatch):
    import scripts.refresh_btc_5m_resolutions_from_gamma as gamma

    calls = []

    class FakeClient:
        def __init__(self, *, timeout_s, retries, user_agent):
            calls.append({"init_timeout_s": timeout_s, "retries": retries, "user_agent": user_agent})

        def get_json(self, url, *, params, headers, request_role, timeout_s):
            calls.append(
                {
                    "url": url,
                    "params": params,
                    "headers": headers,
                    "request_role": request_role,
                    "timeout_s": timeout_s,
                }
            )
            return (
                [
                    {
                        "markets": [
                            {
                                "closed": True,
                                "clobTokenIds": json.dumps(["yes-token", "no-token"]),
                                "conditionId": "0xcond",
                                "outcomePrices": json.dumps(["1", "0"]),
                                "outcomes": json.dumps(["Up", "Down"]),
                                "question": "Bitcoin Up or Down - 5 minutes",
                                "slug": "btc-updown-5m-1782374700",
                                "umaResolutionStatus": "resolved",
                            }
                        ]
                    }
                ],
                {"route_class": "DIRECT_PASS"},
            )

    monkeypatch.setattr(gamma, "PolymarketHttpClient", FakeClient)

    row = gamma.fetch_gamma_resolution("btc-updown-5m-1782374700", timeout_s=2.5, user_agent="unit-agent")

    assert row is not None
    assert row["direction"] == "UP"
    assert calls[0] == {"init_timeout_s": 2.5, "retries": 1, "user_agent": "unit-agent"}
    assert calls[1]["url"] == gamma.GAMMA_EVENTS_URL
    assert calls[1]["params"] == {"slug": "btc-updown-5m-1782374700"}
    assert calls[1]["request_role"] == "gamma_resolution_refresh"
    assert calls[1]["headers"]["Origin"] == "https://polymarket.com"


