def test_gamma_resolution_commit_rereads_and_preserves_concurrent_union(tmp_path: Path):
    import scripts.refresh_btc_5m_resolutions_from_gamma as gamma

    output = tmp_path / "resolutions.jsonl"

    def row(idx: int) -> dict:
        return {
            "condition_id": f"0x{idx}",
            "market_slug": f"btc-updown-5m-{1780000000 + idx * 300}",
            "expiry_unix_ts": 1780000300 + idx * 300,
            "direction": "UP",
        }

    gamma._atomic_write_rows(output, [row(1)])
    first = gamma._locked_merge_and_write_rows(
        existing_path=str(output),
        output_path=output,
        generated_rows=[row(2)],
        merge_existing=True,
    )
    second = gamma._locked_merge_and_write_rows(
        existing_path=str(output),
        output_path=output,
        generated_rows=[row(3)],
        merge_existing=True,
    )

    assert [item["condition_id"] for item in first] == ["0x1", "0x2"]
    assert [item["condition_id"] for item in second] == ["0x1", "0x2", "0x3"]
    persisted = [json.loads(line) for line in output.read_text(encoding="utf-8").splitlines()]
    assert [item["condition_id"] for item in persisted] == ["0x1", "0x2", "0x3"]
    assert list(tmp_path.glob(".resolutions.jsonl.*.tmp")) == []


def test_gamma_resolution_refresh_defaults_to_history_preserving_merge(monkeypatch):
    import scripts.refresh_btc_5m_resolutions_from_gamma as gamma

    monkeypatch.setattr(sys, "argv", ["refresh_btc_5m_resolutions_from_gamma.py"])
    assert gamma.parse_args().merge_existing is True

    monkeypatch.setattr(
        sys,
        "argv",
        ["refresh_btc_5m_resolutions_from_gamma.py", "--replace-existing"],
    )
    assert gamma.parse_args().merge_existing is False


def adaptive_move(
    *,
    wallet: str,
    wallet_name: str,
    outcome: str = "Up",
    market_slug: str = "btc-updown-5m-1700000000",
    condition_id: str = "0xcond",
    token_id: str = "token-up",
    price: float = 0.42,
    usdc_size: float = 1.0,
    event_ts: float = 1_700_000_002.0,
    generated_at: str = "2023-11-14T22:13:24+00:00",
    event_age_s: float = 2.0,
) -> dict:
    return {
        "event": "wallet_copy_live_tracked_move",
        "generated_at": generated_at,
        "action": "BUY",
        "source_wallet": wallet,
        "wallet_name": wallet_name,
        "source_event_id": f"we-{wallet}-{outcome}-{price}",
        "source_fingerprint": f"wef-{wallet}-{outcome}-{price}",
        "condition_id": condition_id,
        "market_slug": market_slug,
        "outcome": outcome,
        "source_price": price,
        "source_usdc_size": usdc_size,
        "event_ts": event_ts,
        "token_id": token_id,
        "wallet_event": {
            "action": "BUY",
            "source_wallet": wallet,
            "wallet_name": wallet_name,
            "event_id": f"we-{wallet}-{outcome}-{price}",
            "source_fingerprint": f"wef-{wallet}-{outcome}-{price}",
            "condition_id": condition_id,
            "market_slug": market_slug,
            "outcome": outcome,
            "price": price,
            "usdc_size": usdc_size,
            "event_ts": event_ts,
            "observed_ts": event_ts + event_age_s,
            "token_id": token_id,
        },
        "copyability": {"accepted": True, "reason": "accepted"},
        "tracking_evidence": {
            "clob_book": {
                "status": "OK",
                "instant_fill_status": "PASS",
                "best_ask": price,
                "best_bid": max(0.0, price - 0.01),
                "spread": 0.01,
                "source_price": price,
                "max_copy_price": price + 0.02,
                "fillable_usd": 10.0,
                "fillable_shares": round(10.0 / price, 6),
                "avg_fill_price": price,
                "fill_ratio": 1.0,
                "blocking_reason": "none",
                "token_id": token_id,
                "book_hash": f"book-{token_id}",
            }
        },
        "copy_efficiency": {
            "wallet_action": "BUY",
            "copy_status": "COPIED_FILLED",
            "copyability_accepted": True,
            "clob_book_status": "OK",
            "clob_fill_ratio": 1.0,
            "fill_source": "clob_book_evidence",
            "event_age_s": event_age_s,
            "source_price": price,
            "source_usdc_size": usdc_size,
        },
    }


