def test_adaptive_bot_builds_paper_intent_from_fresh_clob_wallet_consensus():
    cfg = AdaptiveBotConfig(min_agreeing_wallets=2, max_order_usd=2.0, min_order_usd=0.1)
    moves = [
        adaptive_move(wallet="0xaaa", wallet_name="alpha", price=0.41, usdc_size=4.0),
        adaptive_move(wallet="0xbbb", wallet_name="bravo", price=0.43, usdc_size=3.0),
    ]

    signals, summary = build_adaptive_signals(moves, config=cfg, now_ts=1_700_000_004.0)
    intent = signal_to_intent(signals[0], config=cfg)

    assert summary["eligible_moves"] == 2
    assert signals[0].status == "PASS"
    assert signals[0].agreeing_wallets == ("0xaaa", "0xbbb")
    assert intent is not None
    assert intent.source_wallet == "ADAPTIVE_WALLET_DERIVED"
    assert intent.policy_id == "adaptive_fresh_clob_consensus_v1"
    assert intent.live_orders_allowed is False
    assert intent.metadata["live_tracking_evidence"]["clob_book"]["status"] == "OK"


