def test_adaptive_bot_reports_tracker_fresh_rows_that_are_runtime_stale():
    cfg = AdaptiveBotConfig(max_observed_event_age_s=10.0, max_observation_age_s=1_000.0)
    moves = [
        adaptive_move(
            wallet="0xaaa",
            wallet_name="alpha",
            price=0.41,
            event_ts=1_700_000_000.0,
            event_age_s=2.0,
        )
    ]

    signals, summary = build_adaptive_signals(moves, config=cfg, now_ts=1_700_000_100.0)
    diagnostics = summary["freshness_diagnostics"]

    assert signals == []
    assert summary["eligible_moves"] == 0
    assert summary["filter_reason_counts"] == {"event_age_above_cap": 1}
    assert diagnostics["buy_events"] == 1
    assert diagnostics["tracker_fresh_buy_events_le_cap"] == 1
    assert diagnostics["runtime_fresh_buy_events_le_cap"] == 0
    assert diagnostics["tracker_fresh_but_runtime_stale"] is True
    assert diagnostics["latest_buy_event_lag_s"] == 100.0
    assert diagnostics["freshness_transition_counts"] == {"tracker_fresh_became_runtime_stale": 1}
    transition = diagnostics["freshness_transition_rows"][0]
    assert transition["source_wallet"] == "0xaaa"
    assert transition["market_slug"] == "btc-updown-5m-1700000000"
    assert transition["tracker_event_age_s"] == 2.0
    assert transition["runtime_event_age_s"] == 100.0
    assert transition["runtime_minus_tracker_age_s"] == 98.0
    assert transition["tracker_latency_budget_remaining_s"] == 8.0
    assert transition["tracker_fresh"] is True
    assert transition["runtime_fresh"] is False
    assert transition["runtime_filter_reason"] == "event_age_above_cap"
    assert diagnostics["top_filter_reasons_by_wallet"][0]["top_reason"] == "event_age_above_cap"


