def test_hotlane_tick_tracker_argv_can_expand_to_cohort_probe():
    from scripts.run_wallet_copy_hotlane_tick import build_tracker_argv

    args = SimpleNamespace(
        registry="registry.json",
        tracker_state="tracker.json",
        tracker_event_log="tracker.jsonl",
        paper_state="paper.json",
        paper_event_log="paper.jsonl",
        tracker_time_replay_paper_state="tracker_time_replay_paper.json",
        tracker_time_replay_paper_event_log="tracker_time_replay_paper.jsonl",
        single_wallet_exact_copy_paper_state="single_wallet_paper.json",
        single_wallet_exact_copy_paper_event_log="single_wallet_paper.jsonl",
        profit_policy_state="profit.json",
        seed_history_state="history.json",
        limit=5,
        pages=1,
        data_api_timeout_s=1.0,
        max_poll_runtime_s=8.0,
        max_runtime_s=15.0,
        tracker_iterations=6,
        tracker_poll_interval_s=0.5,
        wallets_per_tick=2,
        parallel_wallet_fetches=2,
        parallel_data_api_sources=True,
        clob_timeout_s=0.8,
        gamma_timeout_s=0.8,
    )

    argv = build_tracker_argv(
        args,
        max_wallets_override=4,
        parallel_wallet_fetches_override=4,
        limit_override=12,
        pages_override=2,
        wallet_addresses_override=["0xbbb", "0xccc"],
        max_runtime_override_s=7.5,
    )

    assert argv[argv.index("--max-wallets") + 1] == "4"
    assert argv[argv.index("--parallel-wallet-fetches") + 1] == "4"
    assert "--parallel-data-api-sources" in argv
    assert argv[argv.index("--limit") + 1] == "12"
    assert argv[argv.index("--pages") + 1] == "2"
    assert argv[argv.index("--data-api-trade-query-keys") + 1] == "user,proxyWallet"
    assert argv[argv.index("--max-runtime-s") + 1] == "7.5"
    assert argv[argv.index("--iterations") + 1] == "1"
    assert argv[argv.index("--poll-interval-s") + 1] == "0.0"
    assert argv[argv.index("--tracker-time-replay-paper-state") + 1] == "tracker_time_replay_paper.json"
    assert argv[argv.index("--tracker-time-replay-paper-event-log") + 1] == "tracker_time_replay_paper.jsonl"
    assert argv[argv.index("--single-wallet-exact-copy-paper-state") + 1] == "single_wallet_paper.json"
    assert argv[argv.index("--single-wallet-exact-copy-paper-event-log") + 1] == "single_wallet_paper.jsonl"
    assert "--no-include-activity" not in argv
    assert argv.count("--wallet-address") == 2
    first_wallet = argv.index("--wallet-address")
    second_wallet = argv.index("--wallet-address", first_wallet + 1)
    assert argv[first_wallet + 1] == "0xbbb"
    assert argv[second_wallet + 1] == "0xccc"
    assert "--no-use-profit-search-scope" in argv


