def test_hotlane_tracker_snapshot_surfaces_current_poll_root_cause(tmp_path: Path):
    from scripts.run_wallet_copy_hotlane_tick import _tracker_snapshot

    tracker_state = tmp_path / "tracker.json"
    tracker_state.write_text(
        json.dumps(
            {
                "summary": {
                    "new_wallet_events": 0,
                    "tracker_scope": {"wallets_tracked": 18},
                    "copy_efficiency": {"status": "WATCH", "summary": {"source_fresh_buy_events_le_10s": 0}},
                    "current_poll_diagnostics": {
                        "blockers": ["current_poll_source_route_partial"],
                        "zero_current_poll_root_cause": "source_route_partial",
                        "fresh_buy_loss_stage": "all_source_rows_deduped_or_deferred",
                        "source_route_status_counts": {"PASS": 50, "HTTP_NON_2XX": 19},
                        "source_route_class_counts": {"ROUTE_RECOVERED_DEGRADED": 25},
                        "current_poll_source_freshness_by_source": {
                            "trade:user": {"fresh_buy_rows_le_10s": 0, "fresh_buy_rows_le_30s": 2}
                        },
                        "current_poll_ladder": {
                            "raw_rows": 125,
                            "normalized_events": 60,
                            "after_dedupe_events": 0,
                            "runtime_limited_events_skipped": 42,
                        },
                    },
                    "wallet_reports": [
                        {
                            "runtime_limited_buy_events_skipped": 4,
                            "runtime_limited_fresh_buy_events_skipped": 0,
                        },
                        {
                            "runtime_limited_buy_events_skipped": 3,
                            "runtime_limited_fresh_buy_events_skipped": 1,
                        },
                    ],
                    "hot_path_adaptive": {
                        "status": "WATCH",
                        "blockers": ["no_current_poll_moves"],
                        "summary": {"current_poll_moves": 0, "pass_signals": 0},
                    },
                }
            }
        ),
        encoding="utf-8",
    )

    snapshot = _tracker_snapshot(tracker_state)

    assert snapshot["current_poll_zero_current_poll_root_cause"] == "source_route_partial"
    assert snapshot["current_poll_fresh_buy_loss_stage"] == "all_source_rows_deduped_or_deferred"
    assert snapshot["current_poll_blockers"] == ["current_poll_source_route_partial"]
    assert snapshot["current_poll_ladder"]["runtime_limited_events_skipped"] == 42
    assert snapshot["current_poll_ladder"]["runtime_limited_buy_events_skipped"] == 7
    assert snapshot["current_poll_ladder"]["runtime_limited_fresh_buy_events_skipped"] == 1
    assert snapshot["current_poll_source_route_status_counts"] == {"PASS": 50, "HTTP_NON_2XX": 19}
    assert snapshot["current_poll_source_freshness_by_source"]["trade:user"]["fresh_buy_rows_le_30s"] == 2


