def test_active_forward_probe_selector_adds_operator_mission_anchor_probe():
    from scripts.select_wallet_copy_active_forward_probe import select_active_forward_probe

    anchor_wallet = "0xb27bc932bf8110d8f78e55da7d5f0497a18b5b82"
    active_hotlane = {
        "selected_wallets": [
            {
                "address": "0x9412cdfc1e3171e1aabb013d0f494986445d0cd0",
                "latest_live_event_lag_s": 5.0,
                "live_btc5m_buys": 8,
            },
            {
                "address": anchor_wallet,
                "name": "operator_wallet_0xb27bc932",
                "tags": ["operator_mission_anchor", "short_window_edge"],
                "mission_anchor_reason": "operator_mission_anchor_must_remain_current_poll_measured",
                "latest_live_event_lag_s": 98621.8,
                "history_btc5m_buys": 701,
                "score": 91.0,
            },
        ]
    }
    profit = {
        "forward_candidate": {
            "status": "BLOCKED",
            "candidate_id": "current_forward",
            "candidate_type": "SINGLE_WALLET",
            "source_wallet": "0x9412cdfc1e3171e1aabb013d0f494986445d0cd0",
            "policy": {"policy_id": "p_current"},
            "blockers": ["candidate_missing_clob_fill_evidence"],
            "forward_queue_rank": 0,
        }
    }

    payload = select_active_forward_probe(profit, active_hotlane)

    assert payload["paper_only"] is True
    assert payload["live_orders_allowed"] is False
    assert payload["mission_anchor_probe_candidates_added"] == 1
    assert payload["mission_anchor_wallets"] == [anchor_wallet]
    assert payload["operator_mission_anchor_wallets"] == [anchor_wallet]
    assert payload["decision"]["reason"] == "operator_mission_anchor_forward_probe_selected"
    assert payload["selected_probe"]["source_wallet"] == anchor_wallet
    assert payload["selected_probe"]["candidate_id"] == "mission_anchor_b27bc932bf81"
    assert payload["selected_probe"]["policy_id"].startswith("mission_anchor_fast_wf_0.10_cap_4_all_prices")
    assert "operator_mission_anchor_probe" in payload["selected_probe"]["probe_selection_reasons"]
    assert payload["ranked_probe_candidates"][0]["mission_anchor_probe"] is True
    assert "active_forward_probe_not_live_admission_truth" in payload["decision"]["live_admission_blockers"]
    assert "candidate_blocker:mission_anchor_needs_current_poll_clob_truth" in payload["decision"]["live_admission_blockers"]


