def test_hotlane_tick_summarizes_adaptive_freshness_transition_loss():
    from scripts.run_wallet_copy_hotlane_tick import (
        _aggregate_adaptive_freshness_counter,
        _top_adaptive_freshness_transitions,
    )

    rows = [
        {
            "active_measurement": "cohort_probe",
            "adaptive": {
                "freshness_diagnostics": {
                    "freshness_transition_counts": {
                        "tracker_fresh_became_runtime_stale": 2,
                        "runtime_fresh_copyability_rejected": 1,
                    },
                    "freshness_transition_rows": [
                        {
                            "source_wallet": "0xaaa",
                            "market_slug": "btc-updown-5m-1700000000",
                            "outcome": "Up",
                            "tracker_event_age_s": 2.0,
                            "runtime_event_age_s": 9.5,
                            "transition_reason": "tracker_fresh_became_runtime_stale",
                        }
                    ],
                }
            },
        },
        {
            "active_measurement": "slice",
            "adaptive": {
                "freshness_diagnostics": {
                    "freshness_transition_counts": {"tracker_fresh_became_runtime_stale": 3},
                    "freshness_transition_rows": [
                        {
                            "source_wallet": "0xbbb",
                            "market_slug": "btc-updown-5m-1700000300",
                            "outcome": "Down",
                            "transition_reason": "tracker_fresh_became_runtime_stale",
                        }
                    ],
                }
            },
        },
    ]

    assert _aggregate_adaptive_freshness_counter(rows, "freshness_transition_counts") == {
        "runtime_fresh_copyability_rejected": 1,
        "tracker_fresh_became_runtime_stale": 5,
    }
    transitions = _top_adaptive_freshness_transitions(rows, max_observed_event_age_s=10.0)
    assert transitions[0]["active_measurement"] == "cohort_probe"
    assert transitions[0]["source_wallet"] == "0xaaa"
    assert transitions[0]["runtime_minus_tracker_age_s"] == 7.5
    assert transitions[0]["tracker_latency_budget_remaining_s"] == 8.0
    assert transitions[1]["active_measurement"] == "slice"


