def test_sweeper_profile_detects_high_price_near_close_wallet():
    events = []
    for index in range(25):
        events.append(
            {
                "source_wallet": "0xsweep",
                "wallet_name": "sweeper",
                "action": "BUY",
                "market_slug": "btc-updown-5m-1700000000",
                "outcome": "Up",
                "price": 0.99,
                "usdc_size": 9.9,
                "event_ts": 1700000280 + index % 5,
                "event_id": f"we_sweep_{index}",
            }
        )
    for index in range(25):
        events.append(
            {
                "source_wallet": "0xearly",
                "wallet_name": "early",
                "action": "BUY",
                "market_slug": "btc-updown-5m-1700000000",
                "outcome": "Down",
                "price": 0.42,
                "usdc_size": 4.2,
                "event_ts": 1700000050 + index,
                "event_id": f"we_early_{index}",
            }
        )

    assert extract_btc_5m_window_start(events[0]) == 1700000000
