def test_wallet_history_parallel_sources_keep_all_source_coverage():
    class FakeClient(WalletHistoryClient):
        def fetch_trades(self, *, limit: int = 500, offset: int = 0):
            return [wallet_raw_row("trade") | {"transactionHash": "0xuser", "timestamp": 1_700_000_000}]

        def fetch_proxy_wallet_trades(self, *, limit: int = 500, offset: int = 0):
            return [wallet_raw_row("proxy") | {"transactionHash": "0xproxy", "timestamp": 1_700_000_001}]

        def fetch_activity(self, *, limit: int = 500, offset: int = 0):
            return [wallet_raw_row("activity") | {"transactionHash": "0xactivity", "timestamp": 1_700_000_002}]

    client = FakeClient(WalletSpec(name="alpha", address="0xabc"))

