def test_wallet_history_keeps_proxy_wallet_events_when_user_trade_source_times_out():
    class FakeClient(WalletHistoryClient):
        def fetch_trades(self, *, limit: int = 500, offset: int = 0):
            object.__setattr__(
                self,
                "last_route_report",
                {
                    "status": "TRANSPORT_ERROR",
                    "host": "data-api.polymarket.com",
                    "original_host": "data-api.polymarket.com",
                    "routed_host": "data-api.polymarket.com",
                    "attempts": [{"status": "ERROR", "exception": "ReadTimeout"}],
                },
            )
            raise requests.ReadTimeout("user source timeout")

        def fetch_proxy_wallet_trades(self, *, limit: int = 500, offset: int = 0):
            return [wallet_raw_row("proxy") | {"transactionHash": "0xproxy"}]

        def fetch_activity(self, *, limit: int = 500, offset: int = 0):
            return []

    client = FakeClient(WalletSpec(name="alpha", address="0xabc"))

    events = client.fetch_events(limit=10, include_activity=True)

    assert len(events) == 1
    assert events[0].transaction_hash == "0xproxy"
    assert client.last_fetch_report["ingest_status"] == "PARTIAL"
    assert client.last_fetch_report["api_error"]["endpoint"] == "trades:user"
    assert client.last_fetch_report["api_errors"][0]["source"] == "trade:user"
    assert client.last_fetch_report["api_errors"][0]["route_report"]["status"] == "TRANSPORT_ERROR"
    assert client.last_fetch_report["source_route_status_by_source"]["trade:user"] == "TRANSPORT_ERROR"
    assert "partial_data_api_source_error" in client.last_fetch_report["blockers"]


