def test_wallet_history_records_api_timeout_without_crashing(monkeypatch):
    seen_timeouts = []
    started = time.monotonic()

    def fake_request(self, method, url, **kwargs):
        seen_timeouts.append(kwargs.get("timeout"))
        raise requests.ReadTimeout("unit timeout")

    monkeypatch.setattr(requests.Session, "request", fake_request)
    client = WalletHistoryClient(
        WalletSpec(name="alpha", address="0xabc"),
        connect_timeout_s=0.25,
        read_timeout_s=0.5,
        retries=2,
    )

    events = client.fetch_events(limit=10, include_activity=True, pages=1)

    assert events == []
    assert time.monotonic() - started < 5.0
    assert len(seen_timeouts) <= 18
    assert seen_timeouts
    assert set(seen_timeouts) == {(0.25, 0.5)}
    assert client.last_fetch_report["stop_reason"] == "api_error_ReadTimeout"
    assert client.last_fetch_report["api_error"]["endpoint"] == "trades:user"
    assert client.last_fetch_report["api_error"]["type"] == "ReadTimeout"
    assert client.last_fetch_report["api_error"]["skip_reason"] == "data_api_ReadTimeout_skip_after_bounded_retries"
    assert client.last_fetch_report["api_error"]["bounded_retry_count"] == 1
    assert client.last_fetch_report["api_error"]["timeout_connect_s"] == 0.25
    assert client.last_fetch_report["api_error"]["timeout_read_s"] == 0.5
    assert client.last_fetch_report["data_api_skip_rows"][0]["source"] == "trade:user"


