def test_copy_intent_mirrors_wallet_outcome_and_fraction_cap():
    event = wallet_event()
    policy = CopyPolicy(
        sizing=SizingPolicy(
            policy_id="wallet_fraction_0500_cap_1",
            wallet_fraction=0.5,
            max_order_usd=1.0,
        )
    )

    intent = event_to_intent(event, policy=policy)

    assert intent is not None
    assert intent.side == "YES"
    assert intent.copy_size_usd == 1.0
    assert intent.shares == round(1.0 / 0.42, 6)
    assert intent.live_orders_allowed is False


def test_copy_policy_rejects_unsupported_outcome_without_raising():
    event = wallet_event(outcome="Australia")
    policy = CopyPolicy()

    accepted, reason = policy.accepts(event)
    intent = event_to_intent(event, policy=policy)

    assert accepted is False
    assert reason == "unsupported_outcome"
    assert intent is None


def test_paper_engine_records_full_lifecycle_and_dedupes(tmp_path: Path):
    event = wallet_event()
    intents = build_intents([event])
    engine = PaperWalletCopyEngine(
        PaperExecutionConfig(
            state_path=str(tmp_path / "paper_state.json"),
            event_log_path=str(tmp_path / "paper_events.jsonl"),
            fallback_slippage_bps=0.0,
        )
    )

    first = engine.apply_intents(intents)
    second = engine.apply_intents(intents)

    assert first["summary"]["paper_orders"] == 1
    assert second["summary"]["paper_orders"] == 1
    assert second["summary"]["fill_source_counts"] == {"source_price_plus_slippage_fallback": 1}
    order = second["orders"][0]
    assert order["paper_only"] is True
    assert order["live_orders_allowed"] is False
    assert [row["status"] for row in order["lifecycle"]] == [
        "INTENT_RECEIVED",
        "PAPER_SUBMITTED",
        "PAPER_FILLED",
    ]


def test_paper_engine_dedupes_orders_after_retention_trims_state(tmp_path: Path):
    state_path = tmp_path / "paper_state.json"
