def test_recent_event_log_moves_reads_tail_window(tmp_path: Path):
    from src.wallet_copy.live_tracker import _recent_event_log_moves

    path = tmp_path / "moves.jsonl"
    with path.open("w", encoding="utf-8") as handle:
        handle.write("{not-json}\n")
        for index in range(300):
            handle.write(
                json.dumps(
                    {
                        "event": "wallet_copy_live_move",
                        "wallet_event": {"event_id": f"event_{index}"},
                    }
                )
                + "\n"
            )

    moves = _recent_event_log_moves(str(path), limit=3)

    assert [row["wallet_event"]["event_id"] for row in moves] == ["event_297", "event_298", "event_299"]


def test_paper_engine_reset_existing_state_is_consumed_once(tmp_path: Path):
    state_path = str(tmp_path / "paper_state.json")
    event_log_path = str(tmp_path / "paper_events.jsonl")
    old_event = wallet_event(condition="0xold")
    new_event = wallet_event(condition="0xnew")

    PaperWalletCopyEngine(
        PaperExecutionConfig(
            state_path=state_path,
            event_log_path=event_log_path,
            fallback_slippage_bps=0.0,
        )
    ).apply_intents(build_intents([old_event]))

    reset_engine = PaperWalletCopyEngine(
        PaperExecutionConfig(
            state_path=state_path,
            event_log_path=event_log_path,
            fallback_slippage_bps=0.0,
            reset_existing_state=True,
        )
    )
    reset_engine.apply_intents(build_intents([new_event]))
    state = reset_engine.apply_wallet_lifecycle_events([new_event])

    assert state["summary"]["paper_orders"] == 1
    assert state["orders"][0]["condition_id"] == "0xnew"


def test_paper_engine_rejects_unfillable_clob_book_intent(tmp_path: Path):
    event = wallet_event()
    intent = event_to_intent(event)
    assert intent is not None
    payload = intent.asdict()
    payload["metadata"] = {
        "live_tracking_evidence": {
            "clob_book": {
                "status": "OK",
                "fill_ratio": 0.25,
                "fillable_usd": 0.25,
                "avg_fill_price": 0.42,
                "book_hash": "thin",
            }
        }
    }
    intent = type(intent).from_dict(payload)
    engine = PaperWalletCopyEngine(
        PaperExecutionConfig(
            state_path=str(tmp_path / "paper_state.json"),
            event_log_path=str(tmp_path / "paper_events.jsonl"),
            fallback_slippage_bps=0.0,
        )
    )

    state = engine.apply_intents([intent])

    assert state["summary"]["paper_orders"] == 1
    assert state["summary"]["filled_orders"] == 0
    assert state["summary"]["rejected_orders"] == 1
    assert state["orders"][0]["final_status"] == "REJECTED"
    assert state["orders"][0]["lifecycle"][-1]["status"] == "SKIPPED"


