    assert actionability["micro_batch_actionability_blockers"] == [
        "micro_batch_does_not_improve_strict_fill_count",
        "micro_batch_rejected_child_events_present",
        "micro_batch_requires_overcopy_not_live_admission",
    ]
    assert diagnostics["micro_min_order_actionability"] == actionability
    exact_gap = actionability["micro_batch_exact_no_overcopy_diagnostics"]
    assert exact_gap["status"] == "CORRECTION"
    assert exact_gap["coverage_gap_child_events"] == 2
    assert "no_exact_no_overcopy_probe_groups" in exact_gap["blockers"]
    assert exact_gap["paper_only"] is True
    assert exact_gap["live_orders_allowed"] is False
    assert diagnostics["recommended_repair_lane"] == (
        "diagnose_exact_no_overcopy_micro_copy_before_batching"
    )
    assert dominant_lane["role"] == "paper_only_dominant_tactic_lane_not_live_admission"
    assert dominant_lane["lane_id"] == "micro_min_order_exact_no_overcopy"
    assert dominant_lane["actionable_for_paper_replay"] is False
    assert dominant_lane["paper_only"] is True
    assert dominant_lane["live_orders_allowed"] is False
    assert "micro_min_order_probe_not_actionable_for_repair" in dominant_lane["blockers"]
    assert diagnostics["dominant_paper_tactic_lane"] == dominant_lane
    assert "micro_min_order_probe_not_actionable_for_repair" in plan["blockers"]


