def test_paper_engine_applies_merge_and_redeem_lifecycle(tmp_path: Path):
    events = [
        wallet_event(outcome="Up"),
        wallet_event(outcome="Down"),
    ]
    engine = PaperWalletCopyEngine(
        PaperExecutionConfig(
            state_path=str(tmp_path / "paper_state.json"),
            event_log_path=str(tmp_path / "paper_events.jsonl"),
            fallback_slippage_bps=0.0,
        )
    )
    engine.apply_intents(build_intents(events))

    state = engine.apply_wallet_lifecycle_events([lifecycle_event("MERGE", size=2.0)])
    positions = list((state.get("positions") or {}).values())
    assert all(float(row["shares"]) == 8.0 for row in positions)
    assert state["lifecycle_events"][-1]["position_reduction"]["status"] == "MERGED_PAIR_REDUCED"

    state = engine.apply_wallet_lifecycle_events([lifecycle_event("REDEEM", outcome="Up", size=0.0)])
    up_position = next(row for row in (state.get("positions") or {}).values() if row["outcome"] == "Up")
    assert up_position["shares"] == 0.0
    assert state["lifecycle_events"][-1]["position_reduction"]["status"] == "REDEEMED_POSITION_REDUCED"
    assert state["lifecycle_events"][-1]["position_reduction"]["realized_pnl_usd"] > 0


def test_paper_lifecycle_scales_sell_and_redeem_proceeds_to_copied_shares(tmp_path: Path):
    event = wallet_event(price=0.5, size=200.0)
    policy = CopyPolicy(
        sizing=SizingPolicy(
            policy_id="wallet_fraction_0020_cap_2",
            wallet_fraction=0.02,
            max_order_usd=2.0,
        )
    )
    engine = PaperWalletCopyEngine(
        PaperExecutionConfig(
            state_path=str(tmp_path / "paper_state.json"),
            event_log_path=str(tmp_path / "paper_events.jsonl"),
            fallback_slippage_bps=0.0,
        )
    )
    engine.apply_intents(build_intents([event], policy=policy))

    sell = lifecycle_event("SELL", size=100.0, price=0.9, usdc_size=90.0)
    state = engine.apply_wallet_lifecycle_events([sell])
    reduction = state["lifecycle_events"][-1]["position_reduction"]

    assert reduction["reduced_shares"] == 4.0
    assert reduction["proceeds_usd"] == 3.6
    assert reduction["source_proceeds_usd"] == 90.0
    assert reduction["proceeds_scaling_ratio"] == 0.04
    assert reduction["proceeds_basis"] == "source_wallet_usdc_pro_rata"

    next_event = wallet_event(price=0.5, size=200.0, condition="0xredeem", timestamp=1_700_000_001)
    next_intents = build_intents([next_event], policy=policy)
    engine.apply_intents(next_intents)
    redeem = lifecycle_event("REDEEM", condition="0xredeem", size=100.0, usdc_size=100.0, timestamp=1_700_000_002)
    state = engine.apply_wallet_lifecycle_events([redeem])
    reduction = state["lifecycle_events"][-1]["position_reduction"]

    assert reduction["proceeds_usd"] == 4.0
    assert reduction["source_proceeds_usd"] == 100.0
    assert reduction["proceeds_scaling_ratio"] == 0.04


def test_paper_engine_replays_wallet_events_in_source_order(tmp_path: Path):
    early_redeem = lifecycle_event("REDEEM", size=0.0, timestamp=1_700_000_000)
    late_buy = wallet_event(timestamp=1_700_000_100)
    intent = event_to_intent(late_buy)
