def test_leaderboard_fetch_falls_back_direct_after_relay_5xx(monkeypatch):
    import src.wallet_copy.leaderboard as leaderboard_mod

    monkeypatch.setenv("POLYMARKET_DATA_API_BASE_URL", "http://127.0.0.1:8787/data-api")
    calls: list[dict[str, object]] = []

    class FakeResponse:
        def __init__(self, status_code: int, payload: list[dict[str, object]], route_report: dict[str, object]) -> None:
            self.status_code = status_code
            self._payload = payload
            self.wallet_copy_route_report = route_report

        def raise_for_status(self) -> None:
            if self.status_code >= 400:
                raise requests.HTTPError(f"{self.status_code} synthetic")

        def json(self) -> list[dict[str, object]]:
            return self._payload

    class FakeClient:
        def __init__(self, **_kwargs: object) -> None:
            pass

        def request(self, _method: str, _url: str, *, params: dict[str, object], request_role: str, **_kwargs: object) -> FakeResponse:
            relay_configured = bool(os.environ.get("POLYMARKET_DATA_API_BASE_URL"))
            calls.append({"relay_configured": relay_configured, "request_role": request_role, "offset": params.get("offset")})
            if relay_configured:
                return FakeResponse(
                    503,
                    [],
                    {
                        "status": "HTTP_NON_2XX",
                        "route_class": "ROUTE_RECOVERED_DEGRADED",
                        "source_base_override_configured": True,
                        "source_base_override_env_var": "POLYMARKET_DATA_API_BASE_URL",
                        "attempts": [{"http_status": 503}],
                    },
                )
            return FakeResponse(
                200,
                [
                    {
                        "proxyWallet": "0x0000000000000000000000000000000000000abc",
                        "rank": 1,
                        "pnl": "12.5",
                    }
                ],
                {
                    "status": "PASS",
                    "route_class": "DIRECT_PASS",
                    "source_base_override_configured": False,
                    "attempts": [{"http_status": 200}],
                    "route_report_id": "rr_direct",
                },
            )

    monkeypatch.setattr(leaderboard_mod, "PolymarketHttpClient", FakeClient)

    rows = leaderboard_mod.fetch_leaderboard(limit=50, offset=0)

    assert [call["relay_configured"] for call in calls] == [True, False]
    assert os.environ["POLYMARKET_DATA_API_BASE_URL"] == "http://127.0.0.1:8787/data-api"
    assert len(rows) == 1
    assert rows[0].normalized_address() == "0x0000000000000000000000000000000000000abc"
    assert rows[0].route_report["fallback_source"] == "direct_data_api_after_primary_failure"
    assert rows[0].route_report["suppressed_env_var"] == "POLYMARKET_DATA_API_BASE_URL"
    assert rows[0].route_report["primary_route_report"]["http_statuses"] == [503]
    assert rows[0].route_report["direct_route_report"]["route_class"] == "DIRECT_PASS"


