def test_e5_maker_quote_fills_only_on_later_crossing_sell():
    import scripts.run_maker_first_btc5m_paper_lane as runner
    from scripts.run_whale_consensus_paper_lane import WhaleConsensusFeedEvent

    base = 1_783_284_000.0
    signal_event = WhaleConsensusFeedEvent(
        source_wallet="0x0000000000000000000000000000000000000aaa",
        market_slug=f"btc-updown-5m-{int(base)}",
        condition_id="cond",
        outcome="Up",
        side="BUY",
        price=0.50,
        size=10.0,
        event_ts=base + 20,
        observed_ts=base + 21,
        token_id="up-token",
        transaction_hash="0x1",
        event_id="buy-1",
    )
    later_buy = WhaleConsensusFeedEvent(
        source_wallet="0x0000000000000000000000000000000000000bbb",
        market_slug=f"btc-updown-5m-{int(base)}",
        condition_id="cond",
        outcome="Up",
        side="BUY",
        price=0.48,
        size=10.0,
        event_ts=base + 23,
        observed_ts=base + 24,
        token_id="up-token",
        transaction_hash="0x2",
        event_id="buy-2",
    )
    later_crossing_sell = WhaleConsensusFeedEvent(
        source_wallet="0x0000000000000000000000000000000000000ccc",
        market_slug=f"btc-updown-5m-{int(base)}",
        condition_id="cond",
        outcome="Up",
        side="SELL",
        price=0.49,
        size=5.0,
        event_ts=base + 25,
        observed_ts=base + 26,
        token_id="up-token",
        transaction_hash="0x3",
        event_id="sell-1",
    )
    signals, diagnostics = runner.build_quote_signals(
        [signal_event, later_buy, later_crossing_sell],
        prior_quote_ids=set(),
        now_ts=base + 60,
        quote_lookback_s=300.0,
        max_quotes=4,
        order_usd=1.0,
        max_order_usd=8.0,
        max_price=0.50,
        tick_size=0.01,
        quote_latency_s=0.25,
        cancel_before_close_s=30.0,
    )

    assert diagnostics["signals"] == 1
