    assert signals[0]["maker_vs_taker_counterfactual"]["role"] == "equivalent_fak_taker_copy"
    assert runner._crossing_fill(signals[0], [signal_event, later_buy]) is None
    assert runner._crossing_fill(signals[0], [signal_event, later_buy, later_crossing_sell]) is None

    signals, _ = runner.build_quote_signals(
        [signal_event],
        prior_quote_ids=set(),
        now_ts=base + 60,
        quote_lookback_s=300.0,
        max_quotes=4,
        order_usd=1.0,
        max_order_usd=8.0,
        max_price=0.50,
        tick_size=0.01,
        quote_latency_s=0.25,
        cancel_before_close_s=30.0,
    )
    assert signals[0]["quote_price"] == 0.49
    assert runner._crossing_fill(signals[0], [signal_event, later_crossing_sell])["fill_event_id"] == "sell-1"


