def test_e5_top_of_book_falls_back_direct_without_clob_override(monkeypatch):
    import os

    import scripts.run_maker_first_btc5m_paper_lane as runner
    from scripts.run_whale_consensus_paper_lane import WhaleConsensusFeedEvent

    monkeypatch.setenv("POLYMARKET_CLOB_API_BASE_URL", "http://127.0.0.1:8787/clob")
    observed_override_values: list[str | None] = []

    class PrimaryRelayClient:
        timeout_s = 0.25
        retries = 1
        last_route_report = {"status": "HTTP_NON_2XX", "route_class": "DIRECT_ERROR"}

        def get_book(self, token_id: str):
            raise RuntimeError(f"relay busy for {token_id}")

    class FakeDirectCLOBClient:
        DIRECT_CLOB_HOST = "https://clob.polymarket.com"

        def __init__(self, host: str, *, timeout_s: float, fallback_hosts=(), retries: int = 1):
            self.host = host
            self.timeout_s = timeout_s
            self.fallback_hosts = tuple(fallback_hosts)
            self.retries = retries
            self.last_route_report: dict[str, object] = {}

        def get_book(self, token_id: str):
            observed_override_values.append(os.getenv("POLYMARKET_CLOB_API_BASE_URL"))
            self.last_route_report = {"status": "PASS", "clob_host_used": self.host}
            return {
                "asset_id": token_id,
                "asks": [{"price": "0.51", "size": "10"}],
                "bids": [{"price": "0.49", "size": "10"}],
            }

        @staticmethod
        def summarize_book(book: dict, *, copy_size_usd: float, source_price: float, max_slippage_bps: float):
            return {
                "asset_id": book["asset_id"],
                "best_bid": 0.49,
                "best_ask": 0.51,
                "spread": 0.02,
                "instant_fill_status": "BLOCKED",
                "avg_fill_price": 0.0,
                "fillable_usd": 0.0,
                "fill_ratio": 0.0,
                "blocking_reason": "price_above_slippage_cap",
            }

    monkeypatch.setattr(runner, "CLOBMarketClient", FakeDirectCLOBClient)
    event = WhaleConsensusFeedEvent(
        source_wallet="0x0000000000000000000000000000000000000aaa",
        market_slug="btc-updown-5m-1783284000",
        condition_id="cond",
        outcome="Up",
        side="BUY",
        price=0.50,
        size=10.0,
        event_ts=1_783_284_020.0,
        observed_ts=1_783_284_021.0,
        token_id="up-token",
        transaction_hash="0x1",
        event_id="buy-1",
    )

    row = runner._top_of_book_for_signal(
        event,
        fetch_clob_book=True,
        clob=PrimaryRelayClient(),
        order_usd=1.0,
    )

    assert row["status"] == "OK"
    assert row["best_bid"] == 0.49
    assert observed_override_values == [None]
    assert os.getenv("POLYMARKET_CLOB_API_BASE_URL") == "http://127.0.0.1:8787/clob"
    assert row["route_report"]["fallback_source"] == "direct_clob_after_primary_failure"
    assert row["route_report"]["suppressed_env_var"] == "POLYMARKET_CLOB_API_BASE_URL"
    assert row["route_report"]["primary_route_report"]["status"] == "HTTP_NON_2XX"


def test_e5_top_of_book_persists_both_route_failures_without_exception_scope_bug(monkeypatch):
    import scripts.run_maker_first_btc5m_paper_lane as runner
    from scripts.run_whale_consensus_paper_lane import WhaleConsensusFeedEvent

    class FailedClient:
        DIRECT_CLOB_HOST = "https://clob.polymarket.com"

        def __init__(self, host="primary", timeout_s=1.0, fallback_hosts=(), retries=1):
            self.host = host
            self.timeout_s = timeout_s
            self.retries = retries
            self.last_route_report = {"status": "HTTP_NON_2XX", "host": host}

        def get_book(self, token_id: str):
            raise RuntimeError(f"route unavailable: {self.host}")

    monkeypatch.setattr(runner, "CLOBMarketClient", FailedClient)
    event = WhaleConsensusFeedEvent(
        source_wallet="0x0000000000000000000000000000000000000aaa",
        market_slug="btc-updown-5m-1783284000",
        condition_id="cond",
        outcome="Up",
        side="BUY",
        price=0.50,
        size=10.0,
        event_ts=1_783_284_020.0,
        observed_ts=1_783_284_021.0,
        token_id="up-token",
        transaction_hash="0x1",
        event_id="buy-1",
    )

    row = runner._top_of_book_for_signal(
        event,
        fetch_clob_book=True,
        clob=FailedClient(),
        order_usd=1.0,
    )

    assert row["status"] == "ERROR"
    assert row["error_type"] == "RuntimeError"
    assert row["fallback_error_type"] == "RuntimeError"
    assert "clob.polymarket.com" in row["fallback_error"]
    assert row["route_report"]["fallback_status"] == "ERROR"
    assert row["route_report"]["fallback_route_report"]["status"] == "HTTP_NON_2XX"


