def test_leaderboard_fetch_pages_zero_walks_until_empty_or_cap(monkeypatch):
    import src.wallet_copy.leaderboard as leaderboard_mod

    calls: list[tuple[str, int]] = []

    def fake_fetch_leaderboard(**kwargs):
        period = str(kwargs["period"]).upper()
        offset = int(kwargs["offset"])
        limit = int(kwargs["limit"])
        calls.append((period, offset))
        if offset >= 100:
            return []
        return [
            LeaderboardRow(
                period=period,
                rank=offset + index + 1,
                proxy_wallet=f"0x{offset + index + (1 if period == 'WEEK' else 1000):040x}",
                pnl=1000.0 - offset - index,
            )
            for index in range(limit)
        ]

    monkeypatch.setattr(leaderboard_mod, "fetch_leaderboard", fake_fetch_leaderboard)

    rows = fetch_crypto_top_wallets(periods=("WEEK", "MONTH"), limit=50, pages=0, max_pages=3)

    assert len(rows) == 200
    assert calls == [
        ("WEEK", 0),
        ("WEEK", 50),
        ("WEEK", 100),
        ("MONTH", 0),
        ("MONTH", 50),
        ("MONTH", 100),
    ]


def test_leaderboard_fetch_progress_callback_records_pages_and_timeout(monkeypatch):
    import src.wallet_copy.leaderboard as leaderboard_mod

    calls: list[dict[str, object]] = []

    def fake_fetch_leaderboard(**kwargs):
        calls.append(dict(kwargs))
        period = str(kwargs["period"]).upper()
        offset = int(kwargs["offset"])
        limit = int(kwargs["limit"])
        if offset >= limit:
            return []
        return [
            LeaderboardRow(
                period=period,
                rank=index + 1,
                proxy_wallet=f"0x{index + 1:040x}",
                pnl=10.0,
            )
            for index in range(limit)
        ]

    monkeypatch.setattr(leaderboard_mod, "fetch_leaderboard", fake_fetch_leaderboard)
    events: list[dict[str, object]] = []

    rows = fetch_crypto_top_wallets(
        periods=("WEEK",),
        limit=2,
        pages=0,
        max_pages=3,
        timeout_s=7.5,
        retries=2,
        progress_callback=events.append,
    )

    assert len(rows) == 2
    assert [int(call["offset"]) for call in calls] == [0, 2]
    assert {float(call["timeout_s"]) for call in calls} == {7.5}
    assert {int(call["retries"]) for call in calls} == {2}
    assert [event["status"] for event in events] == [
        "PAGE_STARTED",
        "PAGE_FETCHED",
        "PAGE_STARTED",
        "PAGE_FETCHED",
    ]
    assert events[-1]["empty_page"] is True
    assert events[-1]["rows_total_after_page"] == 2


def test_leaderboard_fetch_stops_on_wall_runtime_budget(monkeypatch):
    import src.wallet_copy.leaderboard as leaderboard_mod

    calls: list[int] = []
    clock = {"now": 1000.0}

    def fake_time():
        return clock["now"]

    def fake_fetch_leaderboard(**kwargs):
        offset = int(kwargs["offset"])
        calls.append(offset)
        clock["now"] += 3.0
        return [
            LeaderboardRow(
                period=str(kwargs["period"]).upper(),
                rank=offset + index + 1,
                proxy_wallet=f"0x{offset + index + 1:040x}",
                pnl=10.0,
            )
            for index in range(int(kwargs["limit"]))
        ]

