def test_leaderboard_onboarding_progress_records_terminal_category_skip(tmp_path: Path):
    from scripts.onboard_leaderboard_crypto_wallets import (
        _is_terminal_leaderboard_category_skip,
        _leaderboard_progress_callback,
        _new_leaderboard_scan_progress,
    )

    args = SimpleNamespace(
        leaderboard_pages=0,
        leaderboard_max_pages=20,
        leaderboard_page_timeout_s=8.0,
        leaderboard_max_wall_runtime_s=11.0,
        leaderboard_page_retries=1,
        leaderboard_progress_state=str(tmp_path / "leaderboard_progress.json"),
    )
    progress = _new_leaderboard_scan_progress(args, ["SCIENCE"], [("MONTH", 50)])
    callback = _leaderboard_progress_callback(args, progress)
    response = requests.Response()
    response.status_code = 400
    exc = requests.HTTPError("400 Client Error: Bad Request")
    exc.response = response

    assert _is_terminal_leaderboard_category_skip(exc) is True

    callback(
        {
            "status": "CATEGORY_SKIPPED",
            "category": "SCIENCE",
            "period": "MONTH",
            "http_status": 400,
            "reason": "leaderboard_category_not_supported_by_data_api",
        }
    )

    saved = json.loads(Path(args.leaderboard_progress_state).read_text(encoding="utf-8"))
    assert saved["status"] == "RUNNING"
    assert saved["pages_completed"] == 1
    assert saved["last_category_skip"]["category"] == "SCIENCE"
    assert saved.get("current_page") is None


