def test_leaderboard_state_preserves_previous_candidate_wallets(tmp_path: Path):
    from scripts.onboard_leaderboard_crypto_wallets import (
        _preserve_previous_candidate_wallets,
        _preserve_registry_leaderboard_wallets,
    )

    output = tmp_path / "leaderboard.json"
    registry = tmp_path / "wallets.json"
    upsert_wallet(
        WalletSpec(
            name="registry_leader",
            address="0x0000000000000000000000000000000000000ccc",
            tags=("leaderboard_crypto", "candidate"),
            notes="registry preserved wallet",
        ),
        path=registry,
    )
    output.write_text(
        json.dumps(
            {
                "candidate_wallets": [
                    {
                        "address": "0x0000000000000000000000000000000000000aaa",
                        "name": "old_leader",
                        "tags": ["leaderboard_crypto", "candidate"],
                        "notes": "previous top wallet",
                    },
                    {
                        "address": "0x0000000000000000000000000000000000000bbb",
                        "name": "still_current",
                        "tags": ["leaderboard_crypto", "candidate"],
                    },
                ]
            }
        ),
        encoding="utf-8",
    )
    payload = {
        "summary": {"unique_wallets": 1, "weekly_wallets": 1, "monthly_wallets": 0},
        "top_wallets": [{"address": "0x0000000000000000000000000000000000000bbb"}],
        "candidate_wallets": [
            {
                "address": "0x0000000000000000000000000000000000000bbb",
                "name": "still_current",
                "tags": ["leaderboard_crypto", "candidate"],
            }
        ],
        "leaderboard_rows": [{"proxy_wallet": "0x0000000000000000000000000000000000000bbb"}],
    }

    merged = _preserve_previous_candidate_wallets(payload, output)
    merged = _preserve_registry_leaderboard_wallets(merged, registry)

    assert merged["summary"]["current_unique_wallets"] == 1
    assert merged["summary"]["preserved_historical_wallets"] == 2
    assert merged["summary"]["registry_preserved_historical_wallets"] == 1
    assert merged["summary"]["unique_wallets"] == 3
    assert [row["address"] for row in merged["candidate_wallets"]] == [
        "0x0000000000000000000000000000000000000bbb",
        "0x0000000000000000000000000000000000000aaa",
        "0x0000000000000000000000000000000000000ccc",
    ]
    historical = merged["candidate_wallets"][1]
    assert historical["current_leaderboard_rank_status"] == "not_in_current_fetch"
    assert "leaderboard_historical" in historical["tags"]
    assert "previous top wallet" in historical["notes"]
    registry_historical = merged["candidate_wallets"][2]
    assert registry_historical["preserved_from_registry"] is True
    assert "registry preserved wallet" in registry_historical["notes"]
    assert len(merged["top_wallets"]) == 1
    assert len(merged["leaderboard_rows"]) == 1


def test_leaderboard_onboarding_writes_source_route_blocked_state(tmp_path: Path):
    from scripts.onboard_leaderboard_crypto_wallets import _write_source_route_blocked_state

    output = tmp_path / "leaderboard.json"
    registry = tmp_path / "wallets.json"
    output.write_text(
        json.dumps(
            {
                "candidate_wallets": [
                    {
                        "address": "0x0000000000000000000000000000000000000aaa",
                        "name": "old_leader",
                        "tags": ["leaderboard_crypto", "candidate"],
                    }
                ],
                "summary": {"unique_wallets": 1},
            }
        ),
        encoding="utf-8",
    )
    upsert_wallet(
        WalletSpec(
            name="registry_leader",
            address="0x0000000000000000000000000000000000000bbb",
            tags=("leaderboard_crypto", "candidate"),
            notes="registry preserved wallet",
        ),
        path=registry,
    )

    payload = _write_source_route_blocked_state(
        SimpleNamespace(
            output=str(output),
            registry=str(registry),
            category="CRYPTO",
            order_by="PNL",
            run_pipeline=False,
            max_wallets=0,
            leaderboard_pages=1,
        ),
        PolymarketRouteError(
            "all Polymarket route variants failed",
            route_report={"route_class": "DIRECT_RESET", "status": "TRANSPORT_ERROR"},
        ),
    )

    persisted = json.loads(output.read_text(encoding="utf-8"))
    assert payload["status"] == "SOURCE_ROUTE_BLOCKED"
    assert persisted["status"] == "SOURCE_ROUTE_BLOCKED"
    assert persisted["summary"]["source_route_blocked"] is True
    assert persisted["summary"]["unique_wallets"] == 2
    assert persisted["source_route_blocked"]["route_report"]["route_class"] == "DIRECT_RESET"
    assert [row["address"] for row in persisted["candidate_wallets"]] == [
        "0x0000000000000000000000000000000000000aaa",
        "0x0000000000000000000000000000000000000bbb",
    ]
    assert persisted["paper_only"] is True
    assert persisted["live_orders_allowed"] is False


