def test_operator_wallet_onboarding_resolves_polymarket_handle_url(monkeypatch):
    class FakeResponse:
        def __init__(self, *, text: str = "", payload: dict | None = None):
            self.text = text
            self._payload = payload

        def raise_for_status(self):
            return None

        def json(self):
            if self._payload is None:
                raise ValueError("not json")
            return self._payload

    calls: list[str] = []

    def fake_get(url: str, timeout: float):
        calls.append(url)
        if url == "https://polymarket.com/@gardenercx":
            return FakeResponse(text='{"buildId":"build-unit"}')
        if url.startswith("https://polymarket.com/_next/data/build-unit/profile/%40gardenercx.json"):
            return FakeResponse(
                payload={
                    "pageProps": {
                        "proxyAddress": "0x98f5d88798331947dc2a0f9087308a17c41f754f",
                        "primaryAddress": "0x98f5d88798331947dc2a0f9087308a17c41f754f",
                        "username": "gardenercx",
                        "profileSlug": "@gardenercx",
                    }
                }
            )
        raise AssertionError(url)

    monkeypatch.setattr("src.wallet_copy.onboarding.requests.get", fake_get)

    candidate = parse_or_resolve_wallet_candidate("gardener=https://polymarket.com/@gardenercx")

    assert candidate.name == "gardener"
    assert candidate.normalized_address() == "0x98f5d88798331947dc2a0f9087308a17c41f754f"
    assert "polymarket_profile_handle" in candidate.tags
    assert "https://polymarket.com/@gardenercx" in candidate.notes
    assert calls == [
        "https://polymarket.com/@gardenercx",
        "https://polymarket.com/_next/data/build-unit/profile/%40gardenercx.json?locale=en&slug=%40gardenercx",
    ]


def test_operator_wallet_onboarding_tracker_rc2_is_watch_evidence_not_structural_failure():
    from scripts.onboard_operator_wallets import _classify_status, _command_result, _structural_failures

    tracker_command = {
        "name": "paper_live_tracker",
        "purpose": "measure paper live copy efficiency",
    }
    tracker_result = _command_result(
        tracker_command,
        {"argv": [], "returncode": 2, "stdout_tail": "copy_efficiency FAIL", "stderr_tail": ""},
    )

    assert tracker_result["ok"] is True
    assert tracker_result["accepted_non_green_evidence"] is True
    assert tracker_result["evidence_status"] == "WATCH"
    assert _structural_failures([tracker_result]) == []
    assert _classify_status(plan_only=False, command_results=[tracker_result]) == "WATCH"

    history_failure = _command_result(
        {"name": "history_and_paper", "purpose": "ingest history"},
        {"argv": [], "returncode": 1, "stdout_tail": "", "stderr_tail": "timeout"},
    )
    assert history_failure["ok"] is False
    assert _classify_status(plan_only=False, command_results=[history_failure]) == "BLOCKED"


