def test_leaderboard_pipeline_roster_bounds_history_stage_without_truncating_registry(tmp_path: Path):
    from scripts.onboard_leaderboard_crypto_wallets import _pipeline_commands, _prepare_pipeline_roster

    class Candidate:
        def __init__(self, address: str):
            self.address = address

        def asdict(self):
            return {
                "address": self.address,
                "name": f"wallet_{self.address[-4:]}",
                "tags": ["leaderboard_crypto"],
            }

    args = SimpleNamespace(
        registry="configs/wallet_copy/wallets.json",
        pipeline_max_wallets=2,
        pipeline_roster=str(tmp_path / "leaderboard_pipeline_roster.json"),
        pipeline_artifact_dir=str(tmp_path / "leaderboard_pipeline"),
        limit=20,
        pages=1,
        history_state="history.json",
        paper_state="paper.json",
        wallet_fraction=0.05,
        max_order_usd=2.0,
        inventory_paper_state="inventory.json",
        resolutions="resolutions.jsonl",
        max_unresolved_ratio=0.5,
        research_state="research.json",
        ml_dataset="dataset.jsonl",
        profit_state="profit.json",
        live_tracker_state="tracker.json",
        slippage_bps=250.0,
        max_multi_wallet_base_intents=1000,
        max_wallets_for_search=25,
        max_single_wallet_candidate_intents=500,
        policy_preset="fast",
        no_consensus_search=False,
        no_inventory_search=False,
        no_skip_low_intent_candidates=False,
        skip_live_tracker=False,
        live_tracker_limit=50,
        live_tracker_pages=1,
        data_api_timeout_s=2.0,
        market_ws_jsonl="market_ws.jsonl",
        arm_live_execution=False,
    )
    candidates = [
        Candidate("0x1111111111111111111111111111111111111111"),
        Candidate("0x2222222222222222222222222222222222222222"),
        Candidate("0x3333333333333333333333333333333333333333"),
    ]

    roster = _prepare_pipeline_roster(args, candidates)
    setattr(args, "pipeline_wallets_config", roster["path"])
    history_cmd = _pipeline_commands(args)[0]["argv"]
    commands = {row["name"]: row["argv"] for row in _pipeline_commands(args)}
    roster_payload = json.loads(Path(roster["path"]).read_text(encoding="utf-8"))

    assert roster["status"] == "WRITTEN"
    assert roster["wallets"] == 2
    assert history_cmd[0] == sys.executable
    assert [row["address"] for row in roster_payload["wallets"]] == [
        "0x1111111111111111111111111111111111111111",
        "0x2222222222222222222222222222222222222222",
    ]
    assert history_cmd[history_cmd.index("--wallets-config") + 1] == roster["path"]
    assert history_cmd[history_cmd.index("--data-api-connect-timeout-s") + 1] == "10"
    assert history_cmd[history_cmd.index("--data-api-read-timeout-s") + 1] == "30"
    assert history_cmd[history_cmd.index("--data-api-retries") + 1] == "2"
    assert history_cmd[history_cmd.index("--history-state") + 1] == str(
        tmp_path / "leaderboard_pipeline" / "history_state.json"
    )
    assert history_cmd[history_cmd.index("--paper-state") + 1] == str(
        tmp_path / "leaderboard_pipeline" / "paper_state.json"
    )
    assert commands["profit_admission"][commands["profit_admission"].index("--output") + 1] == str(
        tmp_path / "leaderboard_pipeline" / "profit_engine_state.json"
    )
    for name in ("profit_admission", "profit_admission_after_tracker"):
        command = commands[name]
        assert "--live-today-sprint-operator-approval-id" in command
        assert command[command.index("--live-today-sprint-operator-approval-id") + 1] == "OP-LIVE-20260703-BELA"
    tracker_cmd = commands["paper_live_tracker"]
    assert tracker_cmd[tracker_cmd.index("--registry") + 1] == roster["path"]
    assert tracker_cmd[tracker_cmd.index("--state") + 1] == str(
        tmp_path / "leaderboard_pipeline" / "live_tracking_state.json"
    )
    bounded_argv = [str(value) for argv in commands.values() for value in argv]
    assert not [value for value in bounded_argv if value.startswith("data/research/wallet_copy_")]
    assert args.registry == "configs/wallet_copy/wallets.json"


