def test_profit_search_fast_intent_preserves_copy_intent_identity():
    event = wallet_event(wallet_name="alpha", wallet="0xaaa", condition="0xfastintent", price=0.42, size=10.0)
    policy = CopyPolicy(
        policy_id="unit_fast_intent",
        strategy_family="wallet_copy_profit_search_v1",
        min_price=0.01,
        max_price=1.0,
        sizing=SizingPolicy(policy_id="wallet_fraction_0.1_cap_1", wallet_fraction=0.1, max_order_usd=1.0),
    )

    canonical = event_to_intent(event, policy=policy, mode="paper")
    fast = _profit_search_intent_from_event(event, copy_policy=policy)

    assert canonical is not None
    assert fast is not None
    assert fast.intent_id == canonical.intent_id
    assert fast.source_event_id == canonical.source_event_id
    assert fast.source_row_event_id == event.event_id
    assert canonical.source_row_event_id == ""
    assert fast.token_id == canonical.token_id
    assert fast.policy_id == canonical.policy_id
    assert fast.sizing_policy_id == canonical.sizing_policy_id
    assert fast.copy_size_usd == canonical.copy_size_usd
    assert fast.live_orders_allowed is False


