def test_live_adapter_awaits_trade_executor_and_returns_plain_results(tmp_path: Path):
    class FakeTradeExecutor:
        def __init__(self):
            self.calls = []

        async def execute_trade(self, decision, size_usd):
            self.calls.append((decision, size_usd))
            return {
                "status": "filled",
                "order_id": "fake-live-order",
                "exec_sign_ms": 12.0,
                "exec_post_ms": 34.0,
                "exec_total_ms": 46.0,
                "wallet_copy_post_submit_book": {"fetch_ms": 7.0},
            }

    intent = event_to_intent(wallet_event(price=0.30))
    assert intent is not None
    intent = type(intent).from_dict({**intent.asdict(), "mode": "live", "live_orders_allowed": True})
    executor = FakeTradeExecutor()
    live_state = tmp_path / "live_execution_state.json"
    live_log = tmp_path / "live_execution_events.jsonl"
    admission = LiveAdmissionSnapshot(
        decision_status="PASS",
        live_admission_status="PASS",
        live_orders_allowed=True,
        paper_only=False,
        live_tracker_truth_status="PASS",
        candidate_policy_id=intent.policy_id,
        sizing_policy_id=intent.sizing_policy_id,
        candidate_source_wallet=intent.source_wallet,
        operator_approval_id="unit-test-approval",
    )
    adapter = CopyExecutionAdapter(
        gate=ExecutionGate(
            mode="live",
            explicit_operator_go=True,
            live_orders_allowed=True,
            dry_run=False,
            admission_snapshot=admission,
        ),
        live_lifecycle=LiveWalletCopyLifecycle(
            LiveExecutionLedgerConfig(state_path=str(live_state), event_log_path=str(live_log))
        ),
        trade_executor=executor,
        per_window_fill_cap=1,
    )

    result = asyncio.run(
        adapter.execute_async(
            [intent],
            clob_token_ids_by_condition={intent.condition_id: [intent.token_id, "no-token"]},
        )
    )

    assert result["paper_only"] is False
    assert result["results"][0]["status"] == "filled"
    assert result["results"][0]["order_id"] == "fake-live-order"
    assert result["results"][0]["wallet_copy_latency_budget"]["source"] == "wallet_copy_live_adapter"
    execute_profile = result["results"][0]["wallet_copy_execute_profile"]
    assert execute_profile["execution_role"] == "taker"
    assert execute_profile["prepare_order_s"] >= 0.0
    assert execute_profile["sign_s"] == 0.012
    assert execute_profile["clob_post_s"] == 0.034
    assert execute_profile["fill_poll_s"] == 0.007
    assert execute_profile["fill_poll_reason"] == "post_submit_book_fetch"
    assert execute_profile["submit_executor_total_s"] == 0.046
    assert execute_profile["target_submit_path_p50_s"] == 0.5
    assert result["results"][0]["wallet_copy_execute_live_profile"] == execute_profile
    assert result["execute_live_profile"]["orders_profiled"] == 1
    assert result["execute_live_profile"]["stage_p50_s"]["prepare_order_s"] >= 0.0
    assert result["execute_live_profile"]["stage_p50_s"]["submit_path_total_s"] >= 0.0
    assert result["live_lifecycle_state"] == str(live_state)
    assert result["live_lifecycle_event_log"] == str(live_log)
    assert result["paper_live_parity_capsules"][0]["status"] == "PASS"
    decision, size_usd = executor.calls[0]
    assert decision["strategy_reason"] == "wallet_copy_intent"
    assert size_usd == intent.copy_size_usd
    ledger = json.loads(live_state.read_text(encoding="utf-8"))
    lifecycle_statuses = [row["status"] for row in ledger["lifecycle_events"]]
    assert ledger["summary"]["live_orders"] == 1
    assert ledger["summary"]["filled_orders"] == 1
    latency_budget = ledger["orders"][0]["latency_budget"]
    assert latency_budget["source"] == "wallet_copy_live_adapter"
    assert latency_budget["hops"]["source_fill_block_to_ws_recv_s"] == 2.0
    assert latency_budget["hops"]["submit_sent_to_exchange_ack_s"] is not None
    assert ledger["orders"][0]["trade_result"]["wallet_copy_latency_budget"] == latency_budget
    assert ledger["orders"][0]["trade_result"]["wallet_copy_execute_profile"] == execute_profile
    assert lifecycle_statuses == ["INTENT_RECEIVED", "LIVE_SUBMITTED", "LIVE_FILLED"]
    log_rows = [json.loads(line) for line in live_log.read_text(encoding="utf-8").splitlines()]
    assert log_rows[0]["event"] == "wallet_copy_live_order"
    assert {row["status"] for row in log_rows if row["event"] == "wallet_copy_live_lifecycle"} == {
        "INTENT_RECEIVED",
        "LIVE_SUBMITTED",
        "LIVE_FILLED",
    }


