def test_live_adapter_skips_second_intent_after_filled_btc5m_window(tmp_path: Path):
    class FakeTradeExecutor:
        def __init__(self):
            self.calls = []

        async def execute_trade(self, decision, size_usd):
            self.calls.append((decision, size_usd))
            return {
                "status": "filled",
                "order_id": f"fake-live-order-{len(self.calls)}",
                "exec_sign_ms": 12.0,
                "exec_post_ms": 34.0,
                "exec_total_ms": 46.0,
            }

    first = event_to_intent(wallet_event(wallet_name="alpha", wallet="0xabc", price=0.30))
    second = event_to_intent(wallet_event(wallet_name="beta", wallet="0xabc", price=0.30))
    assert first is not None
    assert second is not None
    first = type(first).from_dict({**first.asdict(), "mode": "live", "live_orders_allowed": True})
    second = type(second).from_dict({**second.asdict(), "mode": "live", "live_orders_allowed": True})
    executor = FakeTradeExecutor()
    live_state = tmp_path / "live_execution_state.json"
    live_log = tmp_path / "live_execution_events.jsonl"
    adapter = CopyExecutionAdapter(
        gate=ExecutionGate(
            mode="live",
            explicit_operator_go=True,
            live_orders_allowed=True,
            dry_run=False,
            admission_snapshot=LiveAdmissionSnapshot(
                decision_status="PASS",
                live_admission_status="PASS",
                live_orders_allowed=True,
                paper_only=False,
                live_tracker_truth_status="PASS",
                candidate_policy_id=first.policy_id,
                sizing_policy_id=first.sizing_policy_id,
                candidate_source_wallet=first.source_wallet,
                operator_approval_id="unit-test-approval",
            ),
        ),
        live_lifecycle=LiveWalletCopyLifecycle(
            LiveExecutionLedgerConfig(state_path=str(live_state), event_log_path=str(live_log))
        ),
        trade_executor=executor,
        per_window_fill_cap=1,
    )

    result = asyncio.run(
        adapter.execute_async(
            [first, second],
            clob_token_ids_by_condition={first.condition_id: [first.token_id, "no-token"]},
        )
    )

    assert len(executor.calls) == 1
    assert result["results"][0]["status"] == "filled"
    assert result["results"][1]["status"] == "SKIPPED"
    assert result["results"][1]["reason"] == "window_fill_cap"
    assert result["execute_live_profile"]["orders_profiled"] == 1
    ledger = json.loads(live_state.read_text(encoding="utf-8"))
    assert [row["final_status"] for row in ledger["orders"]] == ["FILLED", "REJECTED"]
    assert ledger["orders"][1]["trade_result"]["final_status"] == "window_fill_cap"
    assert ledger["orders"][1]["trade_result"]["wallet_copy_window_fill_cap"]["reason"] == "window_fill_cap"
    assert (
        ledger["orders"][1]["trade_result"]["wallet_copy_window_fill_cap"][
            "cap_filled_or_submitted_orders_per_btc_5m_window"
        ]
        == 1
    )
    assert [row["status"] for row in ledger["orders"][1]["lifecycle"]] == ["INTENT_RECEIVED", "LIVE_SKIPPED"]


