def test_live_adapter_posts_same_size_maker_fallback_after_fak_no_match(tmp_path: Path):
    class FakeTradeExecutor:
        def __init__(self):
            self.calls = []

        async def execute_trade(self, decision, size_usd):
            self.calls.append((decision, size_usd))
            if len(self.calls) == 1:
                return {
                    "status": "unfilled",
                    "final_status": "unfilled",
                    "order_id": "fake-fak-no-match",
                    "order_type": "FAK",
                    "error_class": "fak_no_match",
                }
            return {
                "status": "unfilled",
                "final_status": "unfilled",
                "order_id": "fake-maker-fallback",
                "order_type": "GTC",
                "maker": True,
                "error_class": "post_only_rejected",
                "error": "maker fallback rejected by venue",
                "maker_min_share_effective_cap_usd": 2.5,
                "maker_min_share_bump_cost_usd": 2.45,
            }

    future_window = int(time.time()) + 120
    intent = event_to_intent(wallet_event(window_start=future_window, timestamp=future_window + 5, price=0.30, size=10.0))
    assert intent is not None
    live_intent = type(intent).from_dict({**intent.asdict(), "mode": "live", "live_orders_allowed": True})
    executor = FakeTradeExecutor()
    live_state = tmp_path / "live_execution_state.json"
    live_log = tmp_path / "live_execution_events.jsonl"
    admission = LiveAdmissionSnapshot(
        decision_status="PASS",
        live_admission_status="PASS",
        live_orders_allowed=True,
        paper_only=False,
        live_tracker_truth_status="PASS",
        candidate_policy_id=live_intent.policy_id,
        sizing_policy_id=live_intent.sizing_policy_id,
        candidate_source_wallet=live_intent.source_wallet,
        operator_approval_id="unit-test-approval",
    )
    adapter = CopyExecutionAdapter(
        gate=ExecutionGate(
            mode="live",
            explicit_operator_go=True,
            live_orders_allowed=True,
            dry_run=False,
            admission_snapshot=admission,
        ),
        live_lifecycle=LiveWalletCopyLifecycle(
            LiveExecutionLedgerConfig(state_path=str(live_state), event_log_path=str(live_log))
        ),
        trade_executor=executor,
        enable_maker_fallback=True,
    )

    result = asyncio.run(
        adapter.execute_async(
            [live_intent],
            clob_token_ids_by_condition={live_intent.condition_id: [live_intent.token_id, "no-token"]},
        )
    )

    assert [row["order_type"] for row in result["results"]] == ["FAK", "GTC"]
    assert result["execute_live_profile"]["orders_profiled"] == 2
    assert [row["execution_role"] for row in result["execute_live_profile"]["profiles"]] == ["taker", "maker"]
    fallback_decision, fallback_size = executor.calls[1]
    assert fallback_decision["order_type"] == "GTC"
    assert fallback_decision["post_only_strict"] is True
    assert fallback_decision["skip_if_below_min_shares"] is False
    assert fallback_decision["strategy_reason"] == "wallet_copy_fak_miss_maker_fallback"
    assert fallback_size == live_intent.copy_size_usd
    ledger = json.loads(live_state.read_text(encoding="utf-8"))
    assert [row["execution_role"] for row in ledger["orders"]] == ["taker", "maker"]
    assert ledger["orders"][1]["maker_fallback"]["trigger"] == "fak_no_match"
    assert ledger["orders"][1]["final_status"] == "REJECTED"
    assert ledger["orders"][1]["maker_min_share_effective_cap_usd"] == 2.5
    assert ledger["orders"][1]["maker_min_share_bump_cost_usd"] == 2.45
    assert ledger["summary"]["execution_role_counts"] == {"maker": 1, "taker": 1}


def test_live_adapter_records_passive_at_source_closed_without_submit(tmp_path: Path):
    class FakeTradeExecutor:
        def __init__(self):
            self.calls = []
            self.canceled = []

        async def execute_trade(self, decision, size_usd):
            self.calls.append((decision, size_usd))
            return {
                "status": "submitted",
                "final_status": "live",
                "order_id": "passive-at-source-unit",
                "order_type": decision["order_type"],
                "post_only": decision["post_only_strict"],
            }

        async def get_order_status(self, order_id):
            final_status = "canceled" if order_id in self.canceled else "live"
            return {
                "final_status": final_status,
                "size_matched": 0.0,
                "size_original": 5.0,
                "price": 0.30,
            }

        async def cancel_order(self, order_id):
            self.canceled.append(order_id)
            return True

    future_window = int(time.time() // 300) * 300 + 300
    intent = event_to_intent(
        wallet_event(window_start=future_window, timestamp=time.time(), price=0.30, size=5.0)
    )
    assert intent is not None
    metadata = {
        **intent.metadata,
        "copy_model": "inventory",
            "inventory_best_ask_gate": {
                "execution_path": "direct_post_only_gtc_at_source",
                "original_source_price": 0.30,
                "buffered_limit_price": 0.31,
                "max_copy_price": 0.32,
                "best_ask": 0.31,
                "passive_price": 0.30,
            },
        }
    live_intent = type(intent).from_dict(
        {
            **intent.asdict(),
                "mode": "live",
                "live_orders_allowed": True,
                "limit_price": 0.30,
                "copy_size_usd": 1.5,
                "shares": 5.0,
                "metadata": metadata,
            }
        )
    executor = FakeTradeExecutor()
    live_state = tmp_path / "live_execution_state.json"
    live_log = tmp_path / "live_execution_events.jsonl"
    lifecycle = LiveWalletCopyLifecycle(
        LiveExecutionLedgerConfig(state_path=str(live_state), event_log_path=str(live_log))
    )
    admission = LiveAdmissionSnapshot(
        decision_status="PASS",
        live_admission_status="PASS",
        live_orders_allowed=True,
        paper_only=False,
        live_tracker_truth_status="PASS",
        candidate_policy_id=live_intent.policy_id,
        sizing_policy_id=live_intent.sizing_policy_id,
        candidate_source_wallet=live_intent.source_wallet,
        operator_approval_id="unit-test-approval",
    )
    adapter = CopyExecutionAdapter(
        gate=ExecutionGate(
            mode="live",
            explicit_operator_go=True,
            live_orders_allowed=True,
            dry_run=False,
            admission_snapshot=admission,
        ),
        live_lifecycle=lifecycle,
        trade_executor=executor,
        enable_maker_fallback=True,
    )

    result = asyncio.run(
        adapter.execute_async(
            [live_intent],
            clob_token_ids_by_condition={live_intent.condition_id: [live_intent.token_id, "no-token"]},
        )
    )

    assert executor.calls == []
    assert result["results"][0]["execution_role"] == "taker"
    assert result["results"][0]["status"] == "SKIPPED"
    assert result["results"][0]["order_id"] == ""
    assert (
        result["results"][0]["error_class"]
        == "passive_at_source_lane_closed"
    )
    assert (
        result["results"][0]["reason"]
        == "passive_at_source_lane_closed"
    )
    ledger = json.loads(live_state.read_text(encoding="utf-8"))
    order = ledger["orders"][0]
    assert order["final_status"] == "REJECTED"
    assert order["trade_decision"]["order_type"] == "POLICY_TERMINAL"
    assert (
        order["trade_decision"]["strategy_reason"]
        == "passive_at_source_lane_closed"
    )
    assert (
        order["trade_decision"]["wallet_copy_passive_at_source_closed"]["best_ask"]
        == 0.31
    )
    assert "maker_cancel" not in order
    assert ledger["lifecycle_events"][-1]["status"] == "LIVE_SKIPPED"
    assert "wallet_copy_live_order" in live_log.read_text(encoding="utf-8")


