def test_live_lifecycle_cancels_due_maker_fallback_without_fill(tmp_path: Path):
    class FakeTradeExecutor:
        def __init__(self):
            self.canceled = []
            self.status_calls = 0

        async def get_order_status(self, order_id):
            self.status_calls += 1
            if self.status_calls == 1:
                return {"final_status": "live", "size_matched": 0.0, "size_original": 10.0, "price": 0.42}
            return {"final_status": "canceled", "size_matched": 0.0, "size_original": 10.0, "price": 0.42}

        async def cancel_order(self, order_id):
            self.canceled.append(order_id)
            return True

    intent = event_to_intent(wallet_event())
    assert intent is not None
    live_intent = type(intent).from_dict({**intent.asdict(), "mode": "live", "live_orders_allowed": True})
    live_state = tmp_path / "live_execution_state.json"
    live_log = tmp_path / "live_execution_events.jsonl"
    lifecycle = LiveWalletCopyLifecycle(
        LiveExecutionLedgerConfig(state_path=str(live_state), event_log_path=str(live_log))
    )
    lifecycle.record_result(
        intent=live_intent,
        trade_decision={"strategy_reason": "wallet_copy_fak_miss_maker_fallback", "order_type": "GTC"},
        result={
            "status": "submitted",
            "order_id": "maker-due",
            "order_type": "GTC",
            "maker": True,
            "execution_role": "maker",
            "wallet_copy_maker_fallback": {
                "trigger": "fak_no_match",
                "cancel_after_ts": 1.0,
            },
        },
        parity_capsule={"status": "PASS"},
    )

    summary = asyncio.run(lifecycle.cancel_due_maker_fallback_orders(FakeTradeExecutor(), now_ts=2.0))

    assert summary["canceled_orders"] == 1
    ledger = json.loads(live_state.read_text(encoding="utf-8"))
    assert ledger["orders"][0]["final_status"] == "REJECTED"
    assert ledger["orders"][0]["trade_result"]["error_class"] == "maker_fallback_canceled_unfilled"
    assert ledger["orders"][0]["raw_clob_reject_payload"]["error_class"] == "maker_fallback_canceled_unfilled"
    assert ledger["orders"][0]["raw_clob_reject_payload"]["payload"]["status"] == "CANCELED"
    assert ledger["lifecycle_events"][-1]["status"] == "LIVE_MAKER_CANCELED"


def test_live_lifecycle_cancels_e5_gtc_before_window_close(tmp_path: Path):
    class FakeTradeExecutor:
        def __init__(self):
            self.canceled = []

        async def get_order_status(self, order_id):
            return {"final_status": "live", "size_matched": 0.0, "size_original": 2.0, "price": 0.49}

        async def cancel_order(self, order_id):
            self.canceled.append(order_id)
            return True

    window_start = int(time.time() // 300) * 300
    intent = event_to_intent(wallet_event(window_start=window_start, timestamp=window_start + 5, size=1.0))
    assert intent is not None
    live_intent = type(intent).from_dict({**intent.asdict(), "mode": "live", "live_orders_allowed": True})
    live_state = tmp_path / "live_execution_state.json"
    lifecycle = LiveWalletCopyLifecycle(
        LiveExecutionLedgerConfig(
            state_path=str(live_state),
            event_log_path=str(tmp_path / "live_execution_events.jsonl"),
        )
    )
    lifecycle.record_result(
        intent=live_intent,
        trade_decision={
            "strategy_reason": "e5_maker_first_live_guard",
            "execution_lane": "e5_maker_first_btc5m_v1",
            "order_type": "GTC",
            "post_only_strict": True,
        },
        result={
            "status": "submitted",
            "post_status": "live",
            "order_id": "e5-gtc-cancel-unit",
            "order_type": "GTC",
            "maker": True,
            "execution_role": "maker",
        },
        parity_capsule={"status": "PASS"},
    )

    assert lifecycle.due_maker_fallback_orders(now_ts=float(window_start + 269)) == []
    assert len(
        lifecycle.due_maker_fallback_orders(
            now_ts=float(window_start + 5),
            force_e5_demotion=True,
        )
    ) == 1
    assert len(lifecycle.due_maker_fallback_orders(now_ts=float(window_start + 270))) == 1
    summary = asyncio.run(
        lifecycle.cancel_due_maker_fallback_orders(FakeTradeExecutor(), now_ts=float(window_start + 270))
    )

    assert summary["canceled_orders"] == 1
    ledger = json.loads(live_state.read_text(encoding="utf-8"))
    order = ledger["orders"][0]
    assert order["maker_cancel"]["cancel_after_ts"] == float(window_start + 270)
    assert order["final_status"] == "REJECTED"
    assert order["trade_result"]["error_class"] == "e5_maker_canceled_unfilled"


