def test_e5_quote_builder_filters_delayed_offset_and_side_cells():
    import scripts.run_maker_first_btc5m_paper_lane as maker_runner

    event = maker_runner.WhaleConsensusFeedEvent(
        event_id="delayed",
        event_ts=160.0,
        observed_ts=160.0,
        source_wallet="0xabc",
        market_slug="btc-updown-5m-0",
        condition_id="condition",
        token_id="token",
        outcome="Up",
        side="BUY",
        price=0.49,
        size=10.0,
        transaction_hash="0xtx",
    )
    signals, diagnostics = maker_runner.build_quote_signals(
        [event],
        prior_quote_ids=set(),
        now_ts=161.0,
        quote_lookback_s=1800,
        max_quotes=10,
        order_usd=1,
        max_order_usd=8,
        max_price=0.5,
        tick_size=0.01,
        quote_latency_s=0.25,
        cancel_before_close_s=30,
        fixed_shares=5,
        window_offset_min_s=60,
        window_offset_max_s=180,
        outcomes={"Up"},
    )
    assert len(signals) == 1
    assert signals[0]["size_shares"] == 5
    assert diagnostics.get("window_offset_outside_selected_cell", 0) == 0

    rejected, rejected_diagnostics = maker_runner.build_quote_signals(
        [event],
        prior_quote_ids=set(),
        now_ts=161.0,
        quote_lookback_s=1800,
        max_quotes=10,
        order_usd=1,
        max_order_usd=8,
        max_price=0.5,
        tick_size=0.01,
        quote_latency_s=0.25,
        cancel_before_close_s=30,
        fixed_shares=5,
        window_offset_min_s=180,
        window_offset_max_s=270,
        outcomes={"Down"},
    )
    assert rejected == []
    assert rejected_diagnostics["window_offset_outside_selected_cell"] == 1


