class _RecordingWalletCopyExecutor:
    @staticmethod
    def build(
        *,
        max_chase_ticks: int = 0,
        chase_max_price: float = 0.50,
        min_buy_price: float = 0.0,
        max_buy_price: float = 0.0,
    ):
        from src.config import Config
        from src.trade_executor import TradeExecutor

        class RecordingExecutor(TradeExecutor):
            def __init__(self):
                super().__init__(
                    Config(
                        private_key="unit",
                        wallet_copy_max_chase_ticks=max_chase_ticks,
                        wallet_copy_chase_max_price=chase_max_price,
                        wallet_copy_chase_tick_size=0.01,
                        wallet_copy_min_buy_price=min_buy_price,
                        wallet_copy_max_buy_price=max_buy_price,
                    )
                )
                self.mock_mode = False
                self.recorded = {}

            async def _guard_live_buy_capital(self, **kwargs):
                self.recorded["capital_guard"] = kwargs
                return None

            async def _reserve_balance_for_order(self, **kwargs):
                self.recorded["reserve"] = kwargs
                return 1.0

            async def _execute_real_trade(self, *args, **kwargs):
                self.recorded["execute_args"] = args
                self.recorded["execute_kwargs"] = kwargs
                return {"status": "submitted", "order_id": "0xunit"}

            async def _wallet_copy_post_submit_book_snapshot(self, **kwargs):
                self.recorded["snapshot"] = kwargs
                return {"status": "SKIPPED"}

        return RecordingExecutor()


def _wallet_copy_precision_decision(
    *,
    size_usd: float,
    limit_price: float,
    max_order_usd: float,
    effective_live_cap_usd: float | None = None,
    inventory_policy_max_order_usd: float | None = None,
):
    wallet_copy_policy = {
        "max_order_usd": max_order_usd,
        "policy_id": "fast_wf_0.10_cap_4_all_prices_minusd_0_all_window",
    }
    if effective_live_cap_usd is not None:
        wallet_copy_policy["effective_live_cap_usd"] = effective_live_cap_usd
    metadata = {"wallet_copy_policy": wallet_copy_policy}
    if inventory_policy_max_order_usd is not None:
        metadata["inventory_v2"] = {"policy_max_order_usd": inventory_policy_max_order_usd}
    return {
        "action": "buy",
        "side": "NO",
        "limit_price": limit_price,
        "market_id": "0xcond",
        "clob_token_ids": ["yes-token", "no-token"],
        "order_type": "FAK",
        "strategy_reason": "wallet_copy_intent",
        "wallet_copy": {
            "copy_size_usd": size_usd,
            "metadata": metadata,
        },
    }


