def test_trade_executor_applies_bounded_chase_only_below_configured_price():
    from src.config import Config
    from src.trade_executor import TradeExecutor

    class RecordingExecutor(TradeExecutor):
        def __init__(self):
            super().__init__(
                Config(
                    private_key="unit",
                    wallet_copy_max_chase_ticks=1,
                    wallet_copy_chase_max_price=0.70,
                    wallet_copy_chase_tick_size=0.01,
                )
            )
            self.mock_mode = False
            self.recorded = {}

        async def _guard_live_buy_capital(self, **kwargs):
            self.recorded.setdefault("capital_guard", []).append(kwargs)
            return None

        async def _reserve_balance_for_order(self, **kwargs):
            self.recorded.setdefault("reserve", []).append(kwargs)
            return 1.0

        async def _execute_real_trade(self, *args, **kwargs):
            self.recorded.setdefault("execute_args", []).append(args)
            self.recorded.setdefault("execute_kwargs", []).append(kwargs)
            return {"status": "submitted", "order_id": "0xunit"}

        async def _wallet_copy_post_submit_book_snapshot(self, **kwargs):
            self.recorded.setdefault("snapshot", []).append(kwargs)
            return {"status": "SKIPPED"}

    executor = RecordingExecutor()
    low_price_result = asyncio.run(
        executor.execute_trade(
            {
                "action": "buy",
                "side": "YES",
                "limit_price": 0.69,
                "market_id": "0xcond",
                "clob_token_ids": ["yes-token", "no-token"],
                "order_type": "FAK",
                "strategy_reason": "wallet_copy_intent",
            },
            size_usd=2.0,
        )
    )
    high_price_result = asyncio.run(
        executor.execute_trade(
            {
                "action": "buy",
                "side": "YES",
                "limit_price": 0.85,
                "market_id": "0xcond",
                "clob_token_ids": ["yes-token", "no-token"],
                "order_type": "FAK",
                "strategy_reason": "wallet_copy_intent",
            },
            size_usd=2.0,
        )
    )

    assert executor.recorded["execute_args"][0][3] == 0.70
    assert "snapshot" not in executor.recorded
    assert "wallet_copy_post_submit_book" not in low_price_result
    assert low_price_result["wallet_copy_chase"]["chase_enabled"] is True
    assert low_price_result["wallet_copy_chase"]["effective_limit_price"] == 0.70
    assert executor.recorded["execute_args"][1][3] == 0.85
    assert high_price_result["wallet_copy_chase"]["chase_enabled"] is False
    assert high_price_result["wallet_copy_chase"]["chase_ticks_applied"] == 0


