def test_trade_executor_rounds_market_buy_up_to_min_order_within_overshoot():
    from src.config import Config
    from src.trade_executor import TradeExecutor

    class RecordingExecutor(TradeExecutor):
        def __init__(self):
            super().__init__(Config(private_key="unit"))
            self.mock_mode = False
            self.recorded = {}

        async def _guard_live_buy_capital(self, **kwargs):
            self.recorded["capital_guard"] = kwargs
            return None

        async def _reserve_balance_for_order(self, **kwargs):
            self.recorded["reserve"] = kwargs
            return 1.29

        async def _execute_real_trade(self, *args, **kwargs):
            self.recorded["execute_kwargs"] = kwargs
            return {"status": "submitted", "order_id": "0xunit"}

        async def _wallet_copy_post_submit_book_snapshot(self, **kwargs):
            return {"status": "SKIPPED"}

    executor = RecordingExecutor()
    result = asyncio.run(
        executor.execute_trade(
            {
                "action": "buy",
                "side": "YES",
                "limit_price": 0.43,
                "market_id": "0xcond",
                "clob_token_ids": ["yes-token", "no-token"],
                "order_type": "FAK",
            },
            size_usd=1.075,
        )
    )

    # Precision-valid amounts at 0.43 are multiples of $0.43; $1.075 rounds
    # down to $0.99 (below CLOB min) so it must round UP to $1.29 (3.0 shares)
    # instead of skipping.
    assert result["status"] == "submitted"
    assert executor.recorded["execute_kwargs"]["market_order_amount"] == 1.29
    assert executor.recorded["capital_guard"]["effective_order_usd"] == 1.29


