def test_fill_quality_report_classifies_reject_causes():
    from scripts.report_fill_quality import build_fill_quality_report

    ledger = {
        "orders": [
            {
                "final_status": "REJECTED",
                "side": "YES",
                "limit_price": 0.90,
                "requested_size_usd": 1.8,
                "trade_result": {
                    "error_class": "fak_no_match",
                    "wallet_copy_post_submit_book": {
                        "status": "OK",
                        "best_ask": 0.94,
                        "ask_depth_at_or_below_limit_usd": 0.0,
                    },
                },
            },
            {
                "final_status": "REJECTED",
                "side": "NO",
                "limit_price": 0.82,
                "requested_size_usd": 2.0,
                "trade_result": {
                    "error_class": "fak_no_match",
                    "wallet_copy_post_submit_book": {
                        "status": "OK",
                        "best_ask": 0.82,
                        "ask_depth_at_or_below_limit_usd": 0.75,
                    },
                },
            },
            {
                "final_status": "REJECTED",
                "side": "YES",
                "limit_price": 0.49,
                "requested_size_usd": 1.03,
                "trade_result": {
                    "error_class": "market_buy_precision_below_min_order",
                    "error": "precision-safe market BUY amount would be below CLOB min order: $0.98",
                },
            },
        ]
    }

    report = build_fill_quality_report(ledger, {})

    assert report["reject_classification"]["taxonomy_counts"] == {
        "best_ask_above_copied_limit": 1,
        "insufficient_depth_at_copied_limit": 1,
        "market_buy_precision_below_min_order": 1,
    }
    assert report["reject_classification"]["group_counts"] == {
        "genuine_slippage_or_liquidity": 2,
        "sizing_or_precision": 1,
    }
    high_price = report["reject_classification"]["high_price_85_100"]
    assert high_price["rejects"] == 1
    assert high_price["measured_skip_candidate"] is True
    assert high_price["sampled_rejects"][0]["category"] == "best_ask_above_copied_limit"


def test_live_lifecycle_runtime_permission_can_block_archived_live_ledger(tmp_path: Path):
    intent = event_to_intent(wallet_event())
    assert intent is not None
    live_intent = type(intent).from_dict({**intent.asdict(), "mode": "live", "live_orders_allowed": True})
    live_state = tmp_path / "live_execution_state.json"
    live_log = tmp_path / "live_execution_events.jsonl"
    lifecycle = LiveWalletCopyLifecycle(
        LiveExecutionLedgerConfig(state_path=str(live_state), event_log_path=str(live_log))
    )

    lifecycle.record_result(
        intent=live_intent,
        trade_decision={"strategy_reason": "wallet_copy_intent"},
        result={"status": "filled", "order_id": "0xmatched"},
        parity_capsule={"status": "PASS"},
    )

    blocked = lifecycle.set_runtime_permission(
        paper_only=True,
        live_orders_allowed=False,
        can_trade=False,
        status="LIVE_GUARD_BLOCKED",
        blockers=["profit_engine_no_live_admissible_pass_candidate"],
        owner="unit-test-guard",
    )

    assert blocked["paper_only"] is True
    assert blocked["live_orders_allowed"] is False
    assert blocked["can_trade"] is False
    assert blocked["runtime_permission"]["status"] == "LIVE_GUARD_BLOCKED"
    assert blocked["summary"]["live_orders"] == 1
    assert blocked["summary"]["live_orders_allowed"] is False
    assert blocked["orders"][0]["live_orders_allowed"] is True


def test_live_guard_runtime_permission_sync_skips_no_change_flap(tmp_path: Path):
    import scripts.run_wallet_copy_live_guard as guard

    live_state = tmp_path / "live_execution_state.json"
    live_log = tmp_path / "live_execution_events.jsonl"
    atomic_write_json(
        live_state,
        {
            "kind": "wallet_copy_live_execution_state",
            "paper_only": False,
            "live_orders_allowed": True,
            "can_trade": True,
            "orders": [],
            "lifecycle_events": [],
            "runtime_permission": {
                "status": "LIVE_GUARD_RUNNING",
                "paper_only": False,
                "live_orders_allowed": True,
                "can_trade": True,
                "blockers": [],
                "owner": "wallet_copy_live_guard",
                "updated_at": "2026-07-07T15:30:01Z",
            },
        },
    )
    args = SimpleNamespace(
        live_ledger_state=str(live_state),
        live_ledger_event_log=str(live_log),
        state=str(tmp_path / "guard_state.json"),
    )
    running_payload = {
        "status": "LIVE_GUARD_RUNNING",
        "live_orders_allowed": True,
        "blockers": [],
        "cycle": 23,
    }

    guard._sync_live_ledger_runtime_permission(args, running_payload)
    unchanged = load_json(live_state, default={})
    assert unchanged["runtime_permission"]["updated_at"] == "2026-07-07T15:30:01Z"

    blocked_payload = {
        "status": "LIVE_GUARD_BLOCKED",
        "live_orders_allowed": False,
        "blockers": ["live_guard_candidate_not_pass"],
        "cycle": 24,
    }
    guard._sync_live_ledger_runtime_permission(args, blocked_payload)
    changed = load_json(live_state, default={})
    assert changed["runtime_permission"]["status"] == "LIVE_GUARD_BLOCKED"
    assert changed["runtime_permission"]["can_trade"] is False
    assert changed["runtime_permission"]["blockers"] == ["live_guard_candidate_not_pass"]
    assert changed["runtime_permission"]["updated_at"] != "2026-07-07T15:30:01Z"


def test_live_guard_recent_cycle_counts_include_current_cycle(tmp_path: Path):
    import scripts.run_wallet_copy_live_guard as guard

    event_log = tmp_path / "guard_events.jsonl"
    rows = [
        {
            "event": "wallet_copy_live_guard_cycle",
            "status": "LIVE_GUARD_BLOCKED",
            "cycle_outcome": "LIVE_GUARD_BLOCKED",
            "live_execution": {"orders_submitted": 0},
        },
        {
            "event": "wallet_copy_live_guard_cycle",
            "status": "LIVE_GUARD_RUNNING",
            "cycle_outcome": "LIVE_GUARD_RUNNING",
            "live_execution": {"orders_submitted": 1},
        },
    ]
    event_log.write_text("\n".join(json.dumps(row) for row in rows) + "\n", encoding="utf-8")
    current = {
        "status": "LIVE_GUARD_RUNNING",
        "cycle_outcome": "FILTERED_NO_SUBMIT",
        "live_execution": {"orders_submitted": 0},
    }

    counts = guard._recent_cycle_counts(SimpleNamespace(event_log=str(event_log)), current_payload=current)

    assert counts["cycles_observed"] == 3
    assert counts["blocked_cycles"] == 1
    assert counts["submitted_cycles"] == 1
    assert counts["running_cycles"] == 2
    assert counts["filtered_no_submit_cycles"] == 1


