def test_live_execution_prefilter_keeps_only_fresh_policy_accepted_events():
    from scripts.run_wallet_copy_live_execution import _live_candidate_build_events

    now = 1_700_000_120.0
    window_start = int(now // 300.0) * 300
    fresh = WalletEvent(
        source_wallet="0xaaa",
        wallet_name="unit",
        row_type="trade",
        action="BUY",
        condition_id="0xcond",
        market_slug=f"btc-updown-5m-{window_start}",
        outcome="Up",
        price=0.42,
        size=50.0,
        usdc_size=21.0,
        event_ts=now - 5.0,
        observed_ts=now - 1.0,
        token_id="token-up",
        transaction_hash="0xfresh",
        api_latency_s=1.0,
    )
    stale = WalletEvent.from_dict(
        {
            **fresh.asdict(),
            "event_id": "",
            "event_ts": now - 90.0,
            "observed_ts": now - 89.0,
            "transaction_hash": "0xstale",
        }
    )
    policy_rejected = WalletEvent.from_dict(
        {
            **fresh.asdict(),
            "event_id": "",
            "price": 0.90,
            "usdc_size": 45.0,
            "transaction_hash": "0xpolicy",
        }
    )

    retained, summary = _live_candidate_build_events(
        [stale, fresh, policy_rejected],
        CandidatePolicy(policy_id="unit", max_price=0.50),
        now_ts=now,
        max_event_age_s=30.0,
    )

    assert [event.transaction_hash for event in retained] == ["0xfresh"]
    assert summary["input_events"] == 3
    assert summary["retained_events"] == 1
    assert summary["skip_counts"] == {"stale_build_observed_age": 1}
    assert summary["policy_reject_counts"] == {"price_outside_policy": 1}
    assert [sample["skip_reason"] for sample in summary["sample_filtered_events"]] == [
        "policy_price_outside_policy",
        "stale_build_observed_age",
    ]


