def test_live_execution_inventory_model_drops_stale_or_late_window_state(monkeypatch, tmp_path: Path):
    import scripts.run_wallet_copy_live_execution as live_execution

    now = 1_700_000_120.0
    window_start = 1_700_000_000
    monkeypatch.setattr(live_execution.time, "time", lambda: now)
    stale = WalletEvent.from_dict(
        {
            **wallet_event(price=0.40, size=40.0, window_start=window_start, timestamp=int(now - 2)).asdict(),
            "observed_ts": now - 6.0,
            "transaction_hash": "0xstale-window",
            "event_id": "",
        }
    )
    late = WalletEvent.from_dict(
        {
            **wallet_event(
                wallet="0xdef",
                price=0.40,
                size=40.0,
                window_start=window_start,
                timestamp=window_start + 248,
            ).asdict(),
            "observed_ts": window_start + 249.0,
            "transaction_hash": "0xlate-window",
            "event_id": "",
        }
    )
    ledger_state = tmp_path / "ledger.json"
    ledger_state.write_text(json.dumps({"orders": []}))
    policy = CandidatePolicy(policy_id="unit", wallet_fraction=0.10, max_order_usd=2.0, min_order_usd=1.0)

    stale_intents, stale_summary = live_execution._build_inventory_v2_intents(
        [stale],
        policy,
        now_ts=now,
        max_event_age_s=30.0,
        live_build_max_observed_age_s=3.0,
        live_ledger_state=str(ledger_state),
        late_window_stop_s=60.0,
        max_converge_orders_per_window=6,
    )
    late_intents, late_summary = live_execution._build_inventory_v2_intents(
        [late],
        policy,
        now_ts=window_start + 250.0,
        max_event_age_s=30.0,
        live_build_max_observed_age_s=3.0,
        live_ledger_state=str(ledger_state),
        late_window_stop_s=60.0,
        max_converge_orders_per_window=6,
    )

    assert stale_intents == []
    assert stale_summary["skip_counts"] == {"inventory_window_state_stale": 1}
    stale_row = stale_summary["inventory_window_participation"][0]
    stale_audit = stale_row["stale_drop_audit"]
    assert stale_audit["stale_drop_events"] == 1
    assert stale_audit["sample_events"][0]["source_tx_hash"] == "0xstale-window"
    assert stale_audit["sample_events"][0]["event_ts"] == now - 2
    assert stale_audit["sample_events"][0]["observed_ts"] == now - 6.0
    assert stale_audit["sample_events"][0]["drop_age_s"] == 6.0
    assert stale_audit["events_by_source_tx"]["0xstale-window"]["event_ts"] == now - 2
    assert stale_audit["events_by_source_tx"]["0xstale-window"]["observed_ts"] == now - 6.0
    assert stale_audit["events_by_source_tx"]["0xstale-window"]["drop_age_s"] == 6.0
    assert late_intents == []
    assert late_summary["skip_counts"] == {"inventory_late_window_guard": 1}


def test_live_execution_inventory_model_uses_fresh_rtds_watermark_for_quiet_wallet(monkeypatch, tmp_path: Path):
    import scripts.run_wallet_copy_live_execution as live_execution

    now = 1_700_000_120.0
    window_start = 1_700_000_000
    monkeypatch.setattr(live_execution.time, "time", lambda: now)
    wallet = "0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
    stale_but_confirmed = WalletEvent.from_dict(
        {
            **wallet_event(wallet=wallet, price=0.40, size=40.0, window_start=window_start, timestamp=int(now - 60)).asdict(),
            "observed_ts": now - 60.0,
            "transaction_hash": "0xstale-confirmed",
            "event_id": "",
        }
    )
    ledger_state = tmp_path / "ledger.json"
    ledger_state.write_text(json.dumps({"orders": []}))
    watermark_state = tmp_path / "watermarks.json"
    watermark_state.write_text(
        json.dumps(
            {
                "kind": "wallet_copy_rtds_observation_watermarks",
                "wallets": {
                    wallet: {
                        "source_wallet": wallet,
                        "latest_checked_ts": now - 1.0,
                        "latest_matching_observed_ts": now - 60.0,
                        "history_write_skipped_safe": True,
                        "paper_only": True,
                        "live_orders_allowed": False,
                    }
                },
            }
        )
    )
    policy = CandidatePolicy(policy_id="unit", wallet_fraction=0.10, max_order_usd=2.0, min_order_usd=1.0)

    watermarks = live_execution._load_observation_watermarks(str(watermark_state), source_wallet=wallet)
    intents, summary = live_execution._build_inventory_v2_intents(
        [stale_but_confirmed],
        policy,
        now_ts=now,
        max_event_age_s=30.0,
        live_build_max_observed_age_s=3.0,
        live_ledger_state=str(ledger_state),
        late_window_stop_s=60.0,
        max_converge_orders_per_window=6,
        observation_watermarks=watermarks,
    )

    assert len(intents) == 1
    fresh = live_execution._fresh_intents(
        intents,
        max_event_age_s=30.0,
        max_intents=6,
        live_build_max_observed_age_s=3.0,
    )
    assert fresh == intents
    diagnostics = live_execution._intent_runtime_diagnostics(
        intents[0],
        now_ts=now,
        max_event_age_s=30.0,
        live_build_max_observed_age_s=3.0,
    )
    assert diagnostics["fresh_by_rtds_watermark"] is True
    assert diagnostics["freshness_basis"] == "rtds_watermark_confirmed_unchanged"
    assert summary["skip_counts"] == {}
    participation = summary["inventory_window_participation"][0]
    assert participation["dominant_skip_reason"] == "eligible"
    assert participation["freshness_confirmed_unchanged"] is True
    assert participation["freshness_watermark_ts"] == now - 1.0
    assert participation["source_latest_observed_age_s"] == 60.0
    assert diagnostics["fresh_for_live_build_by_observed_ts"] is False
    assert diagnostics["fresh_for_live_build_by_watermark"] is True
    assert intents[0].observed_ts == now - 60.0


