def test_live_execution_inventory_best_ask_gate_accepts_vwap_plus_buffer(monkeypatch):
    import scripts.run_wallet_copy_live_execution as live_execution

    live_execution._INVENTORY_BEST_ASK_BOOK_CACHE.clear()
    intent = CopyIntent(
        source_wallet="0xaaa",
        wallet_name="alpha",
        source_event_id="inv",
        condition_id="0xcond",
        market_slug="btc-updown-5m-1700000000",
        outcome="Up",
        side="YES",
        limit_price=0.45,
        wallet_usdc_size=10.0,
        copy_size_usd=1.0,
        shares=2.222222,
        observed_ts=1_700_000_002.0,
        token_id="token-up",
        metadata={"copy_model": "inventory", "inventory_v2": {"source_inventory_vwap": 0.44}},
    )

    init_kwargs = {}

    def fake_init(self, *args, **kwargs):
        init_kwargs.update(kwargs)

    monkeypatch.setattr(live_execution.CLOBMarketClient, "__init__", fake_init)
    monkeypatch.setattr(
        live_execution,
        "_direct_clob_book",
        lambda token_id, timeout_s: {"asks": [{"price": "0.45", "size": "100"}], "bids": []},
    )

    accepted, summary = live_execution._apply_inventory_best_ask_gate(
        [intent], timeout_s=0.1, generation_sha256="generation-d20"
    )

    assert len(accepted) == 1
    assert summary["status"] == "PASS"
    assert init_kwargs["retries"] == 1
    assert accepted[0].metadata["inventory_best_ask_gate"]["best_ask"] == 0.45
    assert accepted[0].metadata["inventory_best_ask_gate"]["book_route_winner"] == "direct_clob"
    assert summary["sample_decisions"][0]["direct_clob_fallback_attempted"] is True
    assert summary["sample_decisions"][0]["direct_clob_fallback_passed"] is True


