def test_live_lifecycle_labels_ruled_floor_breach_with_submit_best_ask(tmp_path: Path):
    intent = _ruled_floor_inventory_intent()
    payload = intent.asdict()
    payload["mode"] = "live"
    payload["live_orders_allowed"] = True
    payload["metadata"] = {
        **payload["metadata"],
        "inventory_best_ask_gate": {
            "gate_probe_best_ask": 0.26,
            "best_ask_observed_at_s": 1_700_000_003.0,
            "gate_evaluated_at_s": 1_700_000_003.25,
            "gate_probe_best_ask_age_at_gate_s": 0.25,
            "max_gate_probe_best_ask_age_at_gate_s": 1.0,
            "event_age_s": 1.5,
            "generation_sha256": "generation-d20",
        },
    }
    live_intent = CopyIntent.from_dict(payload)
    lifecycle = LiveWalletCopyLifecycle(
        LiveExecutionLedgerConfig(
            state_path=str(tmp_path / "state.json"),
            event_log_path=str(tmp_path / "events.jsonl"),
        )
    )

    order = lifecycle.record_result(
        intent=live_intent,
        trade_decision={"strategy_reason": "wallet_copy_intent"},
        result={
            "status": "filled",
            "order_id": "floor-breach",
            "response_filled_size_usd": 1.04,
            "response_fill_size_shares": 4.333333,
        },
        parity_capsule={"status": "PASS"},
        latency_budget={"submit_sent_ts": 1_700_000_003.5},
    )

    assert order["trade_result"]["gate_probe_best_ask"] == 0.26
    assert order["trade_result"]["submit_best_ask_evidence"][
        "book_age_at_submit_sent_s"
    ] == 0.5
    assert order["trade_result"]["submit_best_ask_evidence"][
        "gate_to_submit_sent_s"
    ] == 0.25
    evidence = order["trade_result"]["submit_best_ask_evidence"]
    assert evidence["gate_probe_best_ask_age_at_gate_s"] == 0.25
    assert evidence["event_age_s"] == 1.5
    assert evidence["generation_sha256"] == "generation-d20"
    assert evidence["realized_minus_limit_price"] == pytest.approx(-0.06, abs=1e-6)
    assert evidence["realized_minus_gate_probe_best_ask"] == pytest.approx(
        -0.02, abs=1e-6
    )
    assert order["trade_result"]["inventory_best_ask_gate"][
        "generation_sha256"
    ] == "generation-d20"
    assert order["trade_result"]["realized_entry_classification"] == "RULED_FLOOR_BREACH"
    assert order["trade_result"]["ruled_floor_breach"] is True
    assert order["lifecycle"][-1]["payload"]["realized_entry_classification"] == "RULED_FLOOR_BREACH"


