def test_live_execution_inventory_best_ask_gate_fetches_books_concurrently(monkeypatch):
    import threading

    import scripts.run_wallet_copy_live_execution as live_execution

    live_execution._INVENTORY_BEST_ASK_BOOK_CACHE.clear()
    active = 0
    max_active = 0
    lock = threading.Lock()

    def fake_direct_book(token_id, timeout_s):
        nonlocal active, max_active
        with lock:
            active += 1
            max_active = max(max_active, active)
        time.sleep(0.05)
        with lock:
            active -= 1
        return {"asks": [{"price": "0.30", "size": "100"}], "bids": []}

    monkeypatch.setattr(live_execution, "_direct_clob_book", fake_direct_book)
    intents = [
        CopyIntent(
            source_wallet="0xaaa",
            wallet_name="alpha",
            source_event_id=f"inv-{idx}",
            condition_id=f"0xcond{idx}",
            market_slug=f"btc-updown-5m-{1_700_000_000 + idx * 300}",
            outcome="Up",
            side="YES",
            limit_price=0.31,
            wallet_usdc_size=10.0,
            copy_size_usd=1.0,
            shares=3.225806,
            observed_ts=1_700_000_002.0,
            token_id=f"token-up-{idx}",
            metadata={"copy_model": "inventory", "inventory_v2": {"source_inventory_vwap": 0.30}},
        )
        for idx in range(4)
    ]

    accepted, summary = live_execution._apply_inventory_best_ask_gate(intents, timeout_s=0.1)

    assert len(accepted) == 4
    assert summary["status"] == "PASS"
    assert summary["runtime_profile"]["clob_book_fetch_concurrency"] == 4
    assert max_active > 1


