def test_guard_selects_orderfilled_sidecar_only_after_exact_paper_gate(tmp_path: Path):
    import argparse
    import scripts.run_wallet_copy_live_guard as guard

    mixed = tmp_path / "mixed.jsonl"
    sidecar = tmp_path / "sidecar.jsonl"
    gate = tmp_path / "gate.json"
    mixed.touch()
    sidecar.touch()
    args = argparse.Namespace(
        polygon_ws_premerge_jsonl=str(mixed),
        active_member_orderfilled_direct_cursor_state=str(tmp_path / "mixed-cursor.json"),
        orderfilled_sidecar_jsonl=str(sidecar),
        orderfilled_sidecar_live_cursor_state=str(tmp_path / "sidecar-cursor.json"),
        orderfilled_sidecar_gate_state=str(gate),
    )
    gate.write_text(
        json.dumps(
            {
                "paper_only": True,
                "live_source_wiring_gate_passed": True,
                "unique_exact_payload_matched_identities": 100,
                "required_identities": 100,
                "overdue_sidecar_only_payloads": 0,
                "overdue_mixed_only_payloads": 0,
                "p95_sidecar_lead_vs_mixed_guard_s": 5.01,
                "required_p95_lead_s": 5.0,
                "max_rss_gib": 0.05,
                "max_rss_gate_gib": 1.0,
            }
        ),
        encoding="utf-8",
    )
    selection = guard._orderfilled_live_source_selection(args)
    assert selection["gate_passed"] is True
    assert selection["source_jsonl"] == str(sidecar)
    assert selection["cursor_state"].endswith("sidecar-cursor.json")

    payload = json.loads(gate.read_text(encoding="utf-8"))
    payload["overdue_sidecar_only_payloads"] = 1
    gate.write_text(json.dumps(payload), encoding="utf-8")
    selection = guard._orderfilled_live_source_selection(args)
    assert selection["gate_passed"] is False
    assert selection["source_jsonl"] == str(mixed)
    assert selection["cursor_state"].endswith("mixed-cursor.json")

    payload["gate_passed_once"] = True
    gate.write_text(json.dumps(payload), encoding="utf-8")
    selection = guard._orderfilled_live_source_selection(args)
    assert selection["gate_passed"] is True
    assert selection["source_jsonl"] == str(sidecar)


def test_main_cycle_delegates_orderfilled_cursor_to_fast_lane(monkeypatch) -> None:
    import scripts.run_wallet_copy_live_guard as guard

    selection = {
        "gate_passed": True,
        "source_jsonl": "sidecar.jsonl",
        "cursor_state": "cursor.json",
    }
    monkeypatch.setattr(guard, "_orderfilled_live_source_selection", lambda _args: selection)
    monkeypatch.setattr(
        guard,
        "_initialize_orderfilled_sidecar_cursor",
        lambda **_kwargs: pytest.fail("main cycle must not initialize the fast-lane cursor"),
    )
    monkeypatch.setattr(
        guard,
        "_active_member_orderfilled_direct_delta",
        lambda **_kwargs: pytest.fail("main cycle must not read or advance the fast-lane cursor"),
    )

    rows, report, handoff, selected = guard._main_cycle_orderfilled_delta(
        SimpleNamespace(),
        active_set_runtime={"members": []},
        fast_lane_enabled=True,
    )

    assert rows == []
    assert report["status"] == "DELEGATED_TO_FAST_LANE"
    assert report["cursor_owner"] == "orderfilled_fast_lane_tick"
    assert report["cursor_owner_count"] == 1
    assert handoff == {"status": "DELEGATED_TO_FAST_LANE"}
    assert selected is selection


def test_main_cycle_orderfilled_reader_remains_disabled_fast_lane_fallback(monkeypatch) -> None:
    import scripts.run_wallet_copy_live_guard as guard

    selection = {
        "gate_passed": True,
        "source_jsonl": "sidecar.jsonl",
        "cursor_state": "cursor.json",
    }
    calls = []
    read_kwargs = []
    monkeypatch.setattr(guard, "_orderfilled_live_source_selection", lambda _args: selection)
    monkeypatch.setattr(
        guard,
        "_initialize_orderfilled_sidecar_cursor",
        lambda **_kwargs: calls.append("initialize") or {"status": "INITIALIZED"},
    )
    monkeypatch.setattr(
        guard,
        "_active_member_orderfilled_direct_delta",
        lambda **kwargs: (
            read_kwargs.append(kwargs) or calls.append("read") or [],
            {"status": "PASS_NO_CURRENT_EVENT"},
        ),
    )
    args = SimpleNamespace(
        active_member_orderfilled_direct_cursor_state="old-cursor.json",
        polygon_ws_premerge_tail_bytes=1024,
        active_member_orderfilled_hot_source_state="gate.json",
        active_member_orderfilled_accumulator_state="accumulator.json",
        active_member_orderfilled_direct_bootstrap_bytes=512,
        copy_source_identity_router_state="configured-router.json",
    )

    rows, report, handoff, _selected = guard._main_cycle_orderfilled_delta(
        args,
        active_set_runtime={"members": []},
        fast_lane_enabled=False,
    )

    assert rows == []
    assert calls == ["initialize", "read"]
    assert read_kwargs[0]["source_identity_router_state_path"] == "configured-router.json"
    assert handoff["status"] == "INITIALIZED"
    assert report["cursor_owner"] == "main_cycle_fallback"
    assert report["cursor_owner_count"] == 1


