def test_fast_lane_latency_resets_only_on_runtime_generation_change(tmp_path: Path) -> None:
    import scripts.run_wallet_copy_live_guard as guard

    lane = guard._OrderFilledFastLane(
        SimpleNamespace(
            orderfilled_fast_lane=False,
            orderfilled_fast_lane_state=str(tmp_path / "state.json"),
            orderfilled_fast_lane_wake_socket=str(tmp_path / "wake.sock"),
        )
    )
    lane._set_latency_generation("generation-a")
    lane._latencies.extend([0.1, 0.2])
    lane._set_latency_generation("generation-a")
