def test_guard_initializes_sidecar_cursor_before_matched_boundary(tmp_path: Path):
    import scripts.run_wallet_copy_live_guard as guard

    sidecar = tmp_path / "sidecar.jsonl"
    old_cursor = tmp_path / "mixed-cursor.json"
    new_cursor = tmp_path / "sidecar-cursor.json"
    rows = [
        {"event": "polygon_orderfilled_log", "transaction_hash": "0xaaa", "log_index": 1},
        {"event": "polygon_orderfilled_log", "transaction_hash": "0xbbb", "log_index": 2},
        {"event": "polygon_orderfilled_log", "transaction_hash": "0xccc", "log_index": 3},
    ]
    offsets = []
    with sidecar.open("wb") as handle:
        for row in rows:
            offsets.append(handle.tell())
            handle.write((json.dumps(row) + "\n").encode())
    old_cursor.write_text(
        json.dumps(
            {
                "next_byte_offset": 123,
                "seen_identities": ["0xaaa|1", "0xbbb|2"],
            }
        ),
        encoding="utf-8",
    )
    report = guard._initialize_orderfilled_sidecar_cursor(
        source_jsonl=sidecar,
        old_cursor_state=old_cursor,
        new_cursor_state=new_cursor,
        bootstrap_bytes=64,
    )
    cursor = json.loads(new_cursor.read_text(encoding="utf-8"))
    assert report["status"] == "INITIALIZED_MATCHED_OVERLAP"
    assert cursor["next_byte_offset"] == offsets[0]
    assert cursor["seen_identities"] == ["0xaaa|1", "0xbbb|2"]
    assert cursor["handoff"]["replay_before_boundary"] is True


def test_live_execution_rtds_duplicate_detection_timestamp_survives_gate():
    import scripts.run_wallet_copy_live_execution as live_execution
    from src.wallet_copy.research import unique_wallet_events

    window_start = 1_700_000_000
    dataapi_event = wallet_event(window_start=window_start, timestamp=window_start + 2)
    dataapi_event = WalletEvent.from_dict(
        {
            **dataapi_event.asdict(),
            "source": "polymarket_data_api",
            "observed_ts": window_start + 186,
            "api_latency_s": 184.0,
        }
    )
    rtds_event = WalletEvent.from_dict(
        {
            **dataapi_event.asdict(),
            "source": "rtds_activity",
            "observed_ts": window_start + 3,
            "api_latency_s": 1.0,
            "raw": {"rtds_subscription": "activity"},
        }
    )

    merged = unique_wallet_events([dataapi_event, rtds_event])

    assert len(merged) == 1
    assert merged[0].source == "rtds_activity"
    assert merged[0].observed_ts == window_start + 3
    assert merged[0].raw["observation_sources"] == ["polymarket_data_api", "rtds_activity"]

    key = (
        merged[0].source_wallet.lower(),
        merged[0].market_slug,
        merged[0].condition_id,
        merged[0].outcome,
    )
    intent, build_row = live_execution._event_to_inventory_intent(
        key=key,
        events=merged,
        policy=CandidatePolicy(policy_id="unit_rtds", wallet_fraction=0.10, max_order_usd=8.0),
        now_ts=window_start + 4,
        submitted_positions={},
        late_window_stop_s=1.0,
        live_build_max_observed_age_s=60.0,
        max_converge_orders_per_window=3,
    )

    assert intent is not None
    assert build_row["dominant_skip_reason"] == "eligible"
    assert intent.observed_ts == window_start + 3
    assert intent.api_latency_s == 1.0

    accepted, summary = live_execution._apply_profit_latency_suppression_gate(
        [intent],
        now_ts=window_start + 4,
        window_time_suppress_gte_s=180.0,
        signal_age_suppress_gte_s=60.0,
    )

    assert accepted == [intent]
    assert summary["blocked_intents"] == 0
    assert summary["sample_passed_intents"][0]["dataapi_first_seen_ts"] == window_start + 3
    assert summary["sample_passed_intents"][0]["detection_observed_ts"] == window_start + 3
    assert summary["sample_passed_intents"][0]["detection_source"] == "rtds_activity"


