def test_live_execution_drift_buffer_transforms_intents_with_positive_remaining_edge():
    from scripts.run_wallet_copy_live_execution import _apply_drift_buffer_policy

    intent = event_to_intent(wallet_event(price=0.42))
    assert intent is not None
    alpha_report = {
        "execution_profiles": {
            "profiles_by_wallet": {
                intent.source_wallet: {
                    "eligible": True,
                    "latency_horizon_s": 2.0,
                    "fill_sample": 25,
                    "copyable_rate_pct": 72.0,
                    "mean_edge": 0.03,
                    "edge_stats": {"p50": 0.01},
                }
            }
        }
    }

    transformed, summary = _apply_drift_buffer_policy(
        [intent],
        alpha_decay_report=alpha_report,
        enabled=True,
        max_buffer_price=0.05,
    )

    assert summary["status"] == "PASS"
    assert len(transformed) == 1
    buffered = transformed[0]
    assert buffered.limit_price == 0.43
    assert buffered.metadata["drift_buffer"]["buffer_price"] == 0.01
    assert buffered.metadata["drift_buffer"]["expected_edge_after_buffer"] == 0.02
    decision = intent_to_trade_executor_decision(
        type(buffered).from_dict({**buffered.asdict(), "mode": "live", "live_orders_allowed": True}),
        clob_token_ids=[buffered.token_id, "no-token"],
    )
    assert decision["limit_price"] == 0.43
