def test_fast_lane_generation_ignores_selection_churn_but_resets_on_policy_change() -> None:
    import scripts.run_wallet_copy_live_guard as guard

    args = SimpleNamespace(
        execute_live=True,
        explicit_live_operator_go=True,
        live_orders_allowed=True,
        operator_approval_id="approval",
        min_live_order_usd=1.0,
        wallet_fraction=0.1,
        max_order_usd=1.0,
        max_event_age_s=30.0,
        live_build_max_observed_age_s=30.0,
        price_band_decision_min_price=0.25,
        price_band_decision_max_price=0.5,
        profit_latency_window_time_suppress_gte_s=60.0,
        profit_latency_signal_age_suppress_gte_s=30.0,
        per_window_fill_cap=1,
    )
    member = {
        "candidate_id": "candidate",
        "source_wallet": "0x" + "a" * 40,
        "policy_id": "policy",
        "enabled": True,
        "status": "PASS",
        "policy": {
            "policy_id": "policy",
            "min_price": 0.25,
            "max_price": 0.5,
            "max_order_usd": 1.0,
            "wallet_fraction": 0.1,
        },
    }
    base = {"status": "PASS", "members": [member]}
    first = guard._orderfilled_fast_lane_runtime_generation(args, base)
    for cycle in range(100):
        churned = {
            **base,
            "generated_at": f"cycle-{cycle}",
            "status": f"observational-status-{cycle}",
            "refill_direction_id": f"observational-refill-{cycle}",
            "members": [{**member, "is_current_cycle_member": bool(cycle % 2), "counter": cycle}],
        }
        assert guard._orderfilled_fast_lane_runtime_generation(args, churned) == first
    changed = {
        **base,
        "members": [{**member, "policy": {**member["policy"], "max_order_usd": 2.0}}],
    }
    assert guard._orderfilled_fast_lane_runtime_generation(args, changed) != first


