def test_promote_intent_for_live_only_flips_execution_permission_fields():
    intent = event_to_intent(wallet_event())
    assert intent is not None

    live_intent = promote_intent_for_live(intent, operator_approval_id="approval-123")

    paper_payload = intent.asdict()
    live_payload = live_intent.asdict()
    assert live_payload["mode"] == "live"
    assert live_payload["live_orders_allowed"] is True
    assert live_payload["metadata"]["operator_approval_id"] == "approval-123"
    for key, value in paper_payload.items():
        if key in {"mode", "live_orders_allowed", "metadata"}:
            continue
        assert live_payload[key] == value
    assert live_payload["metadata"]["source_fingerprint"] == paper_payload["metadata"]["source_fingerprint"]


