def test_live_execution_blocks_runtime_pass_when_ranked_paper_candidate_has_hard_blockers():
    from scripts.run_wallet_copy_live_execution import _proof_blockers

    candidate = {
        "candidate_id": "runtime-candidate",
        "candidate_type": "SINGLE_WALLET",
        "status": "PASS",
        "policy": {"policy_id": "runtime_policy"},
        "metadata": {"source_wallet": "0xruntime"},
        "runtime_copy_evidence_resolved_blockers": [
            "validation_roi_below_minimum",
            "candidate_missing_clob_fill_evidence",
        ],
    }
    profit_state = {
        "decision": {"status": "PASS", "live_admission_status": "PASS", "live_admission_blockers": []},
        "live_readiness_certificate": {"live_ready": True, "blockers": []},
        "runtime_admission_candidate": candidate,
        "ranked_candidates": [
            {
                "candidate_id": "runtime-candidate",
                "status": "BLOCKED",
                "blockers": [
                    "validation_roi_below_minimum",
                    "candidate_missing_clob_fill_evidence",
                ],
            }
        ],
    }
    snapshot = LiveAdmissionSnapshot(
        decision_status="PASS",
        live_admission_status="PASS",
        live_tracker_truth_status="PASS",
    )

    blockers = _proof_blockers(profit_state, snapshot, candidate=candidate)

    assert "paper_ranked_candidate_blocker:validation_roi_below_minimum" in blockers
    assert "runtime_resolved_hard_paper_blocker:validation_roi_below_minimum" in blockers
    assert "paper_ranked_candidate_blocker:candidate_missing_clob_fill_evidence" not in blockers


