def test_live_execution_skips_already_submitted_intents(tmp_path: Path):
    from scripts.run_wallet_copy_live_execution import _drop_already_live_submitted_intents

    old_intent = event_to_intent(wallet_event(condition="0xold"))
    new_intent = event_to_intent(wallet_event(condition="0xnew"))
    assert old_intent is not None
    assert new_intent is not None
    ledger = tmp_path / "live_execution_state.json"
    ledger.write_text(
        json.dumps(
            {
                "kind": "wallet_copy_live_execution_state",
                "orders": [{"intent_id": old_intent.intent_id}],
            }
        ),
        encoding="utf-8",
    )

    fresh, summary = _drop_already_live_submitted_intents(
        [old_intent, new_intent],
        live_ledger_state=str(ledger),
    )

    assert fresh == [new_intent]
    assert summary["input_intents"] == 2
    assert summary["new_intents"] == 1
    assert summary["already_submitted_intents"] == 1
    assert summary["skipped_intent_ids"] == [old_intent.intent_id]


def test_live_execution_window_fill_cap_filters_filled_and_same_cycle_intents(tmp_path: Path):
    import scripts.run_wallet_copy_live_execution as live_execution

    filled_window = event_to_intent(
        wallet_event(wallet_name="filled", wallet="0xaaa", condition="0xfilled", window_start=1_700_000_000)
    )
    new_window = event_to_intent(
        wallet_event(wallet_name="new", wallet="0xbbb", condition="0xnew", window_start=1_700_000_300)
    )
    first_same_cycle = event_to_intent(
        wallet_event(wallet_name="cycle-a", wallet="0xccc", condition="0xcycle", window_start=1_700_000_600)
    )
    second_same_cycle = event_to_intent(
        wallet_event(wallet_name="cycle-b", wallet="0xddd", condition="0xcycle", window_start=1_700_000_600)
    )
    assert filled_window is not None
    assert new_window is not None
    assert first_same_cycle is not None
    assert second_same_cycle is not None
    ledger = tmp_path / "live_execution_state.json"
    ledger.write_text(
        json.dumps(
            {
                "kind": "wallet_copy_live_execution_state",
                "orders": [
                    {
                        "final_status": "FILLED",
                        "market_slug": filled_window.market_slug,
                        "source_intent": {"market_slug": filled_window.market_slug},
                    }
                ],
            }
        ),
        encoding="utf-8",
    )

    accepted, summary = live_execution._apply_window_fill_cap_gate(
        [filled_window, new_window, first_same_cycle, second_same_cycle],
        live_ledger_state=str(ledger),
        per_window_fill_cap=1,
    )

    assert [intent.source_event_id for intent in accepted] == [
        new_window.source_event_id,
        first_same_cycle.source_event_id,
    ]
    assert summary["per_window_fill_cap"] == 1
    assert summary["taxonomy_counts"] == {"window_fill_cap": 2}
    assert [row["reject_reason"] for row in summary["sample_filtered_intents"]] == [
        "window_fill_cap",
        "window_fill_cap",
    ]
    assert summary["sample_filtered_intents"][0]["window_fills_before"] == 1
    assert summary["sample_filtered_intents"][0]["window_occupied_before"] == 1
    assert summary["sample_filtered_intents"][1]["window_fills_before"] == 0
    assert summary["sample_filtered_intents"][1]["window_occupied_before"] == 1

    event_log = tmp_path / "live_execution_events.jsonl"
    assert (
        live_execution._append_window_fill_cap_events(
            str(event_log),
            summary,
            decision_ts="2026-07-11T08:21:00Z",
        )
        == 2
    )
    events = [json.loads(line) for line in event_log.read_text(encoding="utf-8").splitlines()]
    assert [event["event"] for event in events] == [
        "wallet_copy_live_window_fill_cap_skip",
        "wallet_copy_live_window_fill_cap_skip",
    ]
    assert {event["approved_suppression"] for event in events} == {True}
    assert {event["reject_reason"] for event in events} == {"window_fill_cap"}


