def test_live_wallet_tracker_polls_wallet_truth_and_writes_paper(tmp_path: Path, monkeypatch):
    registry = tmp_path / "wallets.json"
    registry.write_text(
        '{"wallets":[{"name":"alpha","address":"0xabc","enabled":true,"market_filter":"btc_5m","asset_allowlist":["BTC"]}]}',
        encoding="utf-8",
    )

    class FakeHistoryClient:
        def __init__(self, spec):
            self.spec = spec
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1}

        def fetch_events(self, *, limit=100, pages=1, include_activity=True):
            return [wallet_event(wallet_name="alpha", wallet="0xabc")]

    def fake_book(self, token_id):
        return {
            "market": "0xcond",
            "asset_id": token_id,
            "timestamp": "1700000001",
            "hash": "bookhash",
            "asks": [{"price": "0.42", "size": "100"}],
            "bids": [{"price": "0.41", "size": "100"}],
        }

    monkeypatch.setattr("src.wallet_copy.live_tracker.WalletHistoryClient", FakeHistoryClient)
    monkeypatch.setattr("src.wallet_copy.live_tracker.CLOBMarketClient.get_book", fake_book)
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(registry),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            tracker_time_replay_paper_state_path=str(tmp_path / "tracker_time_replay_paper_state.json"),
            tracker_time_replay_paper_event_log_path=str(tmp_path / "tracker_time_replay_paper_events.jsonl"),
                wallet_fraction=0.5,
                max_order_usd=2.0,
                enable_clob_books=True,
                admission_mode=True,
            )
        )

    state = tracker.poll_once()

    assert state["summary"]["new_wallet_events"] == 1
    assert state["summary"]["new_buy_copy_intents"] == 1
    assert state["summary"]["mirror_required_events"] == 1
    assert state["summary"]["mirror_coverage_status"] == "PASS"
    assert state["summary"]["admission_config_eligible"] is True
    assert state["summary"]["admission_eligible"] is True
    assert state["summary"]["research_mode"] is False
    assert state["summary"]["latency"]["api_latency_max_s"] == 2.0
    assert state["summary"]["latency"]["event_age_max_s"] == 2.0
    assert state["summary"]["latency"]["latency_basis"].startswith("api_latency_s is legacy")
    assert state["summary"]["evidence_status_counts"]["mirror_status"]["MIRRORED_BUY_TO_PAPER"] == 1
    assert state["summary"]["wallet_reports"][0]["freshness_diagnosis"]["fresh_buy_rows_le_10s"] == 1
    assert state["summary"]["wallet_reports"][0]["freshness_diagnosis"]["source_feed_delayed"] is False
    assert state["last_moves"][0]["tracking_evidence"]["clob_book"]["instant_fill_status"] == "PASS"
    assert state["last_moves"][0]["tracking_evidence"]["clob_book"]["admission_relevant"] is True
    assert state["last_moves"][0]["mirror_result"]["mirror_status"] == "MIRRORED_BUY_TO_PAPER"
    assert state["last_moves"][0]["copy_efficiency"]["copy_status"] == "COPIED_FILLED"
    assert state["last_moves"][0]["copy_efficiency"]["clob_book_status"] == "OK"
    assert state["last_moves"][0]["copy_efficiency"]["clob_book_admission_relevant"] is True
