    assert state["summary"]["copy_efficiency"]["summary"]["clob_book_status_counts_for_fresh_buys"] == {"OK": 1}
    assert state["summary"]["copy_efficiency"]["summary"]["fallback_filled_buy_copy_events"] == 0
    assert state["summary"]["paper_summary"]["paper_orders"] == 1
