def test_live_wallet_tracker_keeps_fetch_report_when_poll_deadline_expires_after_fetch(
    tmp_path: Path, monkeypatch
):
    registry = tmp_path / "wallets.json"
    registry.write_text(
        '{"wallets":[{"name":"alpha","address":"0xabc","enabled":true,"market_filter":"btc_5m","asset_allowlist":["BTC"]}]}',
        encoding="utf-8",
    )

    class FakeHistoryClient:
        def __init__(self, spec):
            self.spec = spec
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "raw_rows": 0}

        def fetch_events(
            self,
            *,
            limit=100,
            pages=1,
            include_activity=True,
            trade_query_keys=None,
            parallel_sources=False,
        ):
            time.sleep(0.02)
            event = wallet_event(wallet_name="alpha", wallet="0xabc")
            self.last_fetch_report = {
                "stop_reason": "page_limit",
                "pages_read": 1,
                "raw_rows": 1,
                "source_row_counts": {"trade:user": 1},
            }
            return [event]

    monkeypatch.setattr("src.wallet_copy.live_tracker.WalletHistoryClient", FakeHistoryClient)
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(registry),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            tracker_time_replay_paper_state_path=str(tmp_path / "tracker_time_replay_paper_state.json"),
            tracker_time_replay_paper_event_log_path=str(tmp_path / "tracker_time_replay_paper_events.jsonl"),
            max_poll_runtime_s=0.001,
            enable_clob_books=False,
            admission_mode=True,
        )
    )

    state = tracker.poll_once()

    report = state["summary"]["wallet_reports"][0]
    assert report["wallet"] == "0xabc"
    assert report["raw_rows"] == 1
    assert report["events_seen"] == 1
    assert report["new_events"] == 1
    assert report["runtime_limited_events_skipped"] == 0
    assert report["poll_deadline_exceeded_before_event_processing"] is True
    assert report["deadline_after_fetch_processing_all_fetched_events"] is True

    diagnostics = state["summary"]["current_poll_diagnostics"]
    assert diagnostics["current_poll_ladder"]["wallets_polled"] == 1
    assert diagnostics["current_poll_ladder"]["raw_rows"] == 1
    assert diagnostics["current_poll_ladder"]["runtime_limited_events_skipped"] == 0
    assert diagnostics["current_poll_ladder"]["runtime_limited_buy_events_skipped"] == 0
    assert diagnostics["current_poll_ladder"]["runtime_limited_fresh_buy_events_skipped"] == 0
    assert diagnostics["current_poll_ladder"]["after_dedupe_events"] == 1
    assert state["summary"]["poll_runtime"]["status"] == "LIMIT_REACHED"
    assert state["summary"]["poll_runtime"]["skipped_events"] == 0


