    assert matrix["paper_only"] is True
    assert matrix["live_orders_allowed"] is False
    matrix_rows = {row["profile_id"]: row for row in matrix["policy_profiles"]}
    assert matrix_rows["strict_current"]["rejected_events"] == 1
    assert matrix_rows["aggressive_best_ask_1500bps"]["filled_events"] == 1
    assert matrix_rows["aggressive_best_ask_1500bps"]["selected_for_replay"] is True
    assert replay["event_proofs"][0]["strict_status"] == "REJECTED"
    assert replay["event_proofs"][0]["tactic_status"] == "FILLED"
    assert replay["event_proofs"][0]["book_hash"] == "bookhash-aggressive-replay"
    assert replay["paper_only"] is True
    assert replay["live_orders_allowed"] is False
    tactic_state = json.loads((tmp_path / "all_order_tactic_paper_state.json").read_text(encoding="utf-8"))
    assert tactic_state["summary"]["filled_orders"] == 1


