def test_live_wallet_tracker_skips_clob_fetch_for_prefetch_stale_admission_buy(tmp_path: Path, monkeypatch):
    def fail_book(self, token_id):
        raise AssertionError(f"stale admission buy should not fetch CLOB book for {token_id}")

    monkeypatch.setattr("src.wallet_copy.live_tracker.CLOBMarketClient.get_book", fail_book)
    event = wallet_event(timestamp=1_700_000_000)
    stale_event = WalletEvent.from_dict(
        {
            **event.asdict(),
            "observed_ts": 1_700_000_022.0,
            "raw": {
                **event.raw,
                "_walletCopySourceFetchStartedTs": 1_700_000_021.0,
                "_walletCopySourceFetchCompletedTs": 1_700_000_021.05,
                "_walletCopySourceFetchDurationS": 0.05,
                "_walletCopySourceFetchSource": "user",
            },
        }
    )
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(tmp_path / "wallets.json"),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            max_copyability_event_age_s=10.0,
            enable_clob_books=True,
            admission_mode=True,
        )
    )
    cache_report = {
        "lookup_events": 0,
        "cache_hits": 0,
        "cache_misses": 0,
        "errors": 0,
        "stale_not_admission_relevant_skipped": 0,
        "token_ids": set(),
        "fetch_durations_s": [],
    }

    evidence = tracker._enrich_event(
        stale_event,
        2.0,
        [],
        clob_book_cache={},
        clob_book_cache_report=cache_report,
    )

    clob = evidence["clob_book"]
    assert clob["status"] == "SKIPPED_STALE_SOURCE_FEED_NOT_ADMISSION_RELEVANT"
    assert clob["reason"] == "event_age_at_source_fetch_start_above_cap"
    assert clob["source_feed_stale_for_admission"] is True
    assert clob["admission_relevant"] is False
    assert clob["event_age_at_source_fetch_start_s"] == 21.0
    assert cache_report["lookup_events"] == 0
    assert cache_report["cache_misses"] == 0
    assert cache_report["stale_not_admission_relevant_skipped"] == 1


