def test_live_wallet_tracker_processes_completed_parallel_wallet_before_slow_pending_wallet(
    tmp_path: Path, monkeypatch
):
    registry = tmp_path / "wallets.json"
    registry.write_text(
        json.dumps(
            {
                "wallets": [
                    {"name": "alpha", "address": "0xaaa", "enabled": True, "market_filter": "btc_5m"},
                    {"name": "bravo", "address": "0xbbb", "enabled": True, "market_filter": "btc_5m"},
                ]
            }
        ),
        encoding="utf-8",
    )

    class FakeHistoryClient:
        def __init__(self, spec, *args, **kwargs):
            self.spec = spec
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "fetch_duration_s": 0.0}

        def fetch_events(
            self,
            *,
            limit=100,
            pages=1,
            include_activity=True,
            trade_query_keys=("user", "proxyWallet"),
            parallel_sources=False,
        ):
            if self.spec.name == "bravo":
                time.sleep(0.2)
                self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "fetch_duration_s": 0.2}
                return [wallet_event(wallet_name="bravo", wallet="0xbbb")]
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "fetch_duration_s": 0.001}
            return [wallet_event(wallet_name="alpha", wallet="0xaaa")]

    monkeypatch.setattr("src.wallet_copy.live_tracker.WalletHistoryClient", FakeHistoryClient)
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(registry),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            enable_clob_books=False,
            enable_copyability_gate=False,
            max_poll_runtime_s=0.05,
            parallel_wallet_fetches=2,
        )
    )

    state = tracker.poll_once()

    assert state["summary"]["new_wallet_events"] == 1
    assert state["last_moves"][0]["wallet_event"]["source_wallet"] == "0xaaa"
    assert state["summary"]["wallet_reports"][0]["wallet"] == "0xaaa"
    assert [report["wallet"] for report in state["summary"]["wallet_reports"]] == ["0xaaa", "0xbbb"]
    skipped_report = state["summary"]["wallet_reports"][1]
    assert skipped_report["events_seen"] == 0
    assert skipped_report["new_events"] == 0
    assert skipped_report["raw_rows"] == 0
    assert skipped_report["poll_deadline_exceeded_before_event_processing"] is True
    assert skipped_report["poll_runtime_skip_reason"] == "poll_processing_reserve_before_wallet_fetch_completed"
    assert state["summary"]["poll_runtime"]["status"] == "LIMIT_REACHED"
    assert state["summary"]["poll_runtime"]["skipped_wallet_addresses"] == ["0xbbb"]
    diagnostics = state["summary"]["current_poll_diagnostics"]
    assert diagnostics["current_poll_ladder"]["wallets_polled"] == 2
    assert diagnostics["current_poll_ladder"]["runtime_limited_wallet_reports"] == 1
    assert "current_poll_runtime_limited_before_event_processing" in diagnostics["blockers"]


def test_live_wallet_tracker_prioritizes_fresh_buy_when_event_processing_runtime_limited(
    tmp_path: Path, monkeypatch
):
    registry = tmp_path / "wallets.json"
    registry.write_text(
        json.dumps(
            {
                "wallets": [
                    {"name": "alpha", "address": "0xaaa", "enabled": True, "market_filter": "btc_5m"},
                ]
            }
        ),
        encoding="utf-8",
    )
    old_event = wallet_event(
        wallet_name="alpha",
        wallet="0xaaa",
        condition="0xold",
        window_start=1_699_999_700,
        timestamp=1_699_999_700,
    )
    fresh_event = wallet_event(
        wallet_name="alpha",
        wallet="0xaaa",
        condition="0xfresh",
        window_start=1_700_000_000,
        timestamp=1_700_000_000,
    )

    class FakeHistoryClient:
        def __init__(self, spec, *args, **kwargs):
            self.spec = spec
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "fetch_duration_s": 0.0}

        def fetch_events(
            self,
            *,
            limit=100,
            pages=1,
            include_activity=True,
            trade_query_keys=("user", "proxyWallet"),
            parallel_sources=False,
        ):
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "fetch_duration_s": 0.001}
            return [old_event, fresh_event]

    clock = {"now": 1_700_000_002.0}

    def fake_time():
        return clock["now"]

    original_enrich = LiveWalletTracker._enrich_event

    def slow_enrich(self, *args, **kwargs):
        result = original_enrich(self, *args, **kwargs)
        clock["now"] += 2.0
        return result

    monkeypatch.setattr("src.wallet_copy.live_tracker.WalletHistoryClient", FakeHistoryClient)
    monkeypatch.setattr("src.wallet_copy.live_tracker.time.time", fake_time)
    monkeypatch.setattr(LiveWalletTracker, "_enrich_event", slow_enrich)
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(registry),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            enable_clob_books=False,
            enable_copyability_gate=False,
            max_poll_runtime_s=1.0,
        )
    )

    state = tracker.poll_once()
    report = state["summary"]["wallet_reports"][0]

    assert state["summary"]["new_wallet_events"] == 1
    assert state["last_moves"][0]["wallet_event"]["condition_id"] == "0xfresh"
    assert report["event_processing_priority"] == "fresh_buy_first_desc_event_ts"
    assert report["runtime_limited_events_skipped"] == 1
    assert report["runtime_limited_buy_events_skipped"] == 1
    assert report["runtime_limited_fresh_buy_events_skipped"] == 0
    diagnostics = state["summary"]["current_poll_diagnostics"]
    assert diagnostics["current_poll_ladder"]["runtime_limited_buy_events_skipped"] == 1
    assert diagnostics["current_poll_ladder"]["runtime_limited_fresh_buy_events_skipped"] == 0


def test_live_wallet_tracker_reports_runtime_skipped_wallets_when_parallel_poll_times_out(
    tmp_path: Path, monkeypatch
):
    registry = tmp_path / "wallets.json"
    registry.write_text(
        json.dumps(
            {
                "wallets": [
                    {"name": "alpha", "address": "0xaaa", "enabled": True, "market_filter": "btc_5m"},
                    {"name": "bravo", "address": "0xbbb", "enabled": True, "market_filter": "btc_5m"},
                ]
            }
        ),
        encoding="utf-8",
    )

    class FakeClock:
        def __init__(self):
            self.value = 0.0

        def __call__(self):
            return self.value

        def advance(self, seconds):
            self.value += seconds

    fake_clock = FakeClock()

    class SlowHistoryClient:
        def __init__(self, spec, *args, **kwargs):
            self.spec = spec
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "fetch_duration_s": 0.0}

        def fetch_events(
            self,
            *,
            limit=100,
            pages=1,
            include_activity=True,
            trade_query_keys=("user", "proxyWallet"),
            parallel_sources=False,
        ):
            fake_clock.advance(0.05)
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "fetch_duration_s": 0.05}
            return [wallet_event(wallet_name=self.spec.name, wallet=self.spec.address)]

    monkeypatch.setattr("src.wallet_copy.live_tracker.WalletHistoryClient", SlowHistoryClient)
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(registry),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            enable_clob_books=False,
            enable_copyability_gate=False,
            max_poll_runtime_s=0.001,
            parallel_wallet_fetches=2,
        )
    )
    tracker._poll_clock = fake_clock

    state = tracker.poll_once()

    reports = state["summary"]["wallet_reports"]
    assert [report["wallet"] for report in reports] == ["0xaaa", "0xbbb"]
    assert all(report["events_seen"] == 0 for report in reports)
    assert all(report["poll_deadline_exceeded_before_event_processing"] is True for report in reports)
    accepted_before_fetch_reasons = {
        "poll_deadline_exceeded_before_wallet_fetch_completed",
        "poll_deadline_timeout_before_wallet_fetch_completed",
    }
    assert {report["poll_runtime_skip_reason"] for report in reports} <= accepted_before_fetch_reasons
    assert state["summary"]["poll_runtime"]["status"] == "LIMIT_REACHED"
    assert state["summary"]["poll_runtime"]["skipped_wallet_addresses"] == ["0xaaa", "0xbbb"]

    diagnostics = state["summary"]["current_poll_diagnostics"]
    assert diagnostics["current_poll_ladder"]["wallets_polled"] == 2
    assert diagnostics["current_poll_ladder"]["raw_rows"] == 0
    assert diagnostics["current_poll_ladder"]["runtime_limited_wallet_reports"] == 2
    reason_counts = diagnostics["current_poll_ladder"]["runtime_limited_reason_counts"]
    assert set(reason_counts) <= accepted_before_fetch_reasons
    assert sum(reason_counts.values()) == 2
    assert diagnostics["zero_current_poll_root_cause"] == "runtime_limited_before_event_processing"
    assert "raw_source_rows_zero" in diagnostics["blockers"]
    assert "current_poll_runtime_limited_before_event_processing" in diagnostics["blockers"]


