def test_admission_evidence_window_requires_matching_hot_path_trade_query_scope():
    def move(label: str, *, window_start: int) -> dict:
        return {
            "source_fingerprint": label,
            "wallet_event": wallet_event(wallet_name=label, wallet="0xabc", window_start=window_start).asdict(),
            "mirror_result": {"mirror_classifier_version": 3, "profit_policy_context_id": "policy"},
        }

    legacy_default_scope_move = move("legacy-default", window_start=1_700_000_000)
    full_scope_move = move("full-scope", window_start=1_700_000_300) | {
        "source_fingerprint": "full-scope",
        "data_api_trade_query_keys": ["user", "proxyWallet"],
    }
    user_scope_move = move("user-scope", window_start=1_700_000_600) | {
        "source_fingerprint": "user-scope",
        "data_api_trade_query_keys": ["user"],
    }

    user_only = _admission_evidence_window(
        [legacy_default_scope_move, full_scope_move, user_scope_move],
        limit=10,
        mirror_classifier_version=3,
        profit_policy_context_id="policy",
        trade_query_keys=("user",),
    )
    default_audit = _admission_evidence_window(
        [legacy_default_scope_move, full_scope_move, user_scope_move],
        limit=10,
        mirror_classifier_version=3,
        profit_policy_context_id="policy",
        trade_query_keys=("user", "proxyWallet"),
    )

    assert [row["source_fingerprint"] for row in user_only] == ["user-scope"]
    assert [row["source_fingerprint"] for row in default_audit] == ["legacy-default", "full-scope"]


