def test_live_wallet_tracker_flags_fill_model_reject_in_copy_efficiency(tmp_path: Path, monkeypatch):
    registry = tmp_path / "wallets.json"
    registry.write_text(
        '{"wallets":[{"name":"alpha","address":"0xabc","enabled":true,"market_filter":"btc_5m","asset_allowlist":["BTC"]}]}',
        encoding="utf-8",
    )

    class FakeHistoryClient:
        def __init__(self, spec):
            self.spec = spec
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1}

        def fetch_events(self, *, limit=100, pages=1, include_activity=True):
            return [wallet_event(wallet_name="alpha", wallet="0xabc")]

    def fake_book(self, token_id):
        return {
            "market": "0xcond",
            "asset_id": token_id,
            "timestamp": "1700000001",
            "hash": "thinbook",
            "asks": [{"price": "0.99", "size": "1"}],
            "bids": [{"price": "0.41", "size": "100"}],
        }

    monkeypatch.setattr("src.wallet_copy.live_tracker.WalletHistoryClient", FakeHistoryClient)
    monkeypatch.setattr("src.wallet_copy.live_tracker.CLOBMarketClient.get_book", fake_book)
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(registry),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            enable_clob_books=True,
            enable_copyability_gate=False,
        )
    )

    state = tracker.poll_once()

    assert state["summary"]["mirror_coverage_status"] == "PASS"
    assert state["last_moves"][0]["mirror_result"]["mirror_status"] == "MIRRORED_BUY_TO_PAPER_REJECTED_BY_FILL_MODEL"
    assert state["summary"]["copy_efficiency"]["status"] == "FAIL"
    assert "paper_order_rejected" in state["summary"]["copy_efficiency"]["blockers"]
    assert state["summary"]["copy_efficiency"]["summary"]["rejected_buy_copy_events"] == 1
    contract = state["summary"]["paper_copy_contract"]
    assert contract["current_poll"]["status"] == "CORRECTION"
    assert "copyable_buy_not_clob_backed_paper_filled" in contract["current_poll"]["blockers"]
    assert "paper_order_rejected" in contract["current_poll"]["blockers"]
    score = state["last_moves"][0]["copy_efficiency"]
    assert score["reject_reason"] == "clob_price_above_slippage_cap"
    assert score["reject_details"]["blocking_reason"] == "price_above_slippage_cap"
    assert score["clob_blocking_reason"] == "price_above_slippage_cap"
    summary = state["summary"]["copy_efficiency"]["summary"]
    assert summary["rejection_reason_counts"]["clob_price_above_slippage_cap"] == 1
    assert summary["fill_blocker_counts"]["clob_fill_ratio_below_minimum"] == 1
    assert summary["clob_blocking_reason_counts"]["price_above_slippage_cap"] == 1
    assert summary["clob_admission_fill_rate_pct"] == 0.0


