def test_live_wallet_tracker_classifies_lifecycle_miss_after_copyability_filtered_entry(tmp_path: Path, monkeypatch):
    registry = tmp_path / "wallets.json"
    registry.write_text(
        '{"wallets":[{"name":"alpha","address":"0xabc","enabled":true,"market_filter":"btc_5m","asset_allowlist":["BTC"]}]}',
        encoding="utf-8",
    )

    stale_buy = wallet_event(
        wallet_name="alpha",
        wallet="0xabc",
        window_start=1_699_999_800,
        timestamp=1_699_999_800,
    )
    redeem = lifecycle_event(
        "REDEEM",
        wallet_name="alpha",
        wallet="0xabc",
        condition=stale_buy.condition_id,
        outcome=stale_buy.outcome,
        size=stale_buy.size,
        timestamp=1_700_000_001,
    )

    class FakeHistoryClient:
        def __init__(self, spec, *args, **kwargs):
            self.spec = spec
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1, "fetch_duration_s": 0.25}

        def fetch_events(self, *, limit=100, pages=1, include_activity=True):
            return [stale_buy, redeem]

    def fake_book(self, token_id):
        return {
            "market": "0xcond",
            "asset_id": token_id,
            "timestamp": "1700000001",
            "hash": "bookhash",
            "asks": [{"price": "0.42", "size": "100"}],
            "bids": [{"price": "0.41", "size": "100"}],
        }

    monkeypatch.setattr("src.wallet_copy.live_tracker.WalletHistoryClient", FakeHistoryClient)
    monkeypatch.setattr("src.wallet_copy.live_tracker.CLOBMarketClient.get_book", fake_book)
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(registry),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            enable_clob_books=True,
            max_copyability_event_age_s=10.0,
        )
    )

    state = tracker.poll_once()

    assert state["summary"]["mirror_coverage_status"] == "NO_REQUIRED_EVIDENCE"
    assert state["summary"]["copy_efficiency"]["summary"]["copyability_filtered_buy_events"] == 1
    assert state["summary"]["copy_efficiency"]["status"] == "WATCH"
    assert state["summary"]["copy_efficiency"]["summary"]["lifecycle_filtered_events"] == 1
    assert state["summary"]["copy_efficiency"]["summary"]["lifecycle_filter_reason_counts"] == {
        "lifecycle_filtered_due_to_entry_copyability": 1
    }
    lifecycle_move = next(move for move in state["last_moves"] if move["action"] == "REDEEM")
    mirror_result = lifecycle_move["mirror_result"]
    assert mirror_result["coverage_status"] == "FILTERED"
    assert mirror_result["mirror_status"] == "FILTERED_BY_COPYABILITY_ENTRY"
    assert mirror_result["lifecycle_filter_class"] == "lifecycle_filtered_due_to_entry_copyability"
    assert mirror_result["filtered_entry_context"]["match_scope"] == "same_condition_outcome"
    assert mirror_result["filtered_entry_context"]["reason_counts"] == {"event_age_above_cap": 1}
    assert state["summary"]["lifecycle_miss_class_counts"] == {}


