def test_load_resolutions_prefers_canonical_over_research_only_for_same_window(tmp_path: Path):
    resolutions = tmp_path / "resolutions.jsonl"
    resolutions.write_text(
        "\n".join(
            [
                json.dumps(
                    {
                        "expiry_unix_ts": 1_700_000_300,
                        "direction": "UP",
                        "source": "polymarket_gamma_resolved_outcome",
                        "research_only": False,
                        "window_type": "5m",
                        "yes_token": "yes-token",
                    }
                ),
                json.dumps(
                    {
                        "expiry_unix_ts": 1_700_000_300,
                        "direction": "DOWN",
                        "source": "binance_spot_1m_kline_research_patch",
                        "research_only": True,
                        "window_type": "5m",
                    }
                ),
            ]
        )
        + "\n",
        encoding="utf-8",
    )

    loaded = load_resolutions(resolutions)

    assert loaded["expiry:1700000300"]["source"] == "polymarket_gamma_resolved_outcome"
    assert loaded["slug_start:1700000000"]["research_only"] is False
    assert loaded["yes-token"]["direction"] == "UP"


