def test_live_tracker_aggressive_tactic_replay_reports_policy_validation(tmp_path: Path, monkeypatch):
    registry = tmp_path / "wallets.json"
    registry.write_text(
        '{"wallets":[{"name":"alpha","address":"0xabc","enabled":true,"market_filter":"btc_5m","asset_allowlist":["BTC"]}]}',
        encoding="utf-8",
    )

    class FakeHistoryClient:
        def __init__(self, spec):
            self.spec = spec
            self.last_fetch_report = {"stop_reason": "page_limit", "pages_read": 1}

        def fetch_events(self, *, limit=100, pages=1, include_activity=True):
            return [
                wallet_event(
                    wallet_name="alpha",
                    wallet="0xabc",
                    price=0.42,
                    outcome="Up",
                    window_start=1_700_000_000,
                )
            ]

    def fake_book(self, token_id):
        return {
            "market": "0xcond",
            "asset_id": token_id,
            "timestamp": "1700000001",
            "hash": "bookhash-policy-validation",
            "asks": [{"price": "0.47", "size": "100"}],
            "bids": [{"price": "0.41", "size": "100"}],
        }

    resolutions = tmp_path / "resolutions.jsonl"
    resolutions.write_text(
        '{"expiry_unix_ts":1700000300,"direction":"UP","source":"unit","research_only":false}\n',
        encoding="utf-8",
    )

    monkeypatch.setattr("src.wallet_copy.live_tracker.WalletHistoryClient", FakeHistoryClient)
    monkeypatch.setattr("src.wallet_copy.live_tracker.CLOBMarketClient.get_book", fake_book)
    tracker = LiveWalletTracker(
        LiveTrackerConfig(
            registry_path=str(registry),
            state_path=str(tmp_path / "tracker_state.json"),
            event_log_path=str(tmp_path / "tracker_events.jsonl"),
            paper_state_path=str(tmp_path / "paper_state.json"),
            paper_event_log_path=str(tmp_path / "paper_events.jsonl"),
            all_order_exact_copy_paper_state_path=str(tmp_path / "all_order_paper_state.json"),
            all_order_exact_copy_paper_event_log_path=str(tmp_path / "all_order_paper_events.jsonl"),
            all_order_tactic_replay_paper_state_path=str(tmp_path / "all_order_tactic_paper_state.json"),
            all_order_tactic_replay_paper_event_log_path=str(tmp_path / "all_order_tactic_paper_events.jsonl"),
            resolutions_path=str(resolutions),
            wallet_fraction=0.5,
            max_order_usd=2.0,
            enable_clob_books=True,
            admission_mode=True,
        )
    )

    state = tracker.poll_once()

    replay = state["summary"]["all_order_exact_copy"]["aggressive_tactic_replay"]
    assert replay["status"] == "PASS"
    assert replay["pnl_attribution_status"] == "PASS"
    assert replay["pnl_attribution_blockers"] == []
    assert replay["policy_validation"]["status"] == "PASS"
    assert replay["policy_validation"]["role"] == "paper_only_aggressive_tactic_policy_validation_not_live_admission"
    assert replay["policy_validation"]["resolution_rows_indexed"] > 0
    assert replay["policy_validation"]["pnl_attribution"]["canonical_resolved_orders"] == 1
    assert replay["policy_validation"]["pnl_attribution"]["tactic_pnl_usd"] > 0
    assert replay["policy_validation"]["paper_only"] is True
    assert replay["policy_validation"]["live_orders_allowed"] is False


