def test_current_poll_progress_promotes_flow_control_shadow_measurement(monkeypatch):
    from scripts.run_wallet_copy_autonomous_repair import _attach_current_poll_progress_diagnostics

    shadow_plan = {
        "status": "CORRECTION",
        "role": "paper_only_flow_control_shadow_measurement_not_live_admission",
        "paper_only": True,
        "live_orders_allowed": False,
        "profile_id": "aggressive_best_ask_250bps",
        "blocked_recommended_tactic": "paper_profile_replay:aggressive_best_ask_250bps",
        "best_profile_pass_events": 7,
        "incremental_pass_events_vs_strict": 1,
        "flow_control_next_action": (
            "delay_recheck_or_rotate_no_liquidity_events_before_size_or_slippage_tuning"
        ),
        "blockers": [
            "blocked_by_flow_control_not_live_admission",
            "paper_shadow_profile_needs_resolved_pnl_attribution",
        ],
        "verification_command": (
            "python3 scripts/run_wallet_copy_autonomous_repair.py --deep-research --command-timeout-s 900"
        ),
    }

    monkeypatch.setattr(
        "scripts.run_wallet_copy_autonomous_repair._current_poll_progress_diagnostics",
        lambda: {
            "status": "WATCH",
            "role": "diagnostic_only_not_live_admission_truth",
            "blockers": ["active_forward_all_order_live_truth_correction"],
            "verify": "diagnostic verify",
            "tracker_rows": [
                {
                    "tracker": "active_forward",
                    "all_order_execution_tactic_plan": {
                        "recommended_tactic": "paper_diagnose_unfillable_or_stale_copy_events",
                        "flow_control_shadow_measurement_plan": shadow_plan,
                    },
                }
            ],
        },
    )

    action = _attach_current_poll_progress_diagnostics(
        {
            "area": "candidate-forward micro/depth copy tactic planning",
            "file": "src/wallet_copy/copy_tactics.py",
            "function": "build_copy_execution_tactic_plan",
            "action": "old action",
            "blockers": ["strict_all_order_rejected_orders_present"],
            "next_command": "python3 scripts/run_wallet_copy_autonomous_repair.py --command-timeout-s 240",
            "verify": "old verify",
        }
    )

    assert action["area"] == "candidate-forward flow-control shadow PnL measurement"
    assert action["type"] == "sharper_measurement"
    assert action["progress_type"] == "sharper_measurement"
    assert action["next_command"] == (
        "python3 scripts/run_wallet_copy_autonomous_repair.py --deep-research --command-timeout-s 900"
    )
    assert action["shadow_tracker"] == "active_forward"
    assert action["shadow_profile_id"] == "aggressive_best_ask_250bps"
    assert action["blocked_recommended_tactic"] == "paper_profile_replay:aggressive_best_ask_250bps"
    assert action["shadow_profile_pass_events"] == 7
    assert action["shadow_incremental_pass_events_vs_strict"] == 1
    assert action["paper_only"] is True
    assert action["live_orders_allowed"] is False
    assert "flow_control_shadow_pnl_measurement_required" in action["blockers"]
    assert "current_poll_diagnostics" in action["verify"]


