def test_performance_reports_lifecycle_realized_pnl(tmp_path: Path):
    event = wallet_event(price=0.4, size=10.0)
    sell = lifecycle_event("SELL", size=5.0)
    sell = WalletEvent.from_dict({**sell.asdict(), "price": 0.7, "usdc_size": 3.5})
    engine = PaperWalletCopyEngine(
        PaperExecutionConfig(
            state_path=str(tmp_path / "paper_state.json"),
            event_log_path=str(tmp_path / "paper_events.jsonl"),
        )
    )
    state = engine.apply_intents(build_intents([event]))
    state = engine.apply_wallet_lifecycle_events([sell])
    resolutions = tmp_path / "resolutions.jsonl"
    resolutions.write_text("", encoding="utf-8")

    report = score_paper_state(state, resolutions_path=resolutions)

    assert report["lifecycle_realized"]["realized_events"] == 1
    assert report["lifecycle_realized"]["realized_pnl_usd"] > 0


