def test_live_tracker_truth_aggregates_candidate_runtime_windows_from_event_log(tmp_path: Path):
    tracker_state = tmp_path / "candidate_forward_state.json"
    candidate_id = "candidate_runtime"
    policy_id = "candidate_policy"
    wallet = "0xcandidate"

    def score(source_event_id: str, market_slug: str) -> dict:
        return {
            "candidate_id": candidate_id,
            "profit_policy_candidate_id": candidate_id,
            "policy_id": policy_id,
            "profit_policy_id": policy_id,
            "source_event_id": source_event_id,
            "source_wallet": wallet,
            "wallet_action": "BUY",
            "market_slug": market_slug,
            "copy_status": "COPIED_FILLED",
            "fill_source": "clob_book_evidence",
            "event_age_s": 4.0,
            "api_latency_s": 0.4,
        }

    tracker_state.write_text(
        json.dumps(
            {
                "kind": "wallet_copy_live_tracking_state",
                "paper_only": True,
                "live_orders_allowed": False,
                "config": {"admission_mode": True},
                "summary": {
                    "wallets": 1,
                    "wallet_reports": [{"wallet": "0xaaa"}],
                    "mirror_coverage_status": "PASS",
                    "mirror_required_events": 1,
                    "mirrored_events": 1,
                    "tracker_scope": {"tracked_wallets": [{"address": wallet}]},
                    "wallet_reports": [{"wallet": wallet, "raw_rows": 2, "events_seen": 2, "new_events": 1}],
                    "copy_efficiency": {
                        "status": "PASS",
                        "blockers": [],
                        "summary": {
                            "source_buy_events": 1,
                            "required_buy_copy_events": 1,
                            "clob_filled_buy_copy_events": 1,
                            "fallback_filled_buy_copy_events": 0,
                            "rejected_buy_copy_events": 0,
                            "missed_buy_copy_events": 0,
                        },
                        "event_scores": [score("event_1", "btc-updown-5m-1700000000")],
                    },
                },
            }
        ),
        encoding="utf-8",
    )
    (tmp_path / "candidate_forward_events.jsonl").write_text(
        "\n".join(
            json.dumps(
                {
                    "event": "wallet_copy_live_tracked_move",
                    "action": "BUY",
                    "paper_only": True,
                    "live_orders_allowed": False,
                    "market_slug": row["market_slug"],
                    "source_event_id": row["source_event_id"],
                    "profit_policy_candidate_id": candidate_id,
                    "profit_policy_context_id": policy_id,
                    "copy_efficiency": row,
                }
            )
            for row in [
                score("event_1", "btc-updown-5m-1700000000"),
                score("event_2", "btc-updown-5m-1700000300"),
            ]
        )
        + "\n",
        encoding="utf-8",
    )

    truth = _live_tracker_truth(
        tracker_state,
        candidate_policy_id=policy_id,
        candidate_type="SINGLE_WALLET",
        candidate_metadata={
            "candidate_id": candidate_id,
            "source_wallet": wallet,
            "candidate_policy": {"policy_id": policy_id, "min_price": 0.01, "max_price": 1.0},
        },
    )
    candidate = {
        "candidate_id": candidate_id,
        "candidate_type": "SINGLE_WALLET",
        "metadata": {"source_wallet": wallet},
        "policy": {"policy_id": policy_id},
        "status": "BLOCKED",
        "blockers": ["candidate_missing_clob_fill_evidence"],
    }
    patched = _candidate_with_runtime_copy_evidence(
        candidate,
        truth,
        source="unit",
        min_required_buy_copy_events=2,
        min_required_market_windows=2,
    )

    assert truth["status"] == "PASS"
    assert truth["summary"]["candidate_copy_truth_summary"]["required_buy_copy_events"] == 2
    assert truth["summary"]["candidate_copy_truth_summary"]["clob_filled_buy_copy_events"] == 2
    assert patched["status"] == "PASS"
    assert patched["runtime_copy_evidence"]["runtime_candidate_distinct_market_windows"] == 2
    assert "candidate_missing_clob_fill_evidence" not in patched["blockers"]


