def test_runtime_proof_index_extracts_clean_tracker_state_candidate_rows(tmp_path: Path):
    candidate_id = "candidate_not_in_forward_queue"
    policy_id = "fast_policy"
    wallet = "0xabc1230000000000000000000000000000000000"
    dirty_candidate_id = "candidate_dirty_group"
    tracker_state = tmp_path / "tracker_state.json"

    def score(
        source_event_id: str,
        market_slug: str,
        *,
        candidate: str = candidate_id,
        fill_source: str = "clob_book_evidence",
        copy_status: str = "COPIED_FILLED",
    ) -> dict:
        return {
            "candidate_id": candidate,
            "profit_policy_candidate_id": candidate,
            "policy_id": policy_id,
            "profit_policy_id": policy_id,
            "source_event_id": source_event_id,
            "source_wallet": wallet,
            "wallet_action": "BUY",
            "market_slug": market_slug,
            "token_id": f"token-{source_event_id}",
            "book_hash": f"book-{source_event_id}",
            "copy_status": copy_status,
            "fill_source": fill_source,
            "event_age_s": 3.0,
            "api_latency_s": 0.25,
        }

    tracker_state.write_text(
        json.dumps(
            {
                "kind": "wallet_copy_live_tracking_state",
                "paper_only": True,
                "live_orders_allowed": False,
                "summary": {
                    "copy_efficiency": {
                        "event_scores": [
                            score("event_1", "btc-updown-5m-1700000000"),
                            score("event_2", "btc-updown-5m-1700000300"),
                            score("dirty_clean", "btc-updown-5m-1700000600", candidate=dirty_candidate_id),
                            score(
                                "dirty_fallback",
                                "btc-updown-5m-1700000600",
                                candidate=dirty_candidate_id,
                                fill_source="source_price_plus_slippage_fallback",
                            ),
                        ]
                    }
                },
            }
        ),
        encoding="utf-8",
    )

    proof_rows = _runtime_proof_rows_from_tracker_state(tracker_state, source="runtime_tracker_state")
    assert {row["candidate_id"] for row in proof_rows} == {candidate_id}
    assert len(proof_rows) == 2
    assert all(row["source"] == "runtime_tracker_state" for row in proof_rows)

    candidate = {
        "candidate_id": candidate_id,
        "candidate_type": "SINGLE_WALLET",
        "metadata": {"source_wallet": wallet},
        "policy": {"policy_id": policy_id},
        "status": "BLOCKED",
        "blockers": ["candidate_missing_clob_fill_evidence"],
    }
    patched = _candidate_with_runtime_copy_evidence(
        candidate,
        {"status": "BLOCKED", "summary": {}, "event_scores": []},
        source="unit",
        min_required_buy_copy_events=2,
        min_required_market_windows=2,
        proof_index_rows=proof_rows,
    )

    assert patched["status"] == "PASS"
    assert patched["runtime_copy_evidence"]["runtime_proof_index_rows"] == 2
    assert patched["runtime_copy_evidence"]["runtime_proof_index_sources"] == ["runtime_tracker_state"]
    assert patched["runtime_copy_evidence"]["runtime_candidate_distinct_market_windows"] == 2
    assert (
        patched["runtime_copy_evidence"].get(
            "runtime_candidate_persisted_proof_used_without_current_tracker_pass"
        )
        is None
    )
    assert "candidate_missing_clob_fill_evidence" not in patched["blockers"]


