def test_forward_policy_feedback_counts_timing_and_price_compatibility():
    rows = [
        {
            "source_wallet": "0xbbb",
            "wallet_action": "BUY",
            "market_slug": "btc-updown-5m-1700000000",
            "source_event_ts": 1_700_000_045,
            "source_price": 0.72,
            "source_usdc_size": 8.0,
            "event_age_s": 4.0,
            "copyability_reason": "accepted",
            "copyability_accepted": True,
        },
        {
            "source_wallet": "0xbbb",
            "wallet_action": "BUY",
            "market_slug": "btc-updown-5m-1700000000",
            "source_event_ts": 1_700_000_210,
            "source_price": 0.31,
            "source_usdc_size": 8.0,
            "event_age_s": 5.0,
            "copyability_reason": "best_ask_above_slippage_cap",
            "copyability_accepted": False,
        },
    ]
    all_window = {
        "metadata": {"source_wallet": "0xbbb"},
        "policy": {"policy_id": "all", "min_price": 0.01, "max_price": 1.0},
    }
    late_high = {
        "metadata": {"source_wallet": "0xbbb"},
        "policy": {
            "policy_id": "late_high",
            "min_price": 0.55,
            "max_price": 1.0,
            "min_seconds_from_open": 180.0,
            "max_seconds_from_open": 300.0,
        },
    }

    all_feedback = _recent_price_compatibility(all_window, rows)
    late_feedback = _recent_price_compatibility(late_high, rows)

    assert all_feedback["recent_policy_compatible_buy_events"] == 2
    assert all_feedback["recent_policy_compatible_fresh_buy_events_le_10s"] == 2
    assert all_feedback["recent_policy_and_copyability_accepted_buy_events"] == 1
    assert all_feedback["recent_policy_copyability_rejected_buy_events"] == 1
    assert all_feedback["recent_policy_copyability_rejection_reasons"] == {
        "best_ask_above_slippage_cap": 1,
    }
    assert late_feedback["recent_price_compatible_buy_events"] == 1
    assert late_feedback["recent_policy_compatible_buy_events"] == 0
    assert late_feedback["recent_policy_rejection_reasons"] == {
        "before_timing_band": 1,
        "price_outside_policy": 1,
    }


