def test_hotlane_runtime_proof_score_requires_passed_runtime_candidate(tmp_path: Path):
    from src.wallet_copy.hotlane import _profit_wallet_scores

    profit_state = tmp_path / "profit.json"
    profit_state.write_text(
        json.dumps(
            {
                "forward_queue_runtime_candidates": [
                    {
                        "candidate_id": "blocked_runtime",
                        "status": "BLOCKED",
                        "metadata": {"source_wallet": "0xblocked"},
                        "runtime_copy_evidence": {
                            "runtime_candidate_distinct_source_events": 10,
                        },
                    },
                    {
                        "candidate_id": "passed_runtime",
                        "status": "PASS",
                        "metadata": {"source_wallet": "0xpassed"},
                        "runtime_copy_evidence": {
                            "runtime_candidate_distinct_source_events": 10,
                        },
                    },
                ]
            }
        ),
        encoding="utf-8",
    )

    scores = _profit_wallet_scores(profit_state)

    assert scores["0xblocked"].get("runtime_copy_proof_score", 0.0) == 0.0
    assert scores["0xblocked"]["runtime_copy_partial_score"] > 0.0
    assert scores["0xpassed"]["runtime_copy_proof_score"] > 0.0
    assert scores["0xpassed"]["forward_queue_score"] > scores["0xblocked"].get("forward_queue_score", 0.0)


