def test_forward_tracking_queue_prefers_stronger_proof_led_event_count(tmp_path: Path):
    strong_policy = CandidatePolicy(
        policy_id="fast_wf_0.05_cap_2_all_prices_minusd_0_first_90s",
        min_price=0.01,
        max_price=1.0,
        max_seconds_from_open=90,
    )
    thin_policy = CandidatePolicy(
        policy_id="fast_wf_0.05_cap_2_late_high_conviction_minusd_0_middle_90s",
        min_price=0.55,
        max_price=1.0,
        min_seconds_from_open=90,
        max_seconds_from_open=180,
    )
    strong_wallet = "0x31393e2f8333d4a6e2e31ca6424defe8b6cb9e2e"
    thin_wallet = "0xeebde7a0e019a63e6b476eb425505b7b3e6eba30"
    strong_rows = [
        {
            "candidate_id": "wcp_strong_3139",
            "policy_id": strong_policy.policy_id,
            "source_wallet": strong_wallet,
            "source_event_id": f"strong_event_{index}",
            "market_slug": f"btc-updown-5m-{index % 3}",
            "event_age_s": 4.0 + index / 20.0,
            "copy_status": "COPIED_FILLED",
            "fill_source": "clob_book_evidence",
            "wallet_action": "BUY",
        }
        for index in range(13)
    ]
    thin_rows = [
        {
            "candidate_id": "wcp_thin_eebde7",
            "policy_id": thin_policy.policy_id,
            "source_wallet": thin_wallet,
            "source_event_id": f"thin_event_{index}",
            "market_slug": f"btc-updown-5m-{index % 4}",
            "event_age_s": 4.0 + index / 20.0,
            "copy_status": "COPIED_FILLED",
            "fill_source": "clob_book_evidence",
            "wallet_action": "BUY",
        }
        for index in range(6)
    ]

    queue = _forward_tracking_queue(
        [],
        cfg=ProfitEngineConfig(
            forward_tracking_queue_size=2,
            min_runtime_candidate_required_buy_copy_events=3,
            min_runtime_candidate_required_market_windows=2,
            active_hotlane_state_path=str(tmp_path / "missing_hotlane.json"),
            active_hotlane_live_tracker_state_path=str(tmp_path / "missing_active_tracker.json"),
            candidate_forward_live_tracker_state_path=str(tmp_path / "missing_candidate_forward.json"),
        ),
        proof_index_rows=[*thin_rows, *strong_rows],
        policies=[strong_policy, thin_policy],
    )

    assert [row["source_wallet"] for row in queue[:2]] == [strong_wallet, thin_wallet]
    assert queue[0]["candidate_id"] == "wcp_strong_3139"
    assert queue[0]["runtime_copy_proof"]["source_events"] == 13
    assert queue[0]["runtime_copy_proof"]["market_windows"] == 3
    assert queue[1]["runtime_copy_proof"]["source_events"] == 6
    assert queue[1]["runtime_copy_proof"]["market_windows"] == 4


def test_forward_candidate_configured_runtime_truth_can_clear_best_candidate_admission(tmp_path: Path):
    events = []
    resolution_lines = []
    for index, wallet in enumerate(["0xaaa"] * 8 + ["0xbbb"] * 6):
        window_start = 1_700_130_000 + index * 300
        events.append(
            wallet_event(
                wallet_name="stale" if wallet == "0xaaa" else "fresh",
                wallet=wallet,
                outcome="Up",
                condition=f"0xnonadmissionqueue{index}",
                price=0.2 if wallet == "0xaaa" else 0.45,
                size=10.0 if wallet == "0xaaa" else 5.0,
                window_start=window_start,
                timestamp=window_start + 30,
            )
        )
        resolution_lines.append({"expiry_unix_ts": window_start + 300, "direction": "UP", "source": "unit"})
    resolutions = tmp_path / "resolutions.jsonl"
    resolutions.write_text("\n".join(json.dumps(row) for row in resolution_lines) + "\n", encoding="utf-8")
    active_hotlane = tmp_path / "active_hotlane.json"
