    assert report["pass_candidates"] == []
    assert report["decision"]["runtime_admission_candidate_id"] == forward_candidate_id
    assert report["decision"]["live_tracker_truth_source"] in {"candidate_forward", "forward_candidate", "forward_queue_rank_0"}
    assert "no_profit_candidate_pass" not in report["decision"]["live_admission_blockers"]
    assert "profit_candidate_pass_depends_on_forward_runtime_clob_probe" not in report["decision"]["live_admission_blockers"]
    assert report["decision"]["live_admission_status"] == "PASS"
    assert report["decision"]["status"] == "PASS"
    assert report["decision"]["live_orders_allowed"] is False
    certificate = report["live_readiness_certificate"]
    assert certificate["status"] == "PROOF_READY"
    assert certificate["live_ready"] is True
    assert certificate["profitability_proven"] is True
    assert certificate["copy_truth"]["required_buy_copy_events"] == 12
    assert certificate["copy_truth"]["clob_filled_buy_copy_events"] == 12
    assert certificate["paper_results"]["resolved_orders"] >= 100


