def test_ranked_runtime_candidate_treats_development_bridge_as_advisory_when_live_target_passes():
    from src.wallet_copy.profit_engine import (
        _candidate_with_runtime_copy_evidence,
        _live_readiness_certificate,
        _runtime_admission_candidates,
    )

    candidate = {
        "candidate_id": "runtime-bridge-candidate",
        "candidate_type": "SINGLE_WALLET",
        "status": "BLOCKED",
        "source_wallet": "0xbridge",
        "policy": {"policy_id": "bridge_policy"},
        "blockers": [
            "candidate_missing_clob_fill_evidence",
            "development_program_bridge_pending_current_poll_inventory",
        ],
        "summary": {
            "resolved_orders": 120,
            "roi_pct": 8.0,
            "wr_pct": 78.0,
            "pnl_usd": 14.0,
            "window_metrics": {"unique_windows": 24, "avg_orders_per_window": 5.0},
        },
        "validation_summary": {"resolved_orders": 40, "roi_pct": 3.0, "wr_pct": 75.0},
        "live_target_profile": {"status": "PASS", "blockers": []},
    }
    proof_rows = [
        {
            "candidate_id": "runtime-bridge-candidate",
            "profit_policy_candidate_id": "runtime-bridge-candidate",
            "policy_id": "bridge_policy",
            "source_wallet": "0xbridge",
            "source_event_id": f"bridge-event-{index}",
            "market_slug": f"btc-updown-5m-170020{index % 4:02d}",
            "wallet_action": "BUY",
            "copy_status": "COPIED_FILLED",
            "fill_source": "clob_book_evidence",
        }
        for index in range(12)
    ]
    truth = {
        "status": "PASS",
        "summary": {
            "candidate_id": "runtime-bridge-candidate",
            "candidate_policy_id": "bridge_policy",
            "candidate_source_wallet": "0xbridge",
            "candidate_copy_truth_summary": {
                "required_buy_copy_events": 12,
                "clob_filled_buy_copy_events": 12,
                "fallback_filled_buy_copy_events": 0,
                "rejected_buy_copy_events": 0,
                "missed_buy_copy_events": 0,
            },
        },
        "event_scores": proof_rows,
    }

    patched = _candidate_with_runtime_copy_evidence(candidate, truth, source="candidate_forward")
    assert patched is not None
    assert patched["status"] == "PASS"
    assert patched["blockers"] == []
    assert set(patched["runtime_copy_evidence_resolved_blockers"]) == {
        "candidate_missing_clob_fill_evidence",
        "development_program_bridge_pending_current_poll_inventory",
    }
    assert _runtime_admission_candidates([patched]) == [patched]

    certificate = _live_readiness_certificate(
        decision={
            "status": "PASS",
            "live_admission_status": "PASS",
            "runtime_admission_candidate_id": "runtime-bridge-candidate",
            "live_admission_blockers": [],
            "live_tracker_truth_source": "candidate_forward",
        },
        best_candidate=None,
        forward_candidate=patched,
        pass_candidates=[],
        effective_live_truth={"status": "PASS", "summary": {}},
        resolution_contract={"research_only_count": 0},
        wallet_search_summary={},
        skipped_candidate_counts={},
    )

    assert certificate["live_ready"] is True
    assert "development_program_bridge_pending_current_poll_inventory" not in certificate["blockers"]


