def test_live_readiness_certificate_uses_runtime_copy_evidence_without_clearing_profit_blocks():
    from src.wallet_copy.profit_engine import _live_readiness_certificate

    certificate = _live_readiness_certificate(
        decision={
            "status": "CORRECTION",
            "live_tracker_truth_source": "canonical",
            "live_admission_blockers": ["live_tracker_truth_not_pass", "no_profit_candidate_pass"],
        },
        best_candidate=None,
        forward_candidate={
            "candidate_id": "proof_candidate",
            "candidate_type": "SINGLE_WALLET",
            "status": "BLOCKED",
            "source_wallet": "0xaaa",
            "policy": {"policy_id": "proof_policy"},
            "blockers": ["insufficient_all_resolved", "all_wr_below_minimum"],
            "summary": {"resolved_orders": 0, "roi_pct": 0.0, "wr_pct": 0.0, "pnl_usd": 0.0},
            "validation_summary": {"resolved_orders": 0, "roi_pct": 0.0, "wr_pct": 0.0},
            "runtime_copy_evidence": {
                "required_buy_copy_events": 13,
                "clob_filled_buy_copy_events": 13,
                "fallback_filled_buy_copy_events": 0,
                "rejected_buy_copy_events": 0,
                "missed_buy_copy_events": 0,
                "required_event_age_p95_s": 7.5,
                "runtime_proof_index_rows": 13,
                "runtime_proof_total_rows": 13,
            },
        },
        pass_candidates=[],
        effective_live_truth={"status": "BLOCKED", "summary": {}},
        resolution_contract={"research_only_count": 0},
        wallet_search_summary={},
        skipped_candidate_counts={},
    )

    assert certificate["live_ready"] is False
    assert certificate["copy_truth"]["candidate_specific_copy_truth_source"] == "runtime_copy_evidence"
