    assert certificate["copy_truth"]["clob_filled_buy_copy_events"] == 13
    assert "no_required_clob_backed_buy_copy_evidence" not in certificate["blockers"]
    assert "profit_engine_decision_not_pass" in certificate["blockers"]
    assert "no_profit_candidate_pass" in certificate["blockers"]


