def test_profit_engine_blocks_thin_filtered_pass_when_raw_baseline_negative(tmp_path: Path):
    events = []
    resolution_lines = []
    for index in range(40):
        window_start = 1_700_200_000 + index * 300
        high_price = index < 10
        outcome = "Up"
        price = 0.6 if high_price else 0.4
        direction = "UP" if high_price else "DOWN"
        events.append(
            wallet_event(
                wallet_name="alpha",
                wallet="0xaaa",
                outcome=outcome,
                condition=f"0xrawloss{index}",
                price=price,
                size=10.0,
                window_start=window_start,
                timestamp=window_start + 60,
            )
        )
        resolution_lines.append(
            {
                "expiry_unix_ts": window_start + 300,
                "direction": direction,
                "source": "unit",
            }
        )
    resolutions = tmp_path / "resolutions.jsonl"
    resolutions.write_text("\n".join(json.dumps(row) for row in resolution_lines) + "\n", encoding="utf-8")

    report = evaluate_profit_candidates(
        events,
        resolutions_path=resolutions,
        config=ProfitEngineConfig(
            min_train_resolved=5,
            min_validation_resolved=2,
            min_all_resolved=8,
            min_roi_pct=1.0,
            min_wr_pct=50.0,
            max_drawdown_usd=20.0,
            max_unresolved_ratio=0.1,
            slippage_bps=0.0,
            max_candidates=10,
            min_raw_baseline_resolved=30,
            min_filtered_resolved_when_raw_negative=20,
            min_candidate_vs_raw_delta_roi_pct=5.0,
        ),
        policies=[
            CandidatePolicy(
                policy_id="thin_high_price_winner_filter",
                min_price=0.55,
                max_price=1.0,
                wallet_fraction=0.1,
                max_order_usd=1.0,
            )
        ],
    )

    assert report["decision"]["status"] == "ANALYZE"
    assert report["best_candidate"]["summary"]["resolved_orders"] == 10
    assert report["best_candidate"]["raw_baseline_summary"]["roi_pct"] < 0
    assert "raw_baseline_negative_candidate_sample_too_thin" in report["best_candidate"]["blockers"]


