def test_runtime_log_rotation_truncates_verbose_guard_without_touching_jsonl(tmp_path: Path):
    from scripts.rotate_wallet_copy_runtime_logs import rotate_log

    log_path = tmp_path / "guard.out"
    state_path = tmp_path / "rotation_state.json"
    event_log_path = tmp_path / "rotation_events.jsonl"
    log_path.write_bytes(b"a" * 64 + b"tail-marker")

    payload = rotate_log(
        log_path=log_path,
        state_path=state_path,
        event_log_path=event_log_path,
        max_bytes=32,
        keep_tail_bytes=16,
    )

    assert payload["status"] == "REPAIRED"
    assert payload["paper_only"] is True
    assert payload["live_orders_allowed"] is False
    assert log_path.read_bytes().endswith(b"tail-marker")
    assert log_path.stat().st_size == 16
    assert json.loads(state_path.read_text(encoding="utf-8"))["action"] == "copytruncate_tail"
    assert len(event_log_path.read_text(encoding="utf-8").splitlines()) == 1


