def test_pipeline_resume_slice_completion_uses_only_current_run_reports():
    from scripts.run_wallet_copy_pipeline_resume import _matching_report_count, _slice_completion

    history_state = {
        "ingest": {
            "wallet_reports": [
                {"last_offset": 0, "normalized_events": 10, "blockers": ["history_page_limit_reached"]},
                {"last_offset": 0, "normalized_events": 11, "blockers": ["history_page_limit_reached"]},
                {"last_offset": 0, "normalized_events": 12, "blockers": []},
                {"last_offset": 0, "normalized_events": 13, "blockers": ["history_page_limit_reached"]},
            ]
        }
    }

    assert _matching_report_count(history_state, 0) == 4
    assert _matching_report_count(history_state, 500) == 0

    completion = _slice_completion(history_state, 0, current_wallet_count=2)

    assert completion["wallet_reports"] == 2
    assert completion["matching_wallet_reports_total"] == 4
    assert completion["normalized_events"] == 25
    assert completion["page_limit_wallets"] == 1
    assert completion["coverage_complete_hint"] is False

    timeout_completion = _slice_completion(history_state, 0, current_wallet_count=0)
    assert timeout_completion["wallet_reports"] == 0
    assert timeout_completion["matching_wallet_reports_total"] == 4
    assert timeout_completion["normalized_events"] == 0
    assert timeout_completion["coverage_complete_hint"] is False


def test_pipeline_resume_can_report_persisted_partial_timeout_progress():
    from scripts.run_wallet_copy_pipeline_resume import _matching_report_count, _slice_completion

    before = {
        "ingest": {
            "wallet_reports": [
                {"last_offset": 1500, "normalized_events": 4, "blockers": ["history_page_limit_reached"]},
                {"last_offset": 1500, "normalized_events": 5, "blockers": ["history_page_limit_reached"]},
            ]
        }
    }
    after = {
        "ingest": {
            "wallet_reports": [
                *before["ingest"]["wallet_reports"],
                {"last_offset": 1500, "normalized_events": 10, "blockers": ["history_page_limit_reached"]},
                {"last_offset": 1500, "normalized_events": 11, "blockers": []},
                {"last_offset": 2000, "normalized_events": 99, "blockers": []},
            ]
        }
    }

    persisted_wallet_count = _matching_report_count(after, 1500) - _matching_report_count(before, 1500)
    completion = _slice_completion(after, 1500, current_wallet_count=persisted_wallet_count)

    assert persisted_wallet_count == 2
    assert completion["wallet_reports"] == 2
    assert completion["matching_wallet_reports_total"] == 4
    assert completion["normalized_events"] == 21
    assert completion["page_limit_wallets"] == 1
    assert completion["coverage_complete_hint"] is False


def test_pipeline_resume_registry_batches_checkpoint_each_wallet(tmp_path: Path, monkeypatch):
    from scripts import run_wallet_copy_pipeline_resume as mod

    wallets_config = tmp_path / "wallets.json"
    wallets_config.write_text(
        json.dumps(
            {
                "wallets": [
                    {"name": "wallet_a", "address": "0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"},
                    {"name": "wallet_b", "address": "0xbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"},
                    {"name": "wallet_c", "address": "0xcccccccccccccccccccccccccccccccccccccccc"},
                ]
            }
        ),
        encoding="utf-8",
    )
    history_state = tmp_path / "history.json"
    paper_state = tmp_path / "paper.json"

    class Result:
        returncode = 0
        stderr = ""

        def __init__(self, wallet_count: int):
            self.stdout = json.dumps({"wallet_results": [{} for _ in range(wallet_count)]})

    def fake_run_child(argv, *, timeout_s):
        batch_config = Path(argv[argv.index("--wallets-config") + 1])
        batch = json.loads(batch_config.read_text(encoding="utf-8"))["wallets"]
        offset = int(argv[argv.index("--offset") + 1])
        payload = json.loads(history_state.read_text(encoding="utf-8")) if history_state.exists() else {}
        ingest = payload.setdefault("ingest", {})
        reports = ingest.setdefault("wallet_reports", [])
        for row in batch:
            reports.append(
                {
                    "wallet": row["address"].lower(),
                    "wallet_name": row["name"],
                    "last_offset": offset,
                    "normalized_events": 1,
                    "blockers": [],
                }
            )
        history_state.write_text(json.dumps(payload), encoding="utf-8")
        paper_state.write_text(json.dumps({"kind": "wallet_copy_paper_state", "paper_only": True}), encoding="utf-8")
        return Result(len(batch))

    monkeypatch.setattr(mod, "_run_child", fake_run_child)
    args = SimpleNamespace(
        wallets_config=str(wallets_config),
        wallet_batch_size=1,
        checkpoint_reserve_s=15.0,
        min_child_timeout_s=10.0,
        history_state=str(history_state),
        wallet_event_log=str(tmp_path / "events.jsonl"),
        paper_state=str(paper_state),
        paper_event_log=str(tmp_path / "paper_events.jsonl"),
        wallet_fraction=0.05,
        max_order_usd=2.0,
        policy_id="leaderboard_crypto_exact_copy_all_buys",
    )

    result, child_results, wallet_index, wallet_count, stopped = mod._run_registry_batches(
        args,
        limit=25,
        pages=1,
        offset=0,
        timeout_s=120.0,
        start_wallet_index=0,
    )

    reports = json.loads(history_state.read_text(encoding="utf-8"))["ingest"]["wallet_reports"]
    assert result.returncode == 0
    assert wallet_index == 3
    assert wallet_count == 3
    assert stopped is False
    assert len(child_results) == 3
    assert [row["wallet_index_start"] for row in child_results] == [0, 1, 2]
    assert [row["wallet_name"] for row in reports] == ["wallet_a", "wallet_b", "wallet_c"]


