def test_autonomous_repair_backlog_normalizes_stale_active_forward_probe_command(tmp_path: Path):
    from scripts.run_wallet_copy_autonomous_repair import _write_backlog

    stale_command = (
        "python3 scripts/run_wallet_live_tracker.py "
        "--state data/research/wallet_copy_active_forward_probe_live_tracking_state.json "
        "--profit-policy-state data/research/wallet_copy_active_forward_probe_profit_state.json "
        "--admission-mode --strict-mirror-coverage --use-profit-search-scope "
        "--iterations 20 --poll-interval-s 0.5 --max-runtime-s 60 "
        "--enable-clob-books --max-wallets 1"
    )
    backlog_state = tmp_path / "backlog.json"
    backlog_log = tmp_path / "backlog.jsonl"
    backlog_state.write_text(
        json.dumps(
            {
                "items": [
                    {
                        "area": "active forward candidate probe",
                        "file": "scripts/select_wallet_copy_active_forward_probe.py",
                        "function": "select_active_forward_probe plus scripts/run_wallet_live_tracker.py main",
                        "action": "measure active forward candidate",
                        "verify": stale_command,
                        "next_command": stale_command,
                        "status": "OPEN",
                    }
                ]
            }
        ),
        encoding="utf-8",
    )

    _write_backlog(
        {"next_actions": [], "feedback_loop": {"non_green_checks": []}},
        SimpleNamespace(backlog_state=str(backlog_state), backlog_log=str(backlog_log)),
    )

    item = json.loads(backlog_state.read_text(encoding="utf-8"))["items"][0]
    assert "--no-use-profit-search-scope" in item["next_command"]
    assert "--use-profit-search-scope" not in item["next_command"]
    assert "--iterations 1" in item["next_command"]
    assert "--iterations 20" not in item["next_command"]
    assert "--max-runtime-s 180" in item["next_command"]
    assert "--max-runtime-s 60" not in item["next_command"]
    assert "--max-poll-runtime-s 120" in item["next_command"]
    assert "--profit-policy-candidate-only" in item["next_command"]
    assert "--parallel-data-api-sources" in item["next_command"]
    assert "--max-wallets 4" in item["next_command"]
    assert "--parallel-wallet-fetches 4" in item["next_command"]
    assert item["verify"] == item["next_command"]


