def test_source_route_probe_progress_pauses_heavy_guards(tmp_path: Path):
    from scripts.run_active_hotlane_clob_ws_guard import _source_route_blocked as clob_ws_blocked
    from scripts.run_wallet_copy_candidate_forward_guard import _source_route_status as candidate_source_route_status
    from scripts.run_wallet_copy_hotlane_tick import _source_route_blocked_state as hotlane_blocked_state
    from src.wallet_copy.source_route import source_route_probe_progress_blocker

    source_route_state = tmp_path / "source_route.json"
    source_route_state.write_text(
        json.dumps(
            {
                "status": "POLYMARKET_ROUTE_RECOVERED_DEGRADED",
                "paper_only": True,
                "live_orders_allowed": False,
                "route_class_counts": {"ROUTE_RECOVERED_DEGRADED": 4, "DIRECT_PASS": 1},
            }
        ),
        encoding="utf-8",
    )
    progress_state = tmp_path / "repair_progress.json"
    progress_state.write_text(
        json.dumps(
            {
                "status": "RUNNING",
                "name": "source_route_probe",
                "pid": 0,
                "generated_at": "2026-06-28T00:00:00+00:00",
            }
        ),
        encoding="utf-8",
    )

    blocker = source_route_probe_progress_blocker(progress_state)
    assert blocker is not None
    assert blocker["status"] == "SOURCE_ROUTE_PROBE_RUNNING"

    candidate = candidate_source_route_status(source_route_state, progress_state=progress_state)
    assert candidate["status"] == "SOURCE_ROUTE_PROBE_RUNNING"
    assert candidate["blockers"] == ["source_route_probe_running"]

    hotlane = hotlane_blocked_state(
        SimpleNamespace(
            source_route_state=str(source_route_state),
            autonomous_repair_command_progress_state=str(progress_state),
            active_hotlane_state=str(tmp_path / "missing_active_hotlane.json"),
            exact_cohort_probe=False,
            cohort_probe_max_wallets=2,
            ticks=1,
        )
    )
    assert hotlane is not None
    assert hotlane["status"] == "SOURCE_ROUTE_BLOCKED_SLEEP"
    assert hotlane["summary"]["source_route_status"] == "SOURCE_ROUTE_PROBE_RUNNING"

    clob = clob_ws_blocked(
        SimpleNamespace(
            source_route_state=str(source_route_state),
            autonomous_repair_command_progress_state=str(progress_state),
        )
    )
    assert clob is not None
    assert clob["source_route_status"] == "SOURCE_ROUTE_PROBE_RUNNING"


