def test_autonomous_repair_single_instance_lock_blocks_duplicate_run(tmp_path: Path):
    from scripts.run_wallet_copy_autonomous_repair import (
        _acquire_single_instance_lock,
        _release_single_instance_lock,
    )

    lock_file = tmp_path / "wallet_copy_autonomous_repair.lock"
    first_handle, first_acquired, first_holder = _acquire_single_instance_lock(str(lock_file))
    assert first_acquired is True
    assert first_holder["pid"] > 0

    second_handle, second_acquired, second_holder = _acquire_single_instance_lock(str(lock_file))
    assert second_acquired is False
    assert second_holder["pid"] == first_holder["pid"]
    second_handle.close()

    _release_single_instance_lock(first_handle)
    third_handle, third_acquired, _third_holder = _acquire_single_instance_lock(str(lock_file))
    assert third_acquired is True
    _release_single_instance_lock(third_handle)


