def test_candidate_forward_route_blocked_ranks_become_resumable_slice(tmp_path):
    from scripts.run_wallet_copy_autonomous_repair import (
        _candidate_forward_tracker_commands,
        _route_blocked_candidate_forward_skip_results,
    )

    profit_state = tmp_path / "profit.json"
    source_route_state = tmp_path / "source_route.json"
    queue = [
        {
            "candidate_id": f"candidate-{rank}",
            "source_wallet": f"0x{rank:040x}",
            "policy_id": "fast_wf_0.05",
            "candidate_type": "SINGLE_WALLET",
            "forward_queue_rank": rank,
        }
        for rank in range(3)
    ]
    profit_state.write_text(json.dumps({"forward_tracking_queue": queue}))
    source_route = {
        "status": "POLYMARKET_ROUTE_RESET",
        "paper_only": True,
        "live_orders_allowed": False,
        "route_class_counts": {"DIRECT_RESET": 4},
        "source_proxy_configured": False,
        "external_route_required": True,
    }
    source_route_state.write_text(json.dumps(source_route))
    args = SimpleNamespace(
        registry="configs/wallet_copy/wallets.json",
        profit_state=str(profit_state),
        source_route_state=str(source_route_state),
        history_state="data/research/wallet_copy_history_state.json",
        candidate_forward_probe_ranks=3,
        candidate_forward_probe_iterations=1,
        candidate_forward_probe_max_runtime_s=45.0,
        candidate_forward_probe_max_poll_runtime_s=12.0,
        live_tracker_max_runtime_s=120.0,
        command_timeout_s=240.0,
        live_tracker_limit=5,
        live_tracker_pages=1,
        data_api_timeout_s=2.0,
        live_tracker_poll_interval_s=0.5,
        clob_timeout_s=1.0,
        gamma_timeout_s=1.0,
        market_ws_jsonl=str(tmp_path / "ws.jsonl"),
        onchain_timeout_s=1.0,
    )

    commands = _candidate_forward_tracker_commands(args)
    skipped = _route_blocked_candidate_forward_skip_results(args, commands, source_route)

    assert [command["queue_rank"] for command in commands] == [0, 1, 2]
    assert [row["queue_rank"] for row in skipped] == [1, 2]
    assert all(row["ok"] for row in skipped)
    assert all(row["returncode"] == 2 for row in skipped)
    assert all(row["skip_reason"] == "SOURCE_ROUTE_BLOCKED_RESUMABLE_SLICE" for row in skipped)
    assert all(row["paper_only"] is True and row["live_orders_allowed"] is False for row in skipped)
    assert skipped[0]["source_route_status"] == "POLYMARKET_ROUTE_RESET"
    assert skipped[0]["route_class_counts"] == {"DIRECT_RESET": 4}
    assert "probe_polymarket_source_routes.py" in skipped[0]["next_command"]


