def test_candidate_forward_guard_uses_guard_specific_command_progress(tmp_path, monkeypatch):
    import scripts.run_wallet_copy_candidate_forward_guard as guard

    source_route_state = tmp_path / "source_route.json"
    profit_state = tmp_path / "profit.json"
    command_progress_state = tmp_path / "guard_progress.json"
    source_route_state.write_text(
        json.dumps(
            {
                "status": "POLYMARKET_ROUTE_RECOVERED_DEGRADED",
                "paper_only": True,
                "live_orders_allowed": False,
            }
        )
    )
    profit_state.write_text(json.dumps({"paper_only": True, "live_orders_allowed": False}))
    monkeypatch.setattr(
        guard,
        "_cycle_commands",
        lambda args: [
            {
                "name": "guard_probe",
                "purpose": "prove guard progress isolation",
                "argv": ["python3", "-c", "pass"],
                "acceptable_returncodes": (0,),
            }
        ],
    )
    captured: dict[str, object] = {}

    def fake_run_command(name, purpose, argv, **kwargs):
        captured.update(kwargs)
        return {"name": name, "ok": True, "returncode": 0}

    monkeypatch.setattr(guard, "_run_command", fake_run_command)

    result = guard.run_cycle(
        SimpleNamespace(
            source_route_state=str(source_route_state),
            profit_state=str(profit_state),
            command_timeout_s=12.0,
            command_progress_state=str(command_progress_state),
        ),
        1,
    )

    assert result["command_results"] == [{"name": "guard_probe", "ok": True, "returncode": 0}]
    assert captured["timeout_s"] == 12.0
    assert captured["progress_state"] == command_progress_state
    assert captured["progress_kind"] == "wallet_copy_candidate_forward_guard_command_progress"


