    assert payload["summary"]["adaptive_children_started"] == 0
    assert payload["source_route"]["status"] == "POLYMARKET_ROUTE_RESET"
    assert payload["ticks"] == []
    assert payload["summary"]["blocked_cohort_probe_preview_status"] == "PASS"
    assert payload["summary"]["blocked_cohort_probe_preview_wallets"] == 2
    assert payload["blocked_cohort_probe_preview"]["candidate_id"] == "wcp_route_blocked"
