def test_gamma_resolution_refresh_clears_source_base_overrides(monkeypatch):
    from scripts.refresh_btc_5m_resolutions_from_gamma import (
        _canonical_gamma_source_route_guard,
        _restore_source_route_env,
    )

    monkeypatch.setenv("POLYMARKET_GAMMA_API_BASE_URL", "http://127.0.0.1:8787/gamma-api")
    monkeypatch.setenv("POLYMARKET_SOURCE_PROXY_URL", "http://127.0.0.1:8787/proxy")

    guard, prior_values = _canonical_gamma_source_route_guard(
        SimpleNamespace(allow_source_base_overrides=False)
    )

    assert guard["enabled"] is True
    assert guard["allow_source_base_overrides"] is False
    assert guard["cleared_env_vars"] == ["POLYMARKET_GAMMA_API_BASE_URL", "POLYMARKET_SOURCE_PROXY_URL"]
    assert "POLYMARKET_GAMMA_API_BASE_URL" not in os.environ
    assert "POLYMARKET_SOURCE_PROXY_URL" not in os.environ

    _restore_source_route_env(prior_values)

    assert os.environ["POLYMARKET_GAMMA_API_BASE_URL"] == "http://127.0.0.1:8787/gamma-api"
    assert os.environ["POLYMARKET_SOURCE_PROXY_URL"] == "http://127.0.0.1:8787/proxy"


