    assert report["candidate_forward_rank_paper_results"][0]["all_order_exact_copy"]["rejected_buy_copy_events"] == 2
    assert report["candidate_forward_rank_paper_results"][0]["all_order_tactic_replay"]["status"] == "PASS"
    assert report["candidate_forward_rank_paper_results"][0]["all_order_tactic_replay"]["filled_orders"] == 3
    assert report["candidate_forward_rank_paper_results"][1]["rank"] == 1
    assert report["candidate_forward_rank_paper_results"][1]["candidate_id"] == "candidate_1"
    assert report["candidate_forward_rank_paper_results"][1]["source_wallet"] == "0xfresh"
    assert report["candidate_forward_rank_paper_results"][1]["blockers"] == ["no_required_buy_copy_evidence"]
    assert report["live_connection_plan"]["mode"] == "CORRECTION_UNTIL_PROFIT_AND_RUNTIME_PROOF"
    gap = report["paper_to_live_gap"]
    assert gap["status"] == "CORRECTION"
    assert gap["candidate_alignment"] == {
        "profit_candidate_id": "replay_profit_candidate",
        "runtime_copy_candidate_id": "candidate_1",
        "same_candidate": False,
    }
