    assert "profitable_candidate_research_only_resolution" in gap["reason_codes"]
    assert "profitable_candidate_misses_live_targets" in gap["reason_codes"]
    assert "profit_candidate_and_runtime_copy_candidate_are_different" in gap["reason_codes"]
    assert "candidate_forward_strict_copy_rejects_have_measured_tactic_fill" in gap["reason_codes"]
    assert "no_single_candidate_passes_profit_and_live_copy_gates" in gap["reason_codes"]
    assert gap["profitable_replay_candidate"]["fill_evidence"]["candidate_fallback_filled_orders"] == 66
    assert gap["runtime_copy_candidate"]["copy_truth"]["clob_filled_buy_copy_events"] == 3
    assert gap["runtime_copy_candidate"]["candidate_forward_top_rank_tactic_replay"]["filled_orders"] == 3
    backlog_actions = _candidate_forward_tactic_backlog_actions(report)
    assert backlog_actions[0]["area"] == "candidate-forward aggressive copy policy validation"
    assert backlog_actions[0]["severity"] == "P1"
    assert "live_readiness_report.paper_to_live_gap" in backlog_actions[0]["verify"]


