def test_clob_market_ws_capture_retries_local_ca_certificate_failure(tmp_path: Path):
    import ssl

    from scripts.run_clob_market_ws_capture import _connect_market_ws

    class FakeWebSocketModule:
        def __init__(self) -> None:
            self.calls: list[dict[str, object]] = []

        def create_connection(self, url: str, timeout: int = 10, **kwargs: object) -> object:
            self.calls.append({"url": url, "timeout": timeout, "kwargs": kwargs})
            if len(self.calls) == 1:
                raise ssl.SSLCertVerificationError("certificate verify failed")
            return object()

    output = tmp_path / "market_ws.jsonl"
    fake = FakeWebSocketModule()

    ws, mode = _connect_market_ws(
        fake,
        url="wss://example.test/ws/market",
        output=str(output),
        ssl_no_verify=False,
        ssl_no_verify_fallback=True,
    )

    assert ws is not None
    assert mode == "ssl_no_verify_fallback"
    assert len(fake.calls) == 2
    assert fake.calls[0]["kwargs"] == {}
    assert fake.calls[1]["kwargs"] == {"sslopt": {"cert_reqs": ssl.CERT_NONE, "check_hostname": False}}
    rows = [json.loads(line) for line in output.read_text(encoding="utf-8").splitlines()]
    assert rows[-1]["event"] == "clob_market_ws_connection"
    assert rows[-1]["ssl_mode"] == "ssl_no_verify_fallback"
    assert rows[-1]["fallback_errors"][0]["error_type"] == "SSLCertVerificationError"


