def test_profit_engine_applies_development_program_bridge_to_forward_queue(tmp_path: Path):
    from src.wallet_copy.profit_engine import (
        _apply_development_program_bridge_to_forward_queue,
        _development_program_bridge_context,
    )

    profit_wallet = "0xeebde7a0e019a63e6b476eb425505b7b3e6eba30"
    proof_wallet = "0x31393e2f8333d4a6e2e31ca6424defe8b6cb9e2e"
    inventory_child_wallet = "0x9412cdfc1e3171e1aabb013d0f494986445d0cd0"
    ranked_candidates = [
        {
            "candidate_id": "inventory_candidate",
            "candidate_type": "MULTI_WALLET_INVENTORY",
            "status": "BLOCKED",
            "blockers": ["candidate_missing_clob_fill_evidence"],
            "policy": {"policy_id": "fast_inventory"},
            "summary": {
                "resolved_orders": 14,
                "wr_pct": 85.714286,
                "roi_pct": 27.83249,
                "pnl_usd": 7.5,
                "window_metrics": {"avg_orders_per_window": 1.0},
            },
            "fill_evidence_summary": {
                "clob_book_filled_buy_count": 0,
                "fallback_filled_buy_count": 14,
            },
            "metadata": {
                "base_intents": 100,
                "plans": 14,
                "inventory_profile": {
                    "top_source_wallets": [
                        {"wallet": inventory_child_wallet, "orders": 8},
                        {"wallet": proof_wallet, "orders": 6},
                    ]
                },
            },
        }
    ]
    bridge_actions = (
        "build_current_poll_inventory_bridge_from_profitable_single_wallet_and_weighted_inventory_candidate",
        "rebuild_scaled_multi_wallet_inventory_from_full_per_wallet_copy_universe",
    )
    for index, next_major_change_action in enumerate(bridge_actions):
        strategy_state = tmp_path / f"strategy_direction_{index}.json"
        strategy_state.write_text(
            json.dumps(
                {
                    "development_program_review": {
                        "full_rethink_required": True,
                        "next_major_change_action": next_major_change_action,
                        "stop_doing": ["do_not_spend_primary_cycles_proving_the_same_single_wallet_again"],
                        "strategic_traps": ["single_wallet_proof_not_promoted_to_multi_wallet_inventory"],
                    },
                    "directions": [
                        {"id": "profitable_wallet_copy_efficiency", "wallet": profit_wallet},
                        {"id": "single_wallet_best_copyable", "wallet": proof_wallet},
                    ],
                }
            ),
            encoding="utf-8",
        )

        context = _development_program_bridge_context(strategy_state, ranked_candidates)
        patched = _apply_development_program_bridge_to_forward_queue(
            [
                {"source_wallet": proof_wallet, "blockers": [], "candidate_id": "proof_candidate"},
                {"source_wallet": profit_wallet, "blockers": [], "candidate_id": "profit_candidate"},
                {"source_wallet": "0x0000000000000000000000000000000000000000", "blockers": []},
            ],
            context,
        )

        assert context["active"] is True
        assert context["next_major_change_action"] == next_major_change_action
        assert context["target_inventory"]["candidate_id"] == "inventory_candidate"
        target_entry = patched[0]
        proof_entry = patched[1]
        profit_entry = patched[2]
        neutral_entry = patched[3]
        assert target_entry["candidate_id"] == "inventory_candidate"
        assert target_entry["candidate_type"] == "MULTI_WALLET_INVENTORY"
        assert context["target_inventory"]["unique_wallets"][0] == inventory_child_wallet
        assert target_entry["source_wallet"] == inventory_child_wallet
        assert target_entry["source_wallets"][:3] == [
            inventory_child_wallet,
            proof_wallet,
            profit_wallet,
        ]
        assert target_entry["development_program_inventory_target_entry"] is True
        assert target_entry["development_program_bridge_focus"] is True
        assert target_entry["development_program_bridge_roles"] == ["multi_wallet_inventory_target"]
        assert target_entry["development_program_target_inventory"]["fallback_filled_buy_count"] == 14
        assert "development_program_inventory_target_needs_current_poll_clob_truth" in target_entry["blockers"]
        assert proof_entry["development_program_bridge_focus"] is True
        assert proof_entry["development_program_bridge_roles"] == ["single_wallet_best_copyable"]
        assert profit_entry["development_program_bridge_roles"] == ["profitable_wallet_copy_efficiency"]
        assert proof_entry["development_program_target_inventory"]["fallback_filled_buy_count"] == 14
        assert "development_program_bridge_pending_current_poll_inventory" in proof_entry["blockers"]
        assert "development_program_bridge_focus" not in neutral_entry


