def test_hotlane_tick_summarizes_current_poll_inventory_bridge_clob_truth():
    from scripts.run_wallet_copy_hotlane_tick import _current_poll_inventory_bridge_burnin_summary

    wallet_a = "0x1111111111111111111111111111111111111111"
    wallet_b = "0x2222222222222222222222222222222222222222"
    wallet_c = "0x3333333333333333333333333333333333333333"
    summary = _current_poll_inventory_bridge_burnin_summary(
        [
            {
                "tick": 1,
                "exact_cohort_probe": {
                    "status": "PASS",
                    "source": "development_program_bridge_candidate",
                    "selected_source": "development_program_bridge_current_poll_inventory_burnin",
                    "candidate_id": "wcp_inventory",
                    "policy_id": "fast_inventory",
                    "cohort_index": 0,
                    "next_cohort_index": 1,
                    "rank": 1,
                    "wallets": [wallet_a, wallet_b],
                    "development_program_stop_doing": [
                        "do_not_count_fallback_inventory_profit_as_live_admissible_progress"
                    ],
                },
                "cohort_probe_tracker": {
                    "hot_path_current_poll_moves": 3,
                    "hot_path_runtime_fresh_buy_events_le_cap": 2,
                    "hot_path_runtime_eligible_wallets": 2,
                    "hot_path_inventory_intents_created": 1,
                    "hot_path_inventory_filled_orders": 1,
                    "hot_path_inventory_rejected_orders": 0,
                    "hot_path_inventory_fill_source_counts": {"clob_book_evidence": 1},
                },
                "cohort_probe_tracker_command": {"ok": True, "returncode": 0},
            },
            {
                "tick": 2,
                "exact_cohort_probe": {
                    "status": "PASS",
                    "source": "development_program_bridge_candidate",
                    "selected_source": "development_program_bridge_current_poll_inventory_burnin",
                    "candidate_id": "wcp_inventory",
                    "cohort_index": 1,
                    "next_cohort_index": 0,
                    "rank": 2,
                    "wallets": [wallet_b, wallet_c],
                },
                "cohort_probe_tracker": {
                    "hot_path_current_poll_moves": 0,
                    "hot_path_runtime_fresh_buy_events_le_cap": 0,
                    "hot_path_runtime_eligible_wallets": 0,
                    "hot_path_inventory_intents_created": 0,
                    "hot_path_inventory_filled_orders": 0,
                    "hot_path_inventory_rejected_orders": 0,
                    "current_poll_zero_current_poll_root_cause": "raw_source_rows_zero",
                    "current_poll_blockers": ["raw_source_rows_zero"],
                },
                "cohort_probe_tracker_command": {"ok": False, "returncode": 1},
            }
        ]
    )

    assert summary["status"] == "PASS"
    assert summary["candidate_id"] == "wcp_inventory"
    assert summary["candidate_specific_clob_truth_attached"] is True
    assert summary["inventory_clob_filled_orders"] == 1
    assert summary["inventory_fallback_filled_orders"] == 0
    assert summary["blockers"] == []
    assert "do_not_count_fallback_inventory_profit_as_live_admissible_progress" in summary["stop_doing"]
    assert summary["attempted_cohort_indices"] == [0, 1]
    assert summary["attempted_cohorts"] == 2
    assert summary["attempted_wallet_count"] == 3
    assert summary["covered_wallets"] == [wallet_a, wallet_b, wallet_c]
    assert summary["attempts_with_current_poll_moves"] == 1
    assert summary["attempts_with_inventory_intents"] == 1
    assert summary["command_failed_attempts"] == 1
    assert summary["attempts"][1]["current_poll_root_cause"] == "raw_source_rows_zero"


