def test_hotlane_tick_summarizes_window_indexed_bridge_data_api_truth(monkeypatch):
    import scripts.run_wallet_copy_hotlane_tick as tick

    wallet_a = "0x1111111111111111111111111111111111111111"
    wallet_b = "0x2222222222222222222222222222222222222222"
    now_s = time.time()
    observed_env: list[dict[str, str | None]] = []

    class FakeWalletHistoryClient:
        def __init__(self, spec, *, timeout_s, retries):
            self.spec = spec
            self.timeout_s = timeout_s
            self.retries = retries
            self.last_fetch_report = {}

        def fetch_events(self, **kwargs):
            observed_env.append(
                {
                    "data": os.environ.get("POLYMARKET_DATA_API_BASE_URL"),
                    "gamma": os.environ.get("POLYMARKET_GAMMA_API_BASE_URL"),
                    "clob": os.environ.get("POLYMARKET_CLOB_API_BASE_URL"),
                }
            )
            self.last_fetch_report = {
                "ingest_status": "PASS",
                "raw_rows": 2,
                "normalized_events": 2,
                "normalized_trade_events": 2,
                "trade_query_keys": kwargs["trade_query_keys"],
                "source_route_status_by_source": {"data_api": "PASS"},
                "source_stop_reasons": {"data_api": "accepted"},
                "source_base_override_counts": {},
            }
            return [
                SimpleNamespace(
                    event_ts=now_s - 5.0,
                    observed_ts=now_s - 4.0,
                    is_buy=True,
                    market_slug="btc-up-down-5m",
                    condition_id="condition-a",
                    outcome="Up",
                    token_id="token-a",
                    size=3.0,
                    price=0.52,
                    usdc_size=1.56,
                ),
                SimpleNamespace(
                    event_ts=now_s - 30.0,
                    observed_ts=now_s - 29.0,
                    is_buy=False,
                    market_slug="btc-up-down-5m",
                    condition_id="condition-a",
                    outcome="Up",
                    token_id="token-a",
                    size=1.0,
                    price=0.51,
                    usdc_size=0.51,
                ),
            ]

    monkeypatch.setenv("POLYMARKET_DATA_API_BASE_URL", "https://stale.invalid")
    monkeypatch.setenv("POLYMARKET_GAMMA_API_BASE_URL", "https://stale.invalid")
    monkeypatch.setenv("POLYMARKET_CLOB_API_BASE_URL", "https://stale.invalid")
    monkeypatch.setattr(tick, "WalletHistoryClient", FakeWalletHistoryClient)
    real_clob = tick.CLOBMarketClient

    class FakeCLOBMarketClient:
        summarize_book = staticmethod(real_clob.summarize_book)

        def __init__(self, *args, **kwargs):
            pass

        def get_book(self, token_id: str):
            return {
                "asset_id": token_id,
                "market": "condition-a",
                "timestamp": now_s,
                "hash": f"book-{token_id}",
                "asks": [{"price": "0.52", "size": "50"}],
                "bids": [{"price": "0.51", "size": "50"}],
            }

    monkeypatch.setattr(tick, "CLOBMarketClient", FakeCLOBMarketClient)

    summary = tick._window_indexed_inventory_bridge_burnin_summary(
        args=SimpleNamespace(
            bridge_window_indexed_data_api=True,
            bridge_window_indexed_limit=10,
            bridge_window_indexed_pages=1,
            bridge_window_indexed_max_event_age_s=120.0,
            bridge_window_indexed_data_api_timeout_s=1.5,
            bridge_window_indexed_data_api_retries=0,
            data_api_trade_query_keys="user,proxyWallet",
            parallel_data_api_sources=True,
        ),
        current_poll_bridge_burnin={
            "candidate_id": "wcp_inventory",
            "candidate_ids": ["wcp_inventory"],
            "policy_id": "fast_inventory",
            "covered_wallets": [wallet_a, wallet_b],
        },
    )

    assert summary["status"] == "PASS"
    assert summary["candidate_id"] == "wcp_inventory"
    assert summary["paper_only"] is True
    assert summary["live_orders_allowed"] is False
    assert summary["data_api_raw_rows"] == 4
    assert summary["raw_rows"] == 4
    assert summary["matching_buy_events"] == 2
    assert summary["multi_wallet_window_groups"] == 1
    assert summary["candidate_specific_window_truth_attached"] is True
    assert summary["source_base_overrides_disabled"] is True
    assert summary["disabled_env_vars"] == [
        "POLYMARKET_CLOB_API_BASE_URL",
        "POLYMARKET_DATA_API_BASE_URL",
        "POLYMARKET_GAMMA_API_BASE_URL",
    ]
    assert observed_env == [
        {"data": None, "gamma": None, "clob": None},
        {"data": None, "gamma": None, "clob": None},
    ]
    lane = summary["continuous_paper_measurement_lane"]
    assert lane["paper_orders"] == 2
    assert lane["paper_fills"] == 2
    assert lane["clob_backed_fill_evidence"] is True
    assert lane["ledger_rows"][0]["source_intent"]["source_event_id"]
    assert os.environ["POLYMARKET_DATA_API_BASE_URL"] == "https://stale.invalid"


