def test_autonomous_repair_admission_tracker_injects_approved_source_route(tmp_path: Path):
    from scripts.run_wallet_copy_autonomous_repair import (
        _approved_source_route_env_overrides,
        _augment_admission_tracker_source_route,
    )

    source_route_state = tmp_path / "source_route.json"
    source_route_state.write_text(
        json.dumps(
            {
                "status": "POLYMARKET_ROUTE_RECOVERED_DEGRADED",
                "measured_base_or_proxy_route_pass": True,
                "operator_live_source_route_approval_id": "unit-approved-route",
                "source_base_overrides": {
                    "data-api.polymarket.com": {
                        "base_url": "http://127.0.0.1:8787/data-api",
                        "configured": True,
                        "env_var": "POLYMARKET_DATA_API_BASE_URL",
                    },
                    "gamma-api.polymarket.com": {
                        "base_url": "http://127.0.0.1:8787/gamma-api",
                        "configured": True,
                        "env_var": "POLYMARKET_GAMMA_API_BASE_URL",
                    },
                },
            }
        ),
        encoding="utf-8",
    )

    env = _approved_source_route_env_overrides(str(source_route_state))
    assert env["POLYMARKET_DATA_API_BASE_URL"] == "http://127.0.0.1:8787/data-api"
    assert env["POLYMARKET_GAMMA_API_BASE_URL"] == "http://127.0.0.1:8787/gamma-api"

    argv, env = _augment_admission_tracker_source_route(
        [
            "python3",
            "scripts/run_wallet_live_tracker.py",
            "--admission-mode",
            "--source-route-state",
            str(source_route_state),
        ]
    )

    assert "--allow-source-base-overrides-in-admission" in argv
    assert env["POLYMARKET_DATA_API_BASE_URL"] == "http://127.0.0.1:8787/data-api"

    source_route_state.write_text(json.dumps({"status": "POLYMARKET_ROUTE_RESET"}), encoding="utf-8")
    argv, env = _augment_admission_tracker_source_route(
        [
            "python3",
            "scripts/run_wallet_live_tracker.py",
            "--admission-mode",
            "--source-route-state",
            str(source_route_state),
        ]
    )
    assert "--allow-source-base-overrides-in-admission" not in argv
    assert env == {}


