def test_orderfilled_direct_cursor_routes_distinct_logs_and_restart_dedupes(tmp_path: Path) -> None:
    from scripts import run_wallet_copy_live_guard as guard

    wallet = "0x1111111111111111111111111111111111111111"
    token = "123"
    gate = tmp_path / "gate.json"
    source = tmp_path / "polygon.jsonl"
    accumulator = tmp_path / "accumulator.json"
    cursor = tmp_path / "cursor.json"
    gate.write_text(
        json.dumps(
            {
                "live_source_wiring_gate_passed": True,
                "unique_resolved_source_events": 100,
                "required_unique_resolved_source_events": 100,
                "token_mapping_missing": 0,
                "identity_market_outcome_parity_violations": 0,
            }
        ),
        encoding="utf-8",
    )
    accumulator.write_text(
        json.dumps(
            {
                "token_metadata_cache": {
                    token: {
                        "market_slug": "btc-updown-5m-1800000000",
                        "condition_id": "0xcondition",
                        "outcome": "Up",
                    }
                }
            }
        ),
        encoding="utf-8",
    )
    base = {
        "event": "polygon_orderfilled_log",
        "selected_wallet": wallet,
        "maker": wallet,
        "taker": "0x2222222222222222222222222222222222222222",
        "transaction_hash": "0xsame",
        "received_at_s": 1_800_000_006.0,
        "block_ts": 1_800_000_005.0,
        "decoded": {"side": "BUY", "asset": token, "price": 0.49, "size": 2.0},
    }
    source.write_text(
        "\n".join(json.dumps({**base, "log_index": index}) for index in (7, 8)) + "\n",
        encoding="utf-8",
    )
    runtime = {"members": [{"source_wallet": wallet, "enabled": True}]}

    first, first_report = guard._active_member_orderfilled_direct_delta(
        polygon_jsonl=source,
        gate_state_path=gate,
        accumulator_state_path=accumulator,
        cursor_state_path=cursor,
        active_set_runtime=runtime,
        now_ts=1_800_000_010.0,
        bootstrap_bytes=4096,
    )
    replay, replay_report = guard._active_member_orderfilled_direct_delta(
        polygon_jsonl=source,
        gate_state_path=gate,
        accumulator_state_path=accumulator,
        cursor_state_path=cursor,
        active_set_runtime=runtime,
        now_ts=1_800_000_011.0,
        bootstrap_bytes=4096,
    )

    assert len(first) == 2
    assert first_report["eligible_rows"] == 2
    assert {row["raw"]["log_index"] for row in first} == {7, 8}
    assert all(row["raw"]["receipt_to_guard_s"] == 4.0 for row in first)
    assert replay == []
    assert replay_report["raw_rows"] == 0


