def test_post_poll_history_delta_dedupes_transaction_identity(tmp_path: Path) -> None:
    from scripts import run_wallet_copy_live_guard as guard

    history = tmp_path / "history.json"
    existing = wallet_event(wallet_name="existing").asdict()
    existing["event_id"] = "existing"
    existing["transaction_hash"] = "0xexisting"
    history.write_text(json.dumps({"events": [existing]}), encoding="utf-8")
    before = guard._history_event_identity_snapshot(history)
    duplicate_tx = {
        **existing,
        "event_id": "duplicate-renamed",
        "source_fingerprint": "different-fingerprint",
    }
    fresh = wallet_event(wallet_name="fresh-dataapi").asdict()
    fresh["event_id"] = "fresh-dataapi"
    fresh["transaction_hash"] = "0xfreshdataapi"
    history.write_text(json.dumps({"events": [existing, duplicate_tx, fresh]}), encoding="utf-8")

    delta = guard._post_poll_history_event_delta(history, before_identities=before)

    assert [row["event_id"] for row in delta] == ["fresh-dataapi"]


