def test_alternate_transport_bridge_skips_protected_first_event_and_submits_exact_survivor(
    monkeypatch,
    tmp_path: Path,
) -> None:
    from scripts import run_wallet_copy_live_guard as guard

    now_ts = 1_800_000_150.0
    wallets = ["0x" + "a" * 40, "0x" + "b" * 40]
    members = [
        {
            "candidate_id": f"candidate-{index}",
            "candidate_type": "SINGLE_WALLET",
            "source_wallet": wallet,
            "policy_id": f"policy-{index}",
            "enabled": True,
            "policy": {
                "policy_id": f"policy-{index}",
                "min_price": 0.25,
                "max_price": 0.50,
                "wallet_fraction": 0.1,
                "max_order_usd": 1.0,
                "min_order_usd": 1.0,
            },
        }
        for index, wallet in enumerate(wallets)
    ]
    events = [
        WalletEvent(
            source_wallet=wallet,
            wallet_name=f"member-{index}",
            row_type="trade",
            action="BUY",
            condition_id=f"condition-{index}",
            market_slug="btc-updown-5m-1800000000",
            outcome="Up",
            price=0.40,
            size=3.0,
            usdc_size=1.2,
            event_ts=now_ts - 2 - index,
            observed_ts=now_ts - 1,
            event_id=f"event-{index}",
            window_start_s=1_800_000_000,
            token_id=f"token-{index}",
        )
        for index, wallet in enumerate(wallets)
    ]
    monkeypatch.setattr(
        guard,
        "_active_set_runtime_member_candidate",
        lambda *_args, **kwargs: {
            "candidate_id": kwargs["candidate_id_pin"],
            "candidate_type": "SINGLE_WALLET",
            "status": "PASS",
            "source_wallet": kwargs["source_wallet_pin"],
        },
    )
    monkeypatch.setattr(guard, "_candidate_pass_gate", lambda *_args, **_kwargs: {"passed": True})
    monkeypatch.setattr(
        guard,
        "_write_live_execution_probe_override",
        lambda *_args, **_kwargs: str(tmp_path / "override.json"),
    )
    monkeypatch.setattr(guard, "atomic_write_json", lambda *_args, **_kwargs: None)
    calls: list[dict] = []
    survivor_intent = {"intent_id": "survivor-intent", "source_wallet": wallets[1]}

    def fake_run(run_args, *, candidate_id: str):
        calls.append(
            {
                "candidate_id": candidate_id,
                "suppressed": bool(getattr(run_args, "suppress_submission", False)),
                "plan": getattr(run_args, "preplanned_plan", None),
            }
        )
        if bool(getattr(run_args, "suppress_submission", False)):
            survivor = candidate_id == "candidate-1"
            return {
                "returncode": 0,
                "stdout_json": {
                    "status": "LIVE_PLAN_SURVIVOR" if survivor else "LIVE_PLAN_PROTECTED_NO_SURVIVOR",
                    "candidate_id": candidate_id,
                    "source_wallet": wallets[int(candidate_id[-1])],
                    "planned_intents": [survivor_intent] if survivor else [],
                    "planned_intent_hash": "exact-hash-1" if survivor else "empty-hash",
                    "planned_token_map": {},
                    "blockers": [] if survivor else ["entry_price_band_gate_filtered_candidate_copy_intents"],
                    "intent_blockers": [] if survivor else ["entry_price_band_gate_filtered_candidate_copy_intents"],
                    "orders_submitted": 0,
                },
            }
        assert run_args.preplanned_plan["planned_intents"] == [survivor_intent]
        assert run_args.preplanned_plan["planned_intent_hash"] == "exact-hash-1"
        return {
            "returncode": 0,
            "stdout_json": {
                "status": "LIVE_EXECUTION_SUBMITTED",
                "candidate_id": candidate_id,
                "source_wallet": wallets[1],
                "orders_submitted": 1,
            },
        }

    monkeypatch.setattr(guard, "_run_fused_live_execution", fake_run)
    args = SimpleNamespace(
        policy_id="incumbent",
        live_orders_allowed=True,
        price_band_decision_min_price=0.0,
        price_band_decision_max_price=0.5,
        min_live_order_usd=1.0,
        profit_state="profit.json",
        history_state="history.json",
        history_window_index="index.json",
        live_arm_state="arm.json",
        live_ledger_state="ledger.json",
        live_ledger_event_log="events.jsonl",
    )

    _stale_args, stale_report = guard._alternate_transport_copyintent_bridge(
        args,
        active_set_runtime={"members": members},
        active_set_rtds_premerge={"matching_events_delta": [event.asdict() for event in events]},
        now_ts=now_ts,
        generation_fence=lambda: False,
    )

    assert stale_report["status"] == "STALE_GENERATION_DISCARDED"
    assert stale_report["stale_generation_discarded"] is True
    assert stale_report["submit_stage_invocations"] == 0
    assert calls == []
    calls.clear()

    _paper_args, paper_report = guard._alternate_transport_copyintent_bridge(
        args,
        active_set_runtime={"members": members},
        active_set_rtds_premerge={"matching_events_delta": [event.asdict() for event in events]},
        now_ts=now_ts,
        generation_fence=lambda: True,
        allow_submit_stage=False,
    )

    assert paper_report["status"] == "PAPER_SURVIVOR_READY_ACTIVATION"
    assert paper_report["post_protection_survivors"] == 1
    assert paper_report["submit_stage_allowed"] is False
    assert paper_report["submit_stage_invocations"] == 0
    assert [call["suppressed"] for call in calls] == [True, True]
    calls.clear()

    routed_args, report = guard._alternate_transport_copyintent_bridge(
        args,
        active_set_runtime={"members": members},
        active_set_rtds_premerge={"matching_events_delta": [event.asdict() for event in events]},
        now_ts=now_ts,
        generation_fence=lambda: True,
    )

    assert report["status"] == "SURVIVOR_SUBMITTED_TO_EXISTING_GUARD"
    assert report["post_protection_survivors"] == 1
    assert report["submit_stage_invocations"] == 1
    assert [call["candidate_id"] for call in calls] == ["candidate-0", "candidate-1", "candidate-1"]
    assert [call["suppressed"] for call in calls] == [True, True, False]
    assert routed_args.candidate_id == "candidate-1"
    assert report["planner_rows"][0]["terminal_stage"] == "PROTECTED_MEASURED_SKIP"
    assert report["planner_rows"][1]["planned_intent_hash"] == "exact-hash-1"
    assert report["generation_fence_checked"] is True


